document.onmousedown = closeElementsOnClick;
function closeElementsOnClick(evt) {
	if (Cyberoam.currentObject != null) {
		var X = 0;
		var Y = 0;
		try {
			if (navigator.appName != "Microsoft Internet Explorer") {
				X = evt.pageX;
				Y = evt.pageY;
			} else {
				X = event.clientX + document.body.scrollLeft;
				Y = event.clientY + document.body.scrollTop;
			}
		} catch (e) { }
		var points = Cyberoam.currentObject.getOffsetPosition();
		if (!(points[0].x < X && points[1].x > X && points[0].y < Y && points[1].y > Y)) {

			Cyberoam.currentObject.hide();
		}
	}
}
