Cyberoam.pageLoad = function (module) {
	if (Cyberoam.pageLayer == 0) {
		Cyberoam.setLabelValue(document.getElementById(Cyberoam.mainFrame));
	} else {
		Cyberoam.setLabelValue(document.getElementById('popup' + Cyberoam.pageLayer));
	}
	if (typeof window['init' + module] === 'function') {
		window['init' + module]();
	}
	if (typeof window['init' + module + 'Theme'] === 'function') {
		window['init' + module + 'Theme']();
	}

	//preGeneratedObject function will only call when confirmDiscard find in any entity of entityObject.
	if (Cyberoam.pageObject[Cyberoam.pageLayer].entityObject) {
		var entityObject = Cyberoam.pageObject[Cyberoam.pageLayer].entityObject;
		for (var i in entityObject) {
			if (entityObject[i].config && entityObject[i].config.confirmDiscard) {
				Cyberoam.pageObject[Cyberoam.pageLayer].preDataObject = Cyberoam.preGeneratedObject(Cyberoam.pageObject[Cyberoam.pageLayer].entityObject, Cyberoam.pageObject[Cyberoam.pageLayer].dataObject);
				//return;
			}
		}
	}

	Cyberoam.setButton();
	Cyberoam.setFocus();
	Cyberoam.setPageTitle();
	Cyberoam.setPageSize();

	//Set mainframe div margin-bottom when fixed footer button available in page.
	if ($(".cp-wrapper #mainframediv")[0])
		$(".cp-wrapper #mainframediv")[0].style.marginBottom = "0px";
	if ($(".footer-btn-pnl").length > 0) {
		if ($(".cp-wrapper #mainframediv")[0])
			$(".cp-wrapper #mainframediv")[0].style.marginBottom = "50px";
	}
};
Cyberoam.setPageTitle = function () {
	var menuDataObj = typeof menu != "undefined" ? menu.currentData && menu.currentData[menu.currentData.length - 1] : undefined;
	if (menuDataObj && (menuDataObj.appController !== "iview" || menuDataObj.tabtype === "setting")) {
		$("#menuLevelDiv").remove();
		$("#timeDiv").remove();
	}
	if (Cyberoam.pageLayer > 0) {
		var obj = document.getElementById("popup" + Cyberoam.pageLayer);
		var forms = obj.getElementsByTagName("form");
		for (var i = 0; i < forms.length; i++) {
			forms[i].onsubmit = function () { return false; };
		}
		if (obj && Cyberoam.pageLayer > 0) {
			var content = Cyberoam.getElementsByClassName("content", obj);
			if (content[0]) {
				content[0].className = "";
			}
			content = Cyberoam.getElementsByClassName("subheader", obj);
			if (content[0]) {
				if (typeof Cyberoam.pageObject[Cyberoam.pageLayer].inlinePopup == "undefined") {
					if (typeof Cyberoam.pageObject[Cyberoam.pageLayer].title != "undefined") {
						content[0].innerText = Cyberoam.pageObject[Cyberoam.pageLayer].title;
					}
					content[0].style.cursor = "move";
					content[0].onmousedown = function (event) {
						dragStart(event, 'popupouter' + Cyberoam.pageLayer);
						var event = new Cyberoam.Event(event);
						event.clearKeyCode();
						return;
					};
				} else {
					content[0].className = "cp-page-title";
					if (typeof Cyberoam.pageObject[Cyberoam.pageLayer].title != "undefined") {
						content[0].innerText = Cyberoam.getTranslatedMSG(Cyberoam.pageObject[Cyberoam.pageLayer].title);
						if (typeof Cyberoam.pageObject[Cyberoam.pageLayer].inlinePopup != "undefined" && Cyberoam.pageObject[Cyberoam.pageLayer].inlinePopup == true) {
							if ($(".cp-page-title").get(0)) {
								$($(".cp-page-title")[0]).remove();
								var title = $('<div class = "cp-page-title" id = "cp-page-title"></div>').text(Cyberoam.getTranslatedMSG(Cyberoam.pageObject[Cyberoam.pageLayer].title));
								$('#topbar-title').prepend(title);
							}
						} else {
							if ($('#topbar-title').find(".cp-page-title").length == 0) {
								if ($(".cp-page-title").get(0)) {
									var title = $('<div class = "cp-page-title" id = "cp-page-title"></div>').text($(".cp-page-title").text())
									$('#topbar-title').prepend(title);
									document.getElementById("cp-page-title").style.display = 'none';
								}
							}
						}
						var titleIndex = 0;
						while ($(".cp-page-title").get(++titleIndex)) {
							$(".cp-page-title").get(titleIndex).style.display = 'none';
						}
					}
				}
			}
		}
	} else {
		var obj = document.getElementById(Cyberoam.mainFrame);
		if (obj !== null) {
			var forms = obj.getElementsByTagName("form");
			for (var i = 0; i < forms.length; i++) {
				forms[i].onsubmit = function () { return false; };
			}
			var content = Cyberoam.getElementsByClassName("subheader", obj);
			if (content[0]) {
				jQuery(content[0]).remove();
			}
		}

		if (document.getElementById("cp-page-title")) {
			var pageTitle = document.getElementById("cp-page-title");
			var pageTitleLbl = "";

			if (pageTitle.children.length == 0 && typeof menu != "undefined" && menuDataObj) {
				pageTitleLbl = typeof menu.getMenuTitle == "function" ? menu.getMenuTitle() : Cyberoam.getTranslatedMSG(menuDataObj.label); // this condition for supporting old-new SFM menu compatibility
			} else if (pageTitle.children.length > 0) {
				pageTitleLbl = pageTitle.childNodes[0].innerText;
			}
			if ($(".cp-page-title").get(0)) {
				$($(".cp-page-title")[0]).remove();
				var title = $('<div class = "cp-page-title" id = "cp-page-title"></div>').text(pageTitleLbl)
				$('#topbar-title').prepend(title);
			}
			var titleIndex = 0;
			while ($(".cp-page-title").get(++titleIndex)) {
				if ($($(".cp-page-title").get(titleIndex)) && $($(".cp-page-title").get(titleIndex))[0])
					$($($(".cp-page-title").get(titleIndex))[0]).remove();
			}
		}

	}
};
Cyberoam.setFocus = function () {
	if (Cyberoam.pageLayer == 0) {
		var object = document.getElementById(Cyberoam.mainFrame);
	} else {
		var object = document.getElementById('popup' + Cyberoam.pageLayer)
	}

	if (object) {
		$(object).find('input, textarea, select')
			.not('input[type=hidden],input[type=submit],input[type=reset],input[type=image],input[type=button]')
			.filter(':enabled:visible:first')
			.focus();
		if (Cyberoam.pageLayer == 0) {
			window.scrollTo(0, 0); //this will reset window scroll position to zero when new page load in mainframe div(e.g. navigate on other tab\menu)
		}
	}
};
