Cyberoam.convertNetmaskToInt = function (subnetmask) {
	var arrSubnetMask = subnetmask.split('.');
	var intRepresentation = Cyberoam.convertIPv4ToInt(subnetmask);//converts ipv4 into an integer format
	var binaryRepresentation = (intRepresentation).toString(2);//Converts the returned integer into binary format
	var count = binaryRepresentation.match(/1/g);
	return count.length;
};

Cyberoam.Address = function (c) {
	this.config = { id: "", title: "", IPType: Cyberoam.Address.IPv4, isMask: false, type: Cyberoam.Address.IPv4, multicast: true, unspecify: true, loopback: true, networkBroadcast: true, networkIP: true, linkLocal: true, broadcast: true, reserved: true, addressList: false, allowAny: false, allowNetmask: false, ipv4Mapping: true, validator: null, getOpcodeValue: null, ip: "", netmask: "", range1: "", range2: "" };
	this.errorStatus = 200;
	for (var key in c) {
		if (typeof this.config[key] != "undefined") {
			this.config[key] = c[key];
		} else {
			Cyberoam.messageBox({message: "Wrong CRController Configuration " + key});
			return;
		}
	}
	if (this.config.type == Cyberoam.Address.All) {
		if (this.config.ip != "" && this.config.ip.indexOf(":") != -1) {
			this.config.IPType = Cyberoam.Address.IPv6;
		} else {
			if (this.config.range1 != "" && this.config.range1.indexOf(":") != -1) {
				this.config.IPType = Cyberoam.Address.IPv6;
			} else
				this.config.IPType = Cyberoam.Address.IPv4;
		}
	} else {
		this.config.IPType = this.config.type;
	}
	this.address = null;
	if (typeof this.config.netmask != "string" && typeof this.config.netmask != "number") {
		var val1 = this.config.netmask();
		this.config.netmask = val1;
	}
	if (this.config.allowNetmask == true) {
		if (this.config.ip.indexOf('/') != "-1") {
			this.config.netmask = this.config.ip.substring(this.config.ip.indexOf('/') + 1, this.config.ip.length);
			this.config.ip = this.config.ip.substring(0, this.config.ip.indexOf('/'));
		}
	}
	if (this.config.IPType == Cyberoam.Address.IPv4) {
		this.address = new Cyberoam.Address.ip4({ address: this.config.ip, netmask: this.config.netmask, multicast: this.config.multicast, unspecify: this.config.unspecify, loopback: this.config.loopback, networkBroadcast: this.config.networkBroadcast, networkIP: this.config.networkIP, linkLocal: this.config.linkLocal, broadcast: this.config.broadcast, reserved: this.config.reserved, addressList: this.config.addressList, allowAny: this.config.allowAny, allowNetmask: this.config.allowNetmask, ipv4Mapping: this.config.ipv4Mapping, range1: this.config.range1, range2: this.config.range2 });
	} else {
		this.address = new Cyberoam.Address.ip6({ address: this.config.ip, netmask: this.config.netmask, multicast: this.config.multicast, unspecify: this.config.unspecify, loopback: this.config.loopback, networkBroadcast: this.config.networkBroadcast, networkIP: this.config.networkIP, linkLocal: this.config.linkLocal, broadcast: this.config.broadcast, reserved: this.config.reserved, addressList: this.config.addressList, allowAny: this.config.allowAny, allowNetmask: this.config.allowNetmask, ipv4Mapping: this.config.ipv4Mapping, range1: this.config.range1, range2: this.config.range2 });
	}

};

Cyberoam.Address.IPv4 = 0;
Cyberoam.Address.IPv6 = 1;
Cyberoam.Address.All = 2;
Cyberoam.Address.multicast = 3;
Cyberoam.Address.loopback = 4;
Cyberoam.Address.unspecified = 1;
Cyberoam.Address.linklocal = 5;
Cyberoam.Address.broadcast = 2;
Cyberoam.Address.reserved = 6;


Cyberoam.Address.prototype.get = function () {
	return { ip: this.address.config.address, netmask: this.address.config.netmask, type: this.config.IPType };
};
Cyberoam.Address.prototype.getErrorStatus = function () {
	return this.errorStatus;
};
Cyberoam.Address.prototype.validate = function () {
	if (!this.address.isValid()) {
		this.errorStatus = this.address.getErrorStatus();
		return false;
	}
	if (this.address.config.netmask != "") {
		if (!this.address.isValidNetmask()) {
			this.errorStatus = this.address.getErrorStatus();
			return false;
		}
	}
	return true;
};
Cyberoam.Address.prototype.validateRange = function () {
	if (!this.address.isValidRange()) {
		return false;
	}
	return true;
};
Cyberoam.Address.prototype.getRange = function () {
	return this.address.getRange();
};
Cyberoam.Address.prototype.set = function (address, netmask) {
	if (this.config.type == Cyberoam.Address.All) {
		if (address != "" && address.indexOf(":") != -1) {
			this.config.IPType = Cyberoam.Address.IPv6;
		} else {
			this.config.IPType = Cyberoam.Address.IPv4;
		}
	} else {
		this.config.IPType = this.config.type;
	}
	if (typeof netmask == "undefined")
		netmask = "";
	if (address.indexOf("/") != -1) {
		netmask = address.split("/")[1];
		address = address.split("/")[0];
	}
	if (this.config.IPType == Cyberoam.Address.IPv4) {
		this.address = new Cyberoam.Address.ip4({ address: address, netmask: netmask, multicast: this.config.multicast, unspecify: this.config.unspecify, loopback: this.config.loopback, networkBroadcast: this.config.networkBroadcast, networkIP: this.config.networkIP, linkLocal: this.config.linkLocal, broadcast: this.config.broadcast, reserved: this.config.reserved, addressList: this.config.addressList, allowAny: this.config.allowAny, allowNetmask: this.config.allowNetmask, ipv4Mapping: this.config.ipv4Mapping });
	} else {
		this.address = new Cyberoam.Address.ip6({ address: address, netmask: netmask, multicast: this.config.multicast, unspecify: this.config.unspecify, loopback: this.config.loopback, networkBroadcast: this.config.networkBroadcast, networkIP: this.config.networkIP, linkLocal: this.config.linkLocal, broadcast: this.config.broadcast, reserved: this.config.reserved, addressList: this.config.addressList, allowAny: this.config.allowAny, allowNetmask: this.config.allowNetmask, ipv4Mapping: this.config.ipv4Mapping });
	}
	if (address != "") {
		if (this.config.isMask) {
			document.getElementById("address_" + this.config.id).value = this.address.config.address;
			document.getElementById("mask_" + this.config.id).value = this.address.config.netmask;
		} else {
			document.getElementById("address_" + this.config.id).value = this.address.config.address + ((this.address.config.netmask != "" && this.address.config.netmask != 'undefined') ? ("/" + this.address.config.netmask) : "");
		}
	}
};
Cyberoam.Address.prototype.create = function () {
	var ele = document.getElementById(this.config.id);
	var entity = this;
	if (entity.config.title == "") {
		if (entity.config.type == Cyberoam.Address.IPv4) {
			entity.config.title = Language.IPv4;
		} else if (entity.config.type == Cyberoam.Address.IPv6) {
			entity.config.title = Language.IPv6;
		}
	}
	var IPElement = Cyberoam.createElement({ tag: "input", type: "text", className: "textboxcss", id: "address_" + this.config.id }, ele);
	IPElement.onblur = function () {
		var address = this.value;
		var netmask = "";
		if (entity.config.type == Cyberoam.Address.All) {
			if (address != "" && address.indexOf(":") != -1) {
				entity.config.IPType = Cyberoam.Address.IPv6;
			} else {
				entity.config.IPType = Cyberoam.Address.IPv4;
			}
		} else {
			entity.config.IPType = entity.config.type;
		}
		if (address.indexOf("/") != -1) {
			netmask = address.split("/")[1];
			address = address.split("/")[0];
		}
		if (entity.config.IPType == Cyberoam.Address.IPv4) {
			entity.address = new Cyberoam.Address.ip4({ address: address, netmask: netmask, multicast: this.config.multicast, unspecify: this.config.unspecify, loopback: this.config.loopback, networkBroadcast: this.config.networkBroadcast, networkIP: this.config.networkIP, linkLocal: this.config.linkLocal, broadcast: this.config.broadcast, reserved: this.config.reserved, addressList: this.config.addressList, allowAny: this.config.allowAny, allowNetmask: this.config.allowNetmask });
		} else {
			entity.address = new Cyberoam.Address.ip6({ address: address, netmask: netmask, multicast: this.config.multicast, unspecify: this.config.unspecify, loopback: this.config.loopback, networkBroadcast: this.config.networkBroadcast, networkIP: this.config.networkIP, linkLocal: this.config.linkLocal, broadcast: this.config.broadcast, reserved: this.config.reserved, addressList: this.config.addressList, allowAny: this.config.allowAny, allowNetmask: this.config.allowNetmask });
		}

	}
	if (this.config.isMask) {
		maskElement = Cyberoam.createElement({ tag: input, className: "textboxcss", id: "mask_" + this.config.id }, ele);
		maskElement.onblur = function () {
			var netmask = this.value;
			entity.address.setMask(netmask);
		}
	}
	this.set(this.config.ip, this.config.netmask);
};
