Cyberoam.Address.ip6.prototype.isIPInRange = function (address, startAddress, endAddress) {
	if (typeof address == "undefined")
		address = this.config.address;
	if (typeof startAddress == "undefined")
		startAddress = this.config.range1;
	if (typeof endAddress == "undefined")
		endAddress = this.config.range2;
	if (!this.isValid(startAddress) || !this.isValid(endAddress) || !this.isValid(address))
		return false;
	if (!this.isValidRange(address, startAddress) && this.isValidRange(address, endAddress)) {
		return true;
	}
	return false;
};
Cyberoam.Address.ip6.prototype.isValidRange = function (startAddress, endAddress) {
	if (typeof startAddress == "undefined")
		startAddress = this.config.range1;
	if (typeof endAddress == "undefined")
		endAddress = this.config.range2;
	if (!this.isValid(startAddress) || !this.isValid(endAddress))
		return false;
	var bestStartAddr = this.bestRepresent(startAddress);
	var bestEndAddr = this.bestRepresent(endAddress);
	var arrStartAddress = bestStartAddr.split(":");
	var arrEndAddress = bestEndAddr.split(":");
	if (Number('0x' + arrStartAddress[0]) < Number('0x' + arrEndAddress[0]))
		return true;
	if (Number('0x' + arrStartAddress[0]) == Number('0x' + arrEndAddress[0])) {
		if (Number('0x' + arrStartAddress[1]) < Number('0x' + arrEndAddress[1]))
			return true;
		if (Number('0x' + arrStartAddress[1]) == Number('0x' + arrEndAddress[1])) {
			if (Number('0x' + arrStartAddress[2]) < Number('0x' + arrEndAddress[2]))
				return true;
			if (Number('0x' + arrStartAddress[2]) == Number('0x' + arrEndAddress[2])) {
				if (Number('0x' + arrStartAddress[3]) < Number('0x' + arrEndAddress[3]))
					return true;
				if (Number('0x' + arrStartAddress[3]) == Number('0x' + arrEndAddress[3])) {
					if (Number('0x' + arrStartAddress[4]) < Number('0x' + arrEndAddress[4]))
						return true;
					if (Number('0x' + arrStartAddress[4]) == Number('0x' + arrEndAddress[4])) {
						if (Number('0x' + arrStartAddress[5]) < Number('0x' + arrEndAddress[5]))
							return true;
						if (Number('0x' + arrStartAddress[5]) == Number('0x' + arrEndAddress[5])) {
							if (Number('0x' + arrStartAddress[6]) < Number('0x' + arrEndAddress[6]))
								return true;
							if (Number('0x' + arrStartAddress[6]) == Number('0x' + arrEndAddress[6])) {
								if (Number('0x' + arrStartAddress[7]) < Number('0x' + arrEndAddress[7]))
									return true;
							}
						}
					}
				}
			}
		}
	}
};
Cyberoam.Address.ip6.prototype.getRange = function (startAddress, endAddress) {
	if (typeof startAddress == "undefined")
		startAddress = this.config.range1;
	if (typeof endAddress == "undefined")
		endAddress = this.config.range2;
	var bestStart = Cyberoam.bestRepresent(startAddress);
	var bestEnd = Cyberoam.bestRepresent(endAddress);
	var startArr = bestStart.split(":");
	var endArr = bestEnd.split(":");
	var count = 0;
	for (var i = 0; i < 8; i++) {
		count += (((Number('0x' + endArr[i]) - Number('0x' + startArr[i])) * (Math.pow(65536, 7 - i))));
	}
	return count + 1;
};
Cyberoam.Address.ip6.prototype.bestRepresent = function (address) {
	return Cyberoam.bestRepresent(address);
};
Cyberoam.binwith2bit = function (bin) {
	for (var i = 0; i < 2 - bin.length; i++) {
		bin = "0" + bin;
	}
	return bin;
};

Cyberoam.getIPv6BitsFromIPv4 = function (address) {
	var addsplit = address.split(".");
	var byte1 = Cyberoam.binwith2bit(parseInt(addsplit[0]).toString(16)) + "" + Cyberoam.binwith2bit(parseInt(addsplit[1]).toString(16));
	var byte2 = Cyberoam.binwith2bit(parseInt(addsplit[2]).toString(16)) + "" + Cyberoam.binwith2bit(parseInt(addsplit[3]).toString(16));
	return byte1 + ":" + byte2;

};
Cyberoam.bestRepresent = function (address) {
	if (address.indexOf('.') != -1) {
		var ipv4address = address.substring(address.lastIndexOf(":") + 1);
		var ipv6address = address.substring(0, address.lastIndexOf(":") + 1);
		address = ipv6address + Cyberoam.getIPv6BitsFromIPv4(ipv4address);
	}
	if (address.indexOf('::') != -1) {
		var arrAddress = address.split("::");
		var a = arrAddress[0];
		var b = arrAddress[1];
		var c = a.split(":");
		var d = b.split(":");
		var maxlen = 8;
		var bestRep = "";
		var i;
		for (i = 0; i < c.length; i++) {
			bestRep += (this.fixLength(c[i], 4) + ":");
		}
		for (var j = 0; j < (8 - (c.length + d.length)); j++ , i++) {
			bestRep += "0000:";
		}
		for (var j = 0; j < d.length; j++ , i++) {
			bestRep += Cyberoam.fixLength(d[j], 4) + ":";
		}
		bestRep = bestRep.substr(0, bestRep.length - 1);
	} else {
		var d = address.split(":");
		var bestRep = "";
		for (var j = 0; j < d.length; j++ , i++) {
			bestRep += Cyberoam.fixLength(d[j], 4) + ":";
		}
		bestRep = bestRep.substr(0, bestRep.length - 1);
	}
	return bestRep;
};
Cyberoam.fixLength = function (s, n) {
	n = (n < 0) ? 0 : n
	s = s.substr(0, n);
	var a = [];
	a.length = n - s.length + 1;
	return "" + a.join('0') + s;
};
Cyberoam.Address.ip6.prototype.fixLength = function (s, n) {
	n = (n < 0) ? 0 : n
	s = s.substr(0, n);
	var a = [];
	a.length = n - s.length + 1;
	return "" + a.join('0') + s;
};
Cyberoam.Address.ip6.prototype.isValidNetmask = function (netmask) {
	var prefix = "";
	if (typeof netmask != "undefined") {
		prefix = netmask;
	} else {
		prefix = this.config.netmask;
	}
	if (prefix == "" || typeof prefix == "undefined") {
		this.errorStatus = 510;
		return false;
	}
	if (isNaN(prefix)) {
		this.errorStatus = 510;
		return false;
	}
	if (typeof prefix == "string") {
		prefix = parseInt(prefix);
	}
	if (typeof prefix != "number") {
		this.errorStatus = 510;
		return false;
	}
	if (prefix < 1 || prefix > 128) {
		this.errorStatus = 510;
		return false;
	}
	return true;
};
Cyberoam.InternetProtocol = function (c) {
	this.config = { id: "", name: "", ipv4tab: false, ipv6tab: false };
	for (var key in c) {
		if (typeof this.config[key] != "undefined") {
			this.config[key] = c[key];
		} else {
			Cyberoam.messageBox({message: "Wrong InternetProtocol Configuration " + key});
			return;
		}
	}
	if (this.config.name == "")
		this.config.name = this.config.id;
}

Cyberoam.InternetProtocol.prototype.create = function () {
	var myObject = this;
	if (myObject.config.id != "") {
		myObject.IPv6Protocol();
		document.getElementById(myObject.config.id).style.display = '';
	}
}
