Cyberoam.CRController = function(c){
	this.config = {id:"",category:[],returnKey:false,label:"",style:"",height:350,width:200,disabled:false,validator:null,getOpcodeValue:null,selectedCategory:"",selectedItems:[],search:true,currentCategoryIndex:0,currentCategory:"",currentItems:[],currentSelectedItem:{},selectAll:false,selectAny:false,returnParam:""};
	categotyDefault = {name:"",label:"",allSelect:false,anySelect:false,addURL:"",addURLTitle:"",image:false,afterOkButton:null,afterCancelButton:null,radioBox:false,checkBox:true,paginator:false,recordPerPage:100,noOfCols:2,width:360,height:280,popupWidth:600,popupHeight:400,data:[],currentPage:1};
	this.searchInterval = null;
	this.lastSearch = "";
	for (var key in c) {
		if(typeof this.config[key] != "undefined"){
			if(key == "category"){
				for(var i=0;i<c.category.length;i++){
					var newCategory = {};
					for (var catKey in categotyDefault) {
						if(c.category[i][catKey])
							newCategory[catKey] = c.category[i][catKey];
						else{
							newCategory[catKey] = categotyDefault[catKey];
						}						
					}
					this.config[key].push(newCategory);
				}
			}else
				this.config[key] = c[key];
		}else{
			 Cyberoam.messageBox({message: "Wrong CRController Configuration "+key});
			 return;
		}
	}
};

Cyberoam.CRController.prototype.create = function(){	
	if(this.id != ""){
		var myobject = this;
		var crconfig = this.config;
		var CRObject= jQuery("#"+crconfig.id);
		CRObject.attr("class","CRController");
		CRObject.width(crconfig.width);
		if(this.config.style != "")
			CRObject.attr("style",this.config.style);
		var spanTag = jQuery("<span style='float:left;width:93%;text-overflow: ellipsis;overflow: hidden;white-space: nowrap;'>"+Cyberoam.getTranslatedMSG(this.config.label)+"</span>").on('click',function(){
			if(document.getElementById("CRbody"+crconfig.id).style.display == "")
				myobject.hide();
			else
				myobject.show();
			document.getElementById("CRSearchText"+crconfig.id).focus();
		}).appendTo(CRObject);
		var button = jQuery("<div class=\"button\"></div>").on('click',function(){
				if(document.getElementById("CRbody"+crconfig.id).style.display == "")
					myobject.hide();
				else
					myobject.show();
				document.getElementById("CRSearchText"+crconfig.id).focus();
		}).appendTo(CRObject);
		var anchorTag = jQuery("<a href=\"javascript:void(0)\" style=\"text-decoration:none;position:relative;height:18px;width:8px\">&nbsp;</a>").appendTo(CRObject);
		anchorTag.on('keyup',function(e){
			var event = new Cyberoam.Event(e);
			if(event.getKeyCode() == 0 || event.getKeyCode() == 32){
				if(document.getElementById("CRbody"+crconfig.id).style.display == "")
					myobject.hide();
				else
					myobject.show();
			}
			document.getElementById("CRSearchText"+crconfig.id).focus();
		});
		anchorTag.on('click',function(e){
			var event = new Cyberoam.Event(e);
			if(event.getKeyCode() == 0 || event.getKeyCode() == 32){
				if(document.getElementById("CRbody"+crconfig.id).style.display == "")
					myobject.hide();
				else
					myobject.show();
			}
			document.getElementById("CRSearchText"+crconfig.id).focus();
		});
		//jQuery("&nbsp</a>")
		var CRBody = jQuery("<div id=CRbody"+crconfig.id+" layer='"+Cyberoam.pageLayer+"' class=\"CRController_body\" style='display:none'></div>").appendTo(document.body);			
		if(crconfig.category.length > 1){
			var table = jQuery("<table width=\"90%\" height=\"28px\" align=\"center\" cellspacing=0 cellpadding=0></table>").appendTo(CRBody);
			var tr = jQuery("<tr></tr>").appendTo(table);
			for(var i=0;i<crconfig.category.length;i++){
				var td = jQuery("<td align=center>"+crconfig.category[i].label+"</td>").appendTo(tr);
				jQuery("<input type=\"radio\" name=\"catrdo"+crconfig.id+"\" value='"+crconfig.category[i].name+"' id=\"category"+crconfig.id+crconfig.category[i].name+"\"/>").on('click',function(){if(this.value != myobject.config.selectedCategory){myobject.setRecord(this.value);}else{myobject.setCategory(this.value,myobject.config.selectedItems);}myobject.show();}).prependTo(td);
				if(typeof crconfig.selectedCategory != "undefined" && crconfig.selectedCategory == crconfig.category[i].name)
					crconfig.currentCategoryIndex = i;
			}
			if(typeof crconfig.selectedCategory == "undefined")
				crconfig.selectedCategory = crconfig.category[0].name;;
		}else{
			crconfig.selectedCategory = crconfig.category[0].name;
			crconfig.currentCategoryIndex = 0;
		}
		if(crconfig.search){
			var searchDiv = jQuery("<div style='width:100%;background:#FFF;' align='center'></div>").appendTo(CRBody);
			jQuery("<input type=\"text\" class=\"CRsearchtext\" id='CRSearchText"+this.config.id+"'/>").on('keyup',function(){ myobject.search(this)}).appendTo(searchDiv);
		}
		jQuery("<div id=\"CRControllerData"+crconfig.id+"\" style='overflow:auto;'><div style='height:100px'></div></div>").appendTo(CRBody);
		var buttonDiv = jQuery("<div id=\"CRControllerButton"+crconfig.id+"\" align=\"center\"></div>").appendTo(CRBody);
		jQuery('<input type="button" class="inputbutton" value="<<" />').on('click', function(){ myobject.firstPage()}).appendTo(buttonDiv);
		jQuery('<input type="button" class="inputbutton" value="<" />').on('click',function(){ myobject.prevPage()}).appendTo(buttonDiv);
		jQuery('<input type="button" class="inputbutton" value="'+Language.OkCC+'" />').on('click',function(){ myobject.CRControllerOk()}).appendTo(buttonDiv);
		jQuery('<input type="button" class="inputbutton" value="'+Language.Cancel+'" />').on('click',function(){ myobject.CRControllerCancel()}).appendTo(buttonDiv);
		jQuery('<input type="button" class="inputbutton" value=">" />').on('click',function(){ myobject.nextPage()}).appendTo(buttonDiv);
		jQuery('<input type="button" class="inputbutton" value=">>" />').on('click',function(){ myobject.lastPage()}).appendTo(buttonDiv);
		if(crconfig.selectedItems == undefined)
			crconfig.selectedItems = [];
		if(crconfig.selectedItems == [] || crconfig.selectedItems=="")
			this.setRecord(crconfig.category[0].name);
		else{
			if(typeof crconfig.selectedItems == "object")
				this.setCategory(crconfig.selectedCategory,crconfig.selectedItems);
			else{
				crconfig.selectedItems = new Array(crconfig.selectedItems+"");
				this.setCategory(crconfig.selectedCategory,crconfig.selectedItems);
			}
		}
	}
}
Cyberoam.CRController.prototype.disabled = function(value){
	this.config.disabled = value;
	if(value == true)
		jQuery("#"+this.config.id).attr("class","CRController_disabled");
	else
		jQuery("#"+this.config.id).attr("class","CRController");
}
Cyberoam.CRController.prototype.isDisabled = function(){
	return this.config.disabled;
}
Cyberoam.CRController.prototype.getSelectedLabels = function(){
	var labels = [];
	for(var i=0;i<this.config.selectedItems.length;i++){
		if(this.config.selectedItems[i] == "Any")
			return "Any";
		if(typeof this.config.currentSelectedItem[this.config.selectedItems[i]] != "undefined")
			labels.push(this.config.currentSelectedItem[this.config.selectedItems[i]].label);
	}
	return labels;
}
Cyberoam.CRController.prototype.getSelectedValuesByParam = function(param){
	var values = [];
	for(var i=0;i<this.config.selectedItems.length;i++){
		if(this.config.selectedItems[i] == "Any")
			return "Any";
		if(typeof this.config.currentItems[this.config.selectedItems[i]] != "undefined")
			values.push(this.config.currentItems[this.config.selectedItems[i]][param]);
	}
	return values;
}
Cyberoam.CRController.prototype.getSelectedKeys = function(){
	var keys = [];
	for(var i=0;i<this.config.selectedItems.length;i++){
		if(this.config.selectedItems[i] == "Any")
			return "Any";
		keys.push(this.config.selectedItems[i]);
	}
	return keys;
}
Cyberoam.CRController.prototype.getSelectedCategory = function(){
	return this.config.selectedCategory;
}
Cyberoam.CRController.prototype.setCategory = function(name,record){	
	var crconfig = this.config;
	crconfig.selectedItems = record;
	crconfig.selectedCategory = name;
	for(var i=0;i<crconfig.category.length;i++)
		if(crconfig.category[i].name == name){
			crconfig.currentCategoryIndex = i;
			break;
		}
	var data = crconfig.category[crconfig.currentCategoryIndex].data;
	this.config.currentItems = {};
	this.config.currentItems.length = 0;
	for(var obj in data){
		this.config.currentItems[obj] = Cyberoam.clone(data[obj]);
		this.config.currentItems[obj].selected = false;
		this.config.currentItems.length++;
	}
	var count = 0;
	var selectHTML = [];
	if(crconfig.category[crconfig.currentCategoryIndex].radiobox==false && data.length-1 == crconfig.selectedItems.length){
		crconfig.selectAll = true;
		selectHTML.push("All "+crconfig.category[crconfig.currentCategoryIndex].label);
	}
	if(!crconfig.selectAll){
		for(var i=0;i<crconfig.selectedItems.length;i++){
			if(crconfig.selectedItems[i]!="Any"){
				if(typeof this.config.currentItems[crconfig.selectedItems[i]] != "undefined")
					this.config.currentItems[crconfig.selectedItems[i]].selected = true;
				if(typeof data[crconfig.selectedItems[i]] != "undefined"){
					if(typeof data[crconfig.selectedItems[i]].label == "undefined")
						selectHTML.push(crconfig.selectedItems[i]);
					else
						selectHTML.push(data[crconfig.selectedItems[i]].label);
				}
			}else{
				selectHTML.push("Any");
			}
				
		}
	}
	if(this.config.selectedItems[0] && this.config.selectedItems[0]=="Any"){
		selectHTML = [];
		selectHTML.push("Any "+crconfig.category[crconfig.currentCategoryIndex].label);
		this.config.selectAny = true;
	}
	if(crconfig.category[crconfig.currentCategoryIndex].radioBox==true){
		var CRControllerData = jQuery("#CRControllerData"+this.config.id);
		CRControllerData.empty();
	}
	this.setRecord(crconfig.selectedCategory,false);
	
	if(crconfig.selectAll){
		selectHTML = [];
		selectHTML.push("All "+crconfig.category[crconfig.currentCategoryIndex].label);
	}
	if(selectHTML.length == 0)
		selectHTML.push(this.config.label);
	
	if (selectHTML.toString().indexOf("Language.") != -1 || selectHTML.toString().indexOf("Message.") != -1)
		selectHTML = selectHTMLTitle = Cyberoam.getTranslatedMSG(selectHTML.toString());
	else
		selectHTML = selectHTMLTitle = selectHTML.toString();
/*	if(selectHTMLTitle.length > 25)
		selectHTMLTitle = selectHTMLTitle.substring(0,25)+"...";*/
	document.getElementById(this.config.id).childNodes[0].innerHTML = "";
	document.getElementById(this.config.id).childNodes[0].appendChild(document.createTextNode(selectHTMLTitle));
	document.getElementById(this.config.id).childNodes[0].title = selectHTML.toString();
};
Cyberoam.CRController.prototype.afterRecordSet = function(name){
	var crconfig = this.config;
	for(var i=0;i<crconfig.category.length;i++)
		if(crconfig.category[i].name == name){
			crconfig.currentCategoryIndex = i;
			break;
		}
	var data = crconfig.category[crconfig.currentCategoryIndex].data;
	if(crconfig.category[crconfig.currentCategoryIndex].afterOkButton != null){
		crconfig.category[crconfig.currentCategoryIndex].afterOkButton(this);
	}

};
Cyberoam.CRController.prototype.CRControllerOk = function(){
	
	var category = this.config.category[this.config.currentCategoryIndex];
	this.config.selectedCategory = this.config.currentCategory;
	this.config.selectedItems = [];
	var chkRemainItems={};
	var selectHTML = [];
	if(document.getElementById("crany"+this.config.id) && document.getElementById("crany"+this.config.id).checked){
		this.config.selectedItems = ["Any"];
		selectHTML.push("Any "+category.label);
		this.config.selectAny = true;
	}else{
		var elements = [];
		if(category.radioBox)
			elements = document.getElementsByName("radio"+this.config.id);
		else
			elements = document.getElementsByName("chk"+this.config.id);
		
		for(var i=0;i<elements.length;i++){
			if(elements[i].checked){
				selectHTML.push(elements[i].getAttribute("label"));
				this.config.selectedItems.push(elements[i].getAttribute("key"));
				chkRemainItems[elements[i].getAttribute("key")]={label:elements[i].getAttribute("label")};
			}else{
				this.config.currentItems[elements[i].getAttribute("key")].selected = false;
			}
		}
		
		for(var i in this.config.currentSelectedItem){
			if(typeof chkRemainItems[i] == "undefined"){
				selectHTML.push(this.config.currentSelectedItem[i].label);
				this.config.selectedItems.push(i);
			}
		}
		
		this.config.selectAny = false;
	}
	if(category.radioBox==false && document.getElementById("crSelecteAll"+this.config.id) && document.getElementById("crSelecteAll"+this.config.id).checked){
		selectHTML = [];
		selectHTML.push("All "+category.label);
	}
	if(selectHTML.length == 0)
		selectHTML.push(this.config.label);
	
	if (selectHTML.toString().indexOf("Language.") != -1 || selectHTML.toString().indexOf("Message.") != -1)
		selectHTML = selectHTMLTitle = Cyberoam.getTranslatedMSG(selectHTML.toString());
	else
		selectHTML = selectHTMLTitle = selectHTML.toString();
/*	if(selectHTMLTitle.length > 25)
		selectHTMLTitle = selectHTMLTitle.substring(0,25)+"...";*/
	document.getElementById(this.config.id).childNodes[0].innerHTML = "";
	document.getElementById(this.config.id).childNodes[0].appendChild(document.createTextNode(selectHTMLTitle));
	document.getElementById(this.config.id).childNodes[0].title = selectHTML.toString();
	document.getElementById(this.config.id).className = "CRController";
	if(category.afterOkButton != null){
		category.afterOkButton(this);
	}
	document.getElementById("CRbody"+this.config.id).style.display="none";
	mainconfig = this.config;
	setTimeout(function(){document.getElementById(mainconfig.id).childNodes[2].focus();},1);
	Cyberoam.currentObject = null;	
}
Cyberoam.CRController.prototype.CRControllerCancel = function(){
document.getElementById(this.config.id).childNodes[2].focus();
	if(this.config.selectedCategory != ""){
		this.config.currentSelectedItem={};
		var CRControllerData = jQuery("#CRControllerData"+this.config.id);
		CRControllerData.empty();
		this.setCategory(this.config.selectedCategory,this.config.selectedItems);
		if(this.config.category[this.config.currentCategoryIndex].afterCancelButton != null){
			this.config.category[this.config.currentCategoryIndex].afterCancelButton(this);
		}
		document.getElementById(this.config.id).className = "CRController";
	}
	document.getElementById("CRbody"+this.config.id).style.display="none";
	Cyberoam.currentObject = null;
}
Cyberoam.CRController.prototype.search = function(object){
	var record = this.config.currentItems;
	var myobject = this;
		if(this.searchInterval != null)
		clearTimeout(this.searchInterval);
		this.searchInterval = setTimeout(function(){myobject.searchProcess(object.value)},500);
}
Cyberoam.CRController.prototype.searchProcess = function(val){
var category = this.config.category[this.config.currentCategoryIndex];
			var arr = [];
			val = val.trim();
			if(val == ""){
				if(this.lastSearch.length ==  val.length)
					return;
				var data = category.data;
				this.config.currentItems = {};
				this.config.currentItems.length = 0;
				for(var obj in data){
					if(obj=="length" || obj=="constructor")
						continue;
					this.config.currentItems[obj] = Cyberoam.clone(data[obj]);
					this.config.currentItems[obj].selected = false;
					this.config.currentItems.length++;
				}
			}else{
				val = val.toLowerCase();
				if(this.lastSearch.length <  val.length){ 
					arr = this.config.currentItems;
				}else{
					arr = category.data;
				}
				this.config.currentItems = {};
				this.config.currentItems.length = 0;
				var containsSerach = new Object();
				for(var i in arr){
					if(i=="length" || i=="constructor")
						continue;
					if (arr[i].label.toString().indexOf("Language.") != -1 || arr[i].label.toString().indexOf("Message.") != -1)
						arr[i].label = Cyberoam.getTranslatedMSG(arr[i].label);
					if(document.getElementById("chk"+this.config.id+"_"+i) && document.getElementById("chk"+this.config.id+"_"+i).checked){
						this.config.currentSelectedItem[i]=arr[i];
					}
					if(arr[i].label.toLowerCase().indexOf(val) == 0 || ( arr[i].searchLabel && arr[i].searchLabel.toLowerCase().indexOf(val) == 0) && document.getElementById("chk"+this.config.id+"_"+i) && document.getElementById("chk"+this.config.id+"_"+i).checked){
						this.config.currentItems[i] = arr[i];
						this.config.currentItems.length++;
					}else if(arr[i].label.toLowerCase().indexOf(val) == 0 || ( arr[i].searchLabel && arr[i].searchLabel.toLowerCase().indexOf(val) == 0) ){
						this.config.currentItems[i] = arr[i];
						this.config.currentItems[i].selected = false;
						this.config.currentItems.length++;
					}else if(arr[i].label.toLowerCase().indexOf(val) > 0 || ( arr[i].searchLabel && arr[i].searchLabel.toLowerCase().indexOf(val) > 0) ){
						containsSerach[i] = arr[i];
					}
					
				}
				for(var j in containsSerach){
					this.config.currentItems[j] = containsSerach[j];
					this.config.currentItems[j].selected = false;
					this.config.currentItems.length++;
				}
			}
			this.lastSearch = val;
			category.currentPage = 1;
			this.generateData();
}

Cyberoam.CRController.prototype.firstPage = function(object){
	var category = this.config.category[this.config.currentCategoryIndex];
	if(category.currentPage != 1){
		category.currentPage = 1;
		this.generateData();
	}
}
Cyberoam.CRController.prototype.prevPage = function(object){
	var category = this.config.category[this.config.currentCategoryIndex];
	if(category.currentPage != 1){
		category.currentPage--;
		this.generateData();
	}
}
Cyberoam.CRController.prototype.nextPage = function(object){
	var category = this.config.category[this.config.currentCategoryIndex];
	var totalPage = parseInt(this.config.currentItems.length/category.recordPerPage)+1;
	if(category.currentPage != totalPage)
		category.currentPage++;
	this.generateData();
}
Cyberoam.CRController.prototype.lastPage = function(object){
	var category = this.config.category[this.config.currentCategoryIndex];
	category.currentPage = parseInt(this.config.currentItems.length/category.recordPerPage)+1;
	this.generateData();
}
Cyberoam.CRController.prototype.setRecord = function(name,flag){
	var elements = [];
	this.config.currentSelectedItem={};
	elements = document.getElementsByName("chk"+this.config.id);			
	for(var i=0;i<elements.length;i++){
		elements[i].checked = false;
	}
	var object = document.getElementById("category"+this.config.id+name);
	document.getElementById("CRSearchText"+this.config.id).value = "";
	if(object){		
		object.checked = true;
		var parentTR = object.parentNode.parentNode;
		for(var i=0;i<parentTR.childNodes.length;i++){
			if(parentTR.childNodes[i] == object.parentNode){
					jQuery(parentTR.childNodes[i]).attr("class","catselected");
				this.config.currentCategoryIndex = i;
				if(typeof flag == "undefined" || flag == true){
					var data = this.config.category[this.config.currentCategoryIndex].data;
					this.config.currentItems = {};
					this.config.currentItems.length = 0;
					for(var obj in data){
						this.config.currentItems[obj] = Cyberoam.clone(data[obj]);
						this.config.currentItems[obj].selected = false;
						this.config.currentItems.length++;
					}
				}
			}else{
					jQuery(parentTR.childNodes[i]).attr("class","")
			}
		}
		
		
	}else{
		if(typeof flag == "undefined" || flag == true){
			var data = this.config.category[0].data;
			this.config.currentItems = {};
			this.config.currentItems.length = 0;
			for(var obj in data){
				this.config.currentItems[obj] = Cyberoam.clone(data[obj]);
				this.config.currentItems[obj].selected = false;
				this.config.currentItems.length++;
			}
		}
	}
	this.config.currentCategory = name;
	this.config.selectAny = false;
	this.config.selectAll = false;
	
	if(this.config.currentCategory == this.config.selectedCategory && this.config.selectedItems[0] && this.config.selectedItems[0]=="Any")
		this.config.selectAny = true;
	if(this.config.currentCategory == this.config.selectedCategory && this.config.selectedItems.length > 1 && this.config.currentItems.length == this.config.selectedItems.length)
		this.config.selectAll = true;
	
	var buttons = document.getElementById("CRControllerButton"+this.config.id).getElementsByTagName("input");
	if(this.config.category[this.config.currentCategoryIndex].paginator){
		buttons[0].style.display = "";
		buttons[1].style.display = "";
		buttons[4].style.display = "";
		buttons[5].style.display = "";
	}else{
		buttons[0].style.display = "none";
		buttons[1].style.display = "none";
		buttons[4].style.display = "none";
		buttons[5].style.display = "none";
	}
	this.generateData();
}

Cyberoam.CRController.prototype.generateData = function(){
	var category = this.config.category[this.config.currentCategoryIndex];
	var mainObject = this.config;
	var start = 0;
	var thisObject = this;
	var end = this.config.currentItems.length;
	if(category.paginator){
		start = (category.currentPage - 1)*category.recordPerPage;
		end = category.currentPage*category.recordPerPage;
		if(end > this.config.currentItems.length)
			end = this.config.currentItems.length;
	}

	var tableMainObject = Cyberoam.createElement({tag:"table"});
	tableMainObject.style.width = "100%";
	var tableObject = Cyberoam.createElement({tag:"tbody"},tableMainObject);
	var column = 1;
	if(category.allSelect){
		trObject = Cyberoam.createElement({tag:"tr"},tableObject);
		tdObject = Cyberoam.createElement({tag:"td"},trObject);
		inputObject = Cyberoam.createElement({tag:"input",type:"checkbox",id:"crSelecteAll"+this.config.id},tdObject);
		if(this.config.selectAll)
			inputObject.setAttribute("checked","checked");
		var span = Cyberoam.createElement({tag:"span"},tdObject);
		span.style.overflow="hidden";
		span.style.width="100%";
		span.style.whiteSpace="nowrap";
		span.style.textOverflow="ellipsis";
		span.appendChild(document.createTextNode(Language.SelectAll));		
		column++;
	}else if(category.anySelect){
		trObject = Cyberoam.createElement({tag:"tr"},tableObject);
		tdObject = Cyberoam.createElement({tag:"td"},trObject);
		inputObject = Cyberoam.createElement({tag:"input",type:"checkbox",id:"crany"+this.config.id},tdObject);
		if(this.config.selectAny)
			inputObject.setAttribute("checked","checked");
		var span = Cyberoam.createElement({tag:"span"},tdObject);
		span.style.overflow="hidden";
		span.style.width="100%";
		span.style.whiteSpace="nowrap";
		span.style.textOverflow="ellipsis";
		span.appendChild(document.createTextNode(Language.Any));		
		column++;
	}
	if(column==1){
		trObject = Cyberoam.createElement({tag:"tr"},tableObject);
	}
	category.addURL = Cyberoam.getURL(category.addURL,'CRController',this.config.id);
	if(category.addURL != "" && !Cyberoam.isCCC){
		tdObject = Cyberoam.createElement({tag:"td",colspan:2},trObject);
		divObject = Cyberoam.createElement({tag:"div",className:"CRControllerAddButton"},tdObject);
		divObject.onclick = function(){
			Cyberoam.showPopup({URL:category.addURL,title:Cyberoam.getTranslatedMSG(category.addURLTitle),width:category.popupWidth,height:category.popupHeight});
		}
		uObject = Cyberoam.createElement({tag:"u",colspan:2},divObject);
		uObject.appendChild(document.createTextNode(Language.Add+" "+category.label));
	}else{
		tdObject = Cyberoam.createElement({tag:"td",colspan:2},trObject);
	}
	column = 1;

	this.createOptions = function(key,object,selected,disabled){
		if(disabled)
			disabled = "disabled=disabled";
		if(column == 1)
			trObject = Cyberoam.createElement({tag:"tr"},tableObject);
		
		var label = object.label;
		if(typeof label == "undefined"){
			label = key;
			object.label = key;			
		}
		if (label.indexOf("Language.") != -1 || label.indexOf("Message.") != -1)
			object.label = Cyberoam.getTranslatedMSG(label);
		else
			object.label = label;
		/*if(displayLabel.length > 25){
			displayLabel = displayLabel.substring(0,23)+"...";
		}*/
		tdObject = Cyberoam.createElement({tag:"td",title:object.label},trObject);
		tdObject.style.width=(100/category.noOfCols)+"%";
		if(category.radioBox){			
			inputObject = Cyberoam.createElement({tag:"input",type:"radio",name:"radio"+this.config.id,id:"chk"+this.config.id+"_"+key},tdObject);
			if(typeof mainObject.currentSelectedItem[key] != "undefined"){
				inputObject.setAttribute("checked","checked");
				}else if(selected && typeof mainObject.currentSelectedItem[key] == "undefined"){
				mainObject.currentSelectedItem[key]={label:object.label};
			}
			inputObject.onclick = function(e){
				var radiobuttonWinEvent=e?e:window.event;			
				var clickedCRRadioButton = e?e.target:radiobuttonWinEvent.srcElement;
				var clickedCRRadioButtonKey=clickedCRRadioButton.getAttribute("key");
				var clickedCRRadioButtonLabel=clickedCRRadioButton.getAttribute("label");
				mainObject.currentSelectedItem={};
				if(clickedCRRadioButton.checked){
					mainObject.currentSelectedItem[clickedCRRadioButtonKey]={label:clickedCRRadioButtonLabel};
				}
				thisObject.CRControllerOk()
				};
			if(navigator.userAgent.indexOf("MSIE 7.0") > -1){ // Internet Explorer test (needs to be modified for IE8)
   		 		inputObject.mergeAttributes(document.createElement("<INPUT name='" + "radio"+this.config.id + "' id='"+"chk"+this.config.id+"_"+key+"' />"), false);
  			}
		}else{
			inputObject = Cyberoam.createElement({tag:"input",type:"checkbox",name:"chk"+this.config.id,id:"chk"+this.config.id+"_"+key},tdObject);
			if(typeof mainObject.currentSelectedItem[key] != "undefined"){
				inputObject.setAttribute("checked","checked");
			}else if(selected && typeof mainObject.currentSelectedItem[key] == "undefined"){
				mainObject.currentSelectedItem[key]={label:object.label};
			}
			inputObject.onclick = function(e){
				var checkboxWinEvent=e?e:window.event;			
				var clickedCRCheckbox = e?e.target:checkboxWinEvent.srcElement;
				var clickedCRCheckboxKey=clickedCRCheckbox.getAttribute("key");
				var clickedCRCheckboxLabel=clickedCRCheckbox.getAttribute("label");
				if(document.getElementById("crSelecteAll"+mainObject.id)){
					document.getElementById("crSelecteAll"+mainObject.id).checked=false;
				}
				if(clickedCRCheckbox.checked){
					mainObject.currentSelectedItem[clickedCRCheckboxKey]={label:clickedCRCheckboxLabel};
				}else{
					delete mainObject.currentSelectedItem[clickedCRCheckboxKey];
				}
			};
			if(navigator.userAgent.indexOf("MSIE 7.0") > -1){ // Internet Explorer test (needs to be modified for IE8)
   		 		inputObject.mergeAttributes(document.createElement("<INPUT name='" + "chk"+this.config.id + "' id='"+"chk"+this.config.id+"_"+key+"' />"), false);
  			}
		}
		inputObject.setAttribute("key",key);
		inputObject.setAttribute("label",object.label);
		if(Cyberoam.isIE)
			inputObject.style.styleFloat = "left";
		else
			inputObject.style.cssFloat = "left";
		if(selected)
			inputObject.setAttribute("checked","checked");
		if(disabled)
			inputObject.setAttribute("disabled","disabled");
		
		var span = Cyberoam.createElement({tag:"div"},tdObject);
		span.style.overflow="hidden";
		span.style.width=((parseInt(category.width)/category.noOfCols) - 46)+"px";
		span.style.whiteSpace="nowrap";
		span.style.paddingTop = "2px";
		span.style.textOverflow="ellipsis";
		span.style.height="15px";
		span.appendChild(document.createTextNode(object.label));	
		
		if(column == category.noOfCols){
			column = 0;
		}
		column++;
	};
	var cnt = 0;
	for(var i in this.config.currentItems){			
		if(this.config.currentItems[i].selected == true || ((document.getElementById("chk"+this.config.id+"_"+i) && document.getElementById("chk"+this.config.id+"_"+i).checked) && this.config.selectAny != true)){
			this.createOptions(i,this.config.currentItems[i],true,false);
			continue;
		}
		if(cnt < start){
			cnt++;
			continue;
		}
		if(cnt > end){
			cnt++;
			continue;
		}
		if(i=="length" || i=="constructor")
			continue;
		if(this.config.selectAll)
			this.createOptions(i,this.config.currentItems[i],true,false);
		else if(this.config.selectAny)
			this.createOptions(i,this.config.currentItems[i],false,true);
		else 
			this.createOptions(i,this.config.currentItems[i],false,false);
		cnt++;
	}
	if(column != 0)
		for(;column<category.noOfCols;column++)
			tdObject = Cyberoam.createElement({tag:"td"},trObject);		
	else if(category.noOfCols == colimn)
		tdObject = Cyberoam.createElement({tag:"td"},trObject);
	/*finalList.push("</table>");*/
	var CRControllerData = jQuery("#CRControllerData"+this.config.id);
	CRControllerData.empty();
	CRControllerData.append(tableMainObject);

	
	if(category.allSelect){
		jQuery( document.getElementById("crSelecteAll"+this.config.id)).on('click',function(){
			var elements = [];
			elements = document.getElementsByName("chk"+mainObject.id);			
			for(var i=0;i<elements.length;i++){
				elements[i].checked = this.checked;
				var clickedCRCheckboxKey=elements[i].getAttribute("key");
				var clickedCRCheckboxLabel=elements[i].getAttribute("label");
				if(this.checked){
					mainObject.currentSelectedItem[clickedCRCheckboxKey]={label:clickedCRCheckboxLabel};
				}else{
					delete mainObject.currentSelectedItem[clickedCRCheckboxKey];
				}
			}
		})
	}else if(category.anySelect){
		jQuery(document.getElementById("crany"+this.config.id)).on('click',function(){
			if(this.checked == true)
				mainObject.selectAny = true;
			else
				mainObject.selectAny = false;
			var elements = [];
			if(category.radioBox)
				elements = document.getElementsByName("radio"+mainObject.id);
			else
				elements = document.getElementsByName("chk"+mainObject.id);
			for(var i=0;i<elements.length;i++){
				elements[i].disabled = this.checked;
			}
		})
	}

	document.getElementById("CRbody"+mainObject.id).style.width = category.width+"px";
	document.getElementById("CRControllerData"+mainObject.id).style.height = "auto";	

	if(jQuery("#CRControllerData"+mainObject.id).width() >= category.width)
		document.getElementById("CRbody"+mainObject.id).style.width = category.width;
	if(jQuery("#CRControllerData"+mainObject.id).height() >= category.height){
		document.getElementById("CRControllerData"+mainObject.id).style.height = (category.height-80)+"px";
	}else{
		document.getElementById("CRControllerData"+mainObject.id).style.height = "auto";
	}
	var CRObject = jQuery("#"+this.config.id);	
	document.getElementById("CRbody"+this.config.id).style.top = (CRObject.offset().top+20)+"px";
	if((CRObject.offset().top+30+jQuery("#CRbody"+this.config.id).height()) > (document.body.clientHeight - 30))
		document.getElementById("CRbody"+this.config.id).style.top = (parseInt(document.getElementById("CRbody"+this.config.id).style.top)- ((CRObject.offset().top+30+jQuery("#CRbody"+this.config.id).height()) - (document.body.clientHeight - 30)))+"px";
	
	document.getElementById("CRbody"+this.config.id).style.left = (CRObject.offset().left)+"px";
	if((CRObject.offset().left+jQuery("#CRbody"+this.config.id).width()) > document.body.clientWidth)
		document.getElementById("CRbody"+this.config.id).style.left = (parseInt(document.getElementById("CRbody"+this.config.id).style.left) - ((CRObject.offset().left+jQuery("#CRbody"+this.config.id).width()) - document.body.clientWidth))+"px";
	
}
Cyberoam.CRController.prototype.show = function(){
	if(!this.config.disabled){
		var CRObject = jQuery("#"+this.config.id);		
		CRObject.addClass("CRController_open");
		if(Cyberoam.pageLayer > 0)
			document.getElementById("CRbody"+this.config.id).style.zIndex = Cyberoam.pageLayer*200 + 5;
		document.getElementById("CRbody"+this.config.id).style.display="";
		var mainObject = this.config;
		var category = this.config.category[this.config.currentCategoryIndex];
		if(jQuery("#CRControllerData"+mainObject.id).width() > category.width)
			document.getElementById("CRbody"+mainObject.id).style.width = jQuery("#CRControllerData"+mainObject.id).width()+"px";
		else
			document.getElementById("CRbody"+mainObject.id).style.width = category.width;
		if(document.getElementById("CRControllerData"+mainObject.id).offsetHeight != 0 && document.getElementById("CRControllerData"+mainObject.id).offsetHeight < category.height)
			document.getElementById("CRControllerData"+mainObject.id).style.height = (document.getElementById("CRControllerData"+mainObject.id).offsetHeight)+"px";
		else
			document.getElementById("CRControllerData"+mainObject.id).style.height = (category.height - 80)+"px";

		document.getElementById("CRbody"+this.config.id).style.top = (CRObject.offset().top+20)+"px";
		if((CRObject.offset().top+30+jQuery("#CRbody"+this.config.id).height()) > (document.body.clientHeight - 30))
			document.getElementById("CRbody"+this.config.id).style.top = (parseInt(document.getElementById("CRbody"+this.config.id).style.top)- ((CRObject.offset().top+30+jQuery("#CRbody"+this.config.id).height()) - (document.body.clientHeight - 30)))+"px";
		
		document.getElementById("CRbody"+this.config.id).style.left = (CRObject.offset().left)+"px";
		if((CRObject.offset().left+jQuery("#CRbody"+this.config.id).width()) > document.body.clientWidth)
			document.getElementById("CRbody"+this.config.id).style.left = (parseInt(document.getElementById("CRbody"+this.config.id).style.left) - ((CRObject.offset().left+jQuery("#CRbody"+this.config.id).width()) - document.body.clientWidth))+"px";
		Cyberoam.currentObject = this;
	}
}

Cyberoam.CRController.prototype.hide = function(){
	var CRObject = jQuery("#"+this.config.id);		
	CRObject.removeClass("CRController_open");
	document.getElementById("CRbody"+this.config.id).style.display="none";
	this.CRControllerCancel();
	Cyberoam.currentObject = null;
	//document.getElementById(this.config.id).childNodes[2].focus();
}
Cyberoam.CRController.prototype.getOffsetPosition = function(){
	var bodyObject = document.getElementById("CRbody"+this.config.id);
	return [new Cyberoam.Point(parseInt(bodyObject.style.left),parseInt(bodyObject.style.top)),new Cyberoam.Point((parseInt(bodyObject.style.left)+bodyObject.offsetWidth),(parseInt(bodyObject.style.top) + bodyObject.offsetHeight))];
}
/* this file is user to create selection box
	
	functions
	---------

	var s = new Cyberoam.SelectionBox( {id:"applications",data:[{label:"XNS-Mail",key:"s1"},{label:"XNS-Auth",key:"s2"},{label:"Orkut",key:"s3"},{label:"iSCSI",key:"s4"},{label:"pop3",key:"s5"},{label:"tell",key:"s6"},{label:"Hyves",key:"s7"}],selectAll:false,noOfColumns:2,search:true,width:250,height:150 });

		1)parameter: 	1)id						
						2)data : label
							   key

						3)selectAll	 :
								true for all selected
								false for all unselected
						4)noOfColumns
								by default 1 
								you can pass any number of colums 
						5)search
								true : allow you to search the data selected and character wise
								false : not allow to search
						6)width
								you can pass width of body
						7)height
								you can pass height of body

		2) create	selection Box
			s.create();

		3) You can get the selected Keys
			s.getSelectedKeys()

		4) You can get the selected Labels
			s.getSelectedLabels()

		5) You can get the Selected Items (nodes)
			s.getSelectedItems()
*/

Cyberoam.SelectionBox = function(c) {
	this.config = {"id":"","data":[],returnKey:false,click:null,selectAll:false,noOfColumns:1,search:true,width:250,height:150,label:null,combo1Label:null,combo2Label:null,combo1HTML:null,combo1:null,combo1Selected:null,combo2HTML:null,combo2:null,combo2Selected:null,selectedItem:[],selectAllButtonSelected:false,isDisabled:false};
	this.searchInterval = null;
	this.searchData = [];
	this.listSearchThread = null;
	this.lastSearch = "";
	for (var key in c) {
		if(typeof this.config[key] != "undefined"){
			this.config[key] = c[key];
		}else{
			 Cyberoam.messageBox({message: "Wrong SelectionBox Configuration "+key});
			 this.config = {"id":"","data":[],selectAll:false,noOfColumns:1,search:true,width:0,height:0};
			 return;
		}
	}
	var cloneData = {};
	for(var obj in this.config.data){
		cloneData[obj] = Cyberoam.clone(this.config.data[obj]);
	}
	this.config.data = cloneData;
	for(var t=0;t<this.config.selectedItem.length;t++){
		if(this.config.data[this.config.selectedItem[t]])
			this.config.data[this.config.selectedItem[t]].selected = true;
	}
};

Cyberoam.SelectionBox.prototype.searchSelectedBox  = function(object){
	var myobject = this;
	var arr = this.config.data;
	var val = object.val().toLowerCase();

	var checkTextFieldEmpty=false;
	var id=this.config.id;

	this.searchProcess = function(val,arr){
			jQuery("#selectionBoxBody"+this.config.id).html("");
			if(this.lastSearch.length > val.length)
				this.searchData = [];
			else if(this.searchData.length > 0) {
				arr = this.searchData;
				this.searchData = {};
				}

			var column=this.config.noOfColumns;
			var columnTemp=1;
			var mainElement = document.getElementById("selectionBoxBody"+this.config.id);
			
			if(val != "" && document.getElementById("searchText"+this.config.id).style.color != "rgb(204, 204, 204)" && document.getElementById("searchText"+this.config.id).style.color != "#cccccc" ){
				val = val.toLowerCase();
				var tableMainObject =  Cyberoam.createElement({tag:"table"},mainElement);
				if(this.config.search!=true)
					tableMainObject.setAttribute("cellspacing","1");
				else
					tableMainObject.setAttribute("cellspacing","3");
				tableMainObject.setAttribute("width","100%");
				var tableObject =  Cyberoam.createElement({tag:"tbody"},tableMainObject);
				var tr = null;
				var td = null;
				if(this.config.label != null){
					tr =  Cyberoam.createElement({tag:"tr"},tableObject);
					td =  Cyberoam.createElement({tag:"td"},tr);
					var span =  Cyberoam.createElement({tag:"span"},td);
					if(Cyberoam.isIE)
						span.style.styleFloat = "left";
					else
						span.style.cssFloat = "left";
					span.style.width = "auto";
					span.style.textAlign = "center";
					span.style.fontWeight = "bold";					
					span.appendChild(document.createTextNode(this.config.label));
					
					mainspan =  Cyberoam.createElement({tag:"td"},tr);
					if(Cyberoam.isIE)
						mainspan.style.styleFloat = "right";
					else
						mainspan.style.cssFloat = "right";
					
					combol1label =  Cyberoam.createElement({tag:"span"},mainspan);
					if(Cyberoam.isIE)
						combol1label.style.styleFloat = "left";
					else
						combol1label.style.cssFloat = "left";
					combol1label.style.width = "80px";
					combol1label.style.textAlign = "center";
					combol1label.style.fontWeight = "bold";
					combol1label.appendChild(document.createTextNode(this.config.combo1Label));
					
					combol2label =  Cyberoam.createElement({tag:"span"},mainspan);
					if(Cyberoam.isIE)
						combol2label.style.styleFloat = "left";
					else
						combol2label.style.cssFloat = "left";
					combol2label.style.width = "80px";
					combol2label.style.textAlign = "center";
					combol2label.style.marginRight = "5px";
					combol2label.style.fontWeight = "bold";
					combol2label.appendChild(document.createTextNode(this.config.combo2Label));
				}
				//Select All Checkbox & Label
				tr = Cyberoam.createElement({tag:"tr"},tableObject);
				td = Cyberoam.createElement({tag:"td",colspan:this.config.noOfColumns},tr);
				var div = Cyberoam.createElement({tag:"div",id:"selectall"+this.config.id,className:"selectionBox_item"},td);
				var divIcon = Cyberoam.createElement({tag:"div",className:"selectionbox-icon"},div);
				var divLabel = Cyberoam.createElement({tag:"div",className:"selectionbox-label"},div);
				divLabel.appendChild(document.createTextNode(Language.SelectAll));
				//div.onmouseover = function(e) {$(this).addClass("highlight");	};	
				//div.onmouseout = function(e) { $(this).removeClass("highlight");};	
				div.onclick = function(e) {myobject.divClickEvent(e,this)};	
				// Over Select All
				
				// Checkbox & label for Combo1
				div =  Cyberoam.createElement({tag:"td"},tr);
				if(Cyberoam.isIE)
					div.style.styleFloat = "right";
				else
					div.style.cssFloat = "right";
				if(this.config.combo1 != null){
					select =  Cyberoam.createElement({tag:"select",id:"combo1"+id},div);
					select.style.width = "80px";
					for(var optionKey in this.config.combo1) {
						if (this.config.combo1.hasOwnProperty(optionKey)) {
							var option = Cyberoam.createElement({tag: "option"});
							option.setAttribute("value", optionKey);
							option.appendChild(document.createTextNode(this.config.combo1[optionKey].label));
							if (this.config.combo1Selected == optionKey)
								option.setAttribute("selected", "selected");
							select.appendChild(option);
						}
					}
					select.onclick = function(){
						var combo1value = this.value;
						$("#selectionBoxBody"+id+" table tr td select").each(function(){
							if(this.id.indexOf("combo1") != -1)
								this.value = combo1value;
						});

					}
				}
				if(this.config.combo2 != null){
					select =  Cyberoam.createElement({tag:"select",id:"combo2"+id},div);
					select.style.width = "80px";
					select.style.marginLeft = "3px";
					for(var optionKey in this.config.combo2) {
						if (this.config.combo2.hasOwnProperty(optionKey)) {
							var option = Cyberoam.createElement({tag: "option"});
							option.setAttribute("value", optionKey);
							option.appendChild(document.createTextNode(this.config.combo2[optionKey].label));
							if (this.config.combo2Selected == optionKey)
								option.setAttribute("selected", "selected");
							select.appendChild(option);
						}
					}
					select.onclick = function(){
						var combo2value = this.value;
						$("#selectionBoxBody"+id+" table tr td select").each(function(){
							if(this.id.indexOf("combo2") != -1)
								this.value = combo2value;
						});
					}
				}
				var width = parseInt(document.getElementById(this.config.id).style.width);
				if(this.config.combo1 != null){
					width = width - 125;
				}
				if(this.config.combo2 != null){
					width = width - 125;
				}
				
				// Combo over 
				for(var i in arr) {
					if(arr[i].selected == true || arr[i].label.toLowerCase().indexOf(val) == 0){
						if(columnTemp==1) 
							tr =  Cyberoam.createElement({tag:"tr"},tableObject);
						var td = Cyberoam.createElement({tag:"td"},tr);
						var classNameForDiv = "selectionBox_item";
						if(arr[i].selected) {
							classNameForDiv = classNameForDiv+" selectionBox_item_select";
						}
						
						var div = Cyberoam.createElement({tag:"div",className:classNameForDiv},td);
						var divIcon = Cyberoam.createElement({tag:"div",className:"selectionbox-icon"},div);
						var divLabel = Cyberoam.createElement({tag:"div",className:"selectionbox-label"},div);
						div.style.width = width+"px";
						divLabel.style.width = (width-30)+"px";
						div.setAttribute("key",i);
						div.setAttribute("label",arr[i].label);
						//div.onmouseover = function(e) {$(this).addClass("highlight"); };	
						//div.onmouseout = function(e) { $(this).removeClass("highlight"); };	
						div.onclick = function(e) {myobject.divClickEvent(e,this)};	
						divLabel.appendChild(document.createTextNode(arr[i].label));
						div.setAttribute("title",arr[i].label);
						div = Cyberoam.createElement({tag:"td"},tr);
						if(Cyberoam.isIE)
							div.style.styleFloat = "right";
						else
							div.style.cssFloat = "right";
						
						if(this.config.combo1 != null){
							select =  Cyberoam.createElement({tag:"select",id:"combo1"+id},div);
							select.style.width = "80px";
							for(var optionKey in this.config.combo1) {
								if (this.config.combo1.hasOwnProperty(optionKey)) {
									var option = Cyberoam.createElement({tag: "option"});
									option.setAttribute("value", optionKey);
									option.appendChild(document.createTextNode(this.config.combo1[optionKey].label));
									if (this.config.combo1Selected == optionKey)
										option.setAttribute("selected", "selected");
									select.appendChild(option);
								}
							}
						}
						if(this.config.combo2 != null){
							select =  Cyberoam.createElement({tag:"select",id:"combo2"+id},div);
							select.style.width = "80px";
							select.style.marginLeft = "3px";
							for(var optionKey in this.config.combo2) {
								if (this.config.combo2.hasOwnProperty(optionKey)) {
									var option = Cyberoam.createElement({tag: "option"});
									option.setAttribute("value", optionKey);
									option.appendChild(document.createTextNode(this.config.combo2[optionKey].label));
									if (this.config.combo2Selected == optionKey)
										option.setAttribute("selected", "selected");
									select.appendChild(option);
								}
							}
						}
						
						columnTemp++;		
						if(columnTemp>column){	
							columnTemp=1;
						}
						checkTextFieldEmpty=true;
						this.searchData[i] = arr[i];							
											
					}
	
			}

			if(	checkTextFieldEmpty==false  ){
				var trObject =  Cyberoam.createElement({tag:"tr",className:"noRecordFound"},tableObject);
				var tdObject =  Cyberoam.createElement({tag:"td"},trObject);
				tdObject.appendChild(document.createTextNode(Cyberoam.getTranslatedMSG('Language.NoRecord')));
			}
		}else{
			this.searchData = {};
			this.setSelectionBody();
		}			
		this.lastSearch = val;
	};
	if(this.searchInterval != null)
		clearTimeout(this.searchInterval);

	this.searchInterval = setTimeout(function(){myobject.searchProcess(val,arr)},1000);
};
