Cyberoam.SelectionBox.prototype.setSelectionBox = function(data,selectedItems){
	//this.config.data = null;
	 var cloneData = {};
	 for(var obj in data){
	  cloneData[obj] = Cyberoam.clone(data[obj]);
	 }
	 
	 for(var i =0;i<selectedItems.length;i++){
	  if(typeof cloneData[selectedItems[i]] != "undefined")
	   cloneData[selectedItems[i]].selected = true;
	 }
	 this.config.data = cloneData;
	 this.setSelectionBody();
}
