Cyberoam.SelectionBox.prototype.divClickEvent = function(event,object) {		
	var myobject=this;
	var id=myobject.config.id;	

	if(object.id=="selectall"+this.config.id ){
		if(!myobject.config.isDisabled){
			if(object.className.indexOf("_select") == -1 ){
				$("#selectionBoxBody"+id+" table tr td div").each(function(){
					myobject.setItem(this,"select",false);
				});
				myobject.config.selectAllButtonSelected = true;
				object.className += " selectionBox_item_select";
			}else{
				$("#selectionBoxBody"+id+" table tr td div").each(function(){
					myobject.setItem(this,"unselected",false);
				});
				myobject.config.selectAllButtonSelected = false;
				object.className = "selectionBox_item";
			}
			if((typeof isClick == "undefined" || isClick==true) && myobject.config.click)
				myobject.config.click(myobject);
		}
	}
	else{
		if(!myobject.config.isDisabled)
			this.setItem(object);
	    }
};

Cyberoam.SelectionBox.prototype.setItem = function(object,status,isClick){
	var key  = object.getAttribute("key");
	var myobject=this;
	if(key){
		if((object.className.indexOf("_select") == -1 && typeof status == "undefined") || (typeof status != "undefined" && status=="select")) {
			object.className += " selectionBox_item_select";		
			this.config.data[key].selected=true;
			var ele = object.parentNode.parentNode.childNodes[1].getElementsByTagName("select");
			for(var i=0;i<ele.length;i++){
				ele[i].disabled = false;
			}
		}else{
			object.className = "selectionBox_item";
			this.config.data[key].selected=false;	

			if(this.config.selectAllButtonSelected){
				this.config.selectAllButtonSelected = false;		
				$('#selectall'+this.config.id).removeClass().addClass('selectionBox_item');
			}
			var ele = object.parentNode.parentNode.childNodes[1].getElementsByTagName("select");
			for(var i=0;i<ele.length;i++){
				ele[i].disabled = true;
			}
		}
		if((typeof isClick == "undefined" || isClick==true) && myobject.config.click)
			myobject.config.click(myobject);
	}
};

Cyberoam.SelectionBox.prototype.getSelectedKeys = function() {
	if(!this.config.isDisabled){
		var arr=[];
		for(var i in this.config.data){
			if(this.config.data[i].selected == true)
				arr.push(i);
		}
		return arr;	
	}else{
		return null;
	}	
};
Cyberoam.SelectionBox.prototype.getSelectedLabels = function() {
	if(!this.config.isDisabled){
		var arr=[];
		for(var i in this.config.data){
			if(this.config.data[i].selected == true)
				arr.push(this.config.data[i].label);
		}
		return arr;
	}else{
		return null;
	}
};
Cyberoam.SelectionBox.prototype.getSelectedValues = function() {	
	var key=[];
	var label=[];
	var column1=[];
	var column2=[];	
	var id=this.config.id;	
	$("#selectionBoxBody"+id+" table tr td div").each(function(){
		if(this.className.indexOf("_select") != -1 && this.innerHTML != Language.SelectAll){
			key.push(this.getAttribute("key"));
			label.push(this.getAttribute("label"));
			var ele = this.parentNode.parentNode.childNodes[1].getElementsByTagName("select");
			if(ele[0])
				column1.push(ele[0].value);
			if(ele[1])
				column2.push(ele[1].value);
		}
	});
	
	
	return {key:key,label:label,column1:column1,column2:column2};
};
Cyberoam.SelectionBox.prototype.getSelectedItems = function() {	
	var arr=[];
	for(var i in this.config.data){
		if(this.config.data[i].selected == true)
			arr.push(this.config.data[i]);
	}
	return arr;
};
Cyberoam.SelectionBox.prototype.selectAll = function(object,flag) {
	var myobject=this;
	var id=myobject.config.id;	
	if(object.id=="selectall"+this.config.id ){
		if(flag){
			if(object.className.indexOf("_select") == -1 ){
				$("#selectionBoxBody"+id+" table tr td div").each(function(){
					myobject.setItem(this,"select",false);
				});
				myobject.config.selectAllButtonSelected = true;
				object.className += " selectionBox_item_select";
			}
		}else{
			$("#selectionBoxBody"+id+" table tr td div").each(function(){
				myobject.setItem(this,"unselected",false);
			});
			myobject.config.selectAllButtonSelected = false;
			object.className = "selectionBox_item";
		}
	}
};
Cyberoam.SelectionBox.prototype.create = function(){
	if(this.id != ""){
		var myobject = this;
		jQuery("#"+this.config.id).attr("class","selectionBox");
		document.getElementById(this.config.id).style.height =  myobject.config.height+"px";
		document.getElementById(this.config.id).style.width = myobject.config.width +"px";
		if(this.config.search==true){
			jQuery("#"+this.config.id).html("<table width=\"100%\" align=\"center\" cellspacing=\"1\" cellpadding=\"0\">"+
						"<tr><td>"+ 
						"<input type=\"text\" id=\"searchText"+this.config.id+"\" class='selectionBoxSearch' style=\"width:"+ (Number(myobject.config.width) -10) + "px;*weidth:97%;color:#CCCCCC\" value='"+Cyberoam.getTranslatedMSG("Language.Search")+"'/></td></table>"+
						"<div id=\"selectionBoxBody"+this.config.id+"\" class='selectionBoxBody' style=\"height:120px;\"></div>");
	
		    jQuery("#searchText"+this.config.id).on('keyup',function(){ myobject.searchSelectedBox(jQuery(this))});
	
			jQuery("#searchText"+this.config.id).on('focus',function(e){
				Cyberoam.textEmptyFocus(this,Cyberoam.getTranslatedMSG("Language.Search"));
			});
			jQuery("#searchText"+this.config.id).on('blur',function(e){
				Cyberoam.textEmptyBlur(this,Cyberoam.getTranslatedMSG("Language.Search"));
			});
		}else{
			jQuery("#"+this.config.id).html("<div id=\"selectionBoxBody"+this.config.id+"\" class='selectionBoxBody' style=\"height:"+myobject.config.height+"px;\"></div>");
		}
		this.setSelectionBody();
	}
};
/* this file is user to create datatable
	
	functions
	---------

	   var DT = new Cyberoam.DataTable({id:"CRCont",width:400,afterDelete:function(){alert("a");return false;},
	   columns:[{name:"column1",label:"column1",maxlength:3},{name:"column2",label:"column2",type:"select","events":{onblur:"addInNetwork();}","value":"chk2",option:[{label:"chk1",key:"chk1"},{label:"chk2",key:"chk2"}],width:200},
	   {name:"column3",label:"column3",type:"checkbox",option:[{label:"1",key:"1"},{label:"2",key:"2"}]}]});

		1)		id:
				width:
				afterDelete : written function will call 

				columns: data passeed 
					per data object one column , 
							name : column name
							lable : column label
							maxLength : 
							type: any type like select , checkbox ,password,hyperlink,default is textbox
							option : passed data to that selected box like in select ,label and key
							width:	default is 100
							height :  default is auto
							maxlength : default is null
							value : default value for field
							events : events for textfield and selectbox 
							
				css : you can pass css for main div object				

		2)DT.create();
			create by using this method

	    3)setValue : you can set the value of column wise
			DT.setValue([{"column1":"1","column2":["chk1"],"column3":"3"},{"column1":"2","column2":["chk2"],"column3":"4"}]);

*/
Cyberoam.DataTable = function(c){
	this.config = {id:"",columns:[],width:"auto",height:"auto",validator:null,afterAdd:null,afterDelete:null,css:""};
	var columnDefault = {name:"",label:"",type:"textbox",value:"",config:null,option:[],returnKey:false,width:100,maxlength:null,events:null,title:""};
	this.currentIndex = 1;
	this.checkBox = null;
	this.CRController = {};
	this.currentElements = [];
	for (var key in c) {
		if(this.config[key] != "undefined"){
			if(key == "columns"){
				for(var i=0;i<c.columns.length;i++){
					var newColumn = {};
					for (var catKey in columnDefault) {
						if(c.columns[i][catKey])
							newColumn[catKey] = c.columns[i][catKey];
						else{
							newColumn[catKey] = columnDefault[catKey];
						}						
					}
					this.config[key].push(newColumn);
				}
			}else
				this.config[key] = c[key];
		}else{
			 Cyberoam.messageBox({message: "Wrong CRController Configuration "+key});
			 return;
		}
	}
};
Cyberoam.DataTable.prototype.create = function(){
	var mainobject= this;
	var myConfig = this.config;
	var width = "auto";
	var mainEle = document.getElementById(myConfig.id);
	if(myConfig.width != "auto"){
		mainEle.style.width = myConfig.width;
		width = parseInt(myConfig.width)/myConfig.columns.length;
	}
	if(myConfig.height != "auto")
		mainEle.style.height = myConfig.height;
	if(myConfig.css != "")
		mainEle.style = myConfig.css;
	dataTableHTML = [];
	dataTableHTML.push("<table class='datatable' cellpadding=0 cellspecing=0 ><tbody id=tbody"+myConfig.id+" ><tr>");
	for(var i=0;i<myConfig.columns.length;i++){
		dataTableHTML.push("<td class='tableheader' align='center' style='width:"+width+"' >"+myConfig.columns[i].label+"</td>");
		if(typeof myConfig.columns[i].width == "undefined")
			myConfig.columns[i].width = width;
	}
	dataTableHTML.push("<td class='tableheader' align='center' style='width:20px;padding-right:12px' ><div class=\"datatableAdd\" id='datatableAdd"+myConfig.id +"'><i class=\"fa fa-plus-square\"></i></div></td></tr><tr class=\"datatable-content-row\" id=datatable_"+myConfig.id+"_"+this.currentIndex+">");
	for(var i=0;i<myConfig.columns.length;i++){
		dataTableHTML.push("<td class=tabletext >"+this.createFromElement(myConfig.columns[i])+"</td>");
	}
	
	dataTableHTML.push("<td class=tabletext ><div class=\"datatableDelete\" id='datatableDelete"+myConfig.id+"_"+this.currentIndex+"' index='"+this.currentIndex+"'><i class=\"fa fa-minus-circle\"></i></div></td>");
	dataTableHTML.push("</tr></tbody></table>");
	jQuery(mainEle).html(dataTableHTML.join(""));
	jQuery("#datatableDelete"+myConfig.id+"_"+this.currentIndex).on('click',function(){
			mainobject.deleteRow(this.getAttribute("index"));
		});
	
	this.CRController[this.currentIndex] = {};
	for(var i=0;i<myConfig.columns.length;i++){		
		if(myConfig.columns[i].type == "checkbox"){
			var nodes = [];
			for(var j=0;j<myConfig.columns[i].option.length;j++){
					if(typeof myConfig.columns[i].value!="undefined" && myConfig.columns[i].option[j].key == myConfig.columns[i].value)
						nodes.push({id:this.config.id+"_"+myConfig.columns[i].name+"_"+this.currentIndex+"_"+j,name:myConfig.columns[i].name,label:myConfig.columns[i].option[j].label,value:myConfig.columns[i].option[j].key,checked:true});
					else
						nodes.push({id:this.config.id+"_"+myConfig.columns[i].name+"_"+this.currentIndex+"_"+j,name:myConfig.columns[i].name,label:myConfig.columns[i].option[j].label,value:myConfig.columns[i].option[j].key});
			}
			this.checkBox = new Cyberoam.CheckBox(nodes);
			this.checkBox.create();
		}else if(myConfig.columns[i].type == "CRController"){
			myConfig.columns[i].config["id"] = this.config.id+"_"+myConfig.columns[i].name+"_"+this.currentIndex;
			this.CRController[this.currentIndex][i] = new Cyberoam.CRController(myConfig.columns[i].config);
			this.CRController[this.currentIndex][i].create();
		}
	}
	
	if(myConfig.columns[myConfig.columns.length-1].type == "textbox" || myConfig.columns[myConfig.columns.length-1].type == "textarea" ||  myConfig.columns[myConfig.columns.length-1].type == "select" || myConfig.columns[myConfig.columns.length-1].type == "password" || myConfig.columns[myConfig.columns.length-1].type == "hyperlink"){
			document.getElementById(this.config.id+"_"+myConfig.columns[myConfig.columns.length-1].name+"_"+this.currentIndex).onkeydown = function(e){
				var event = new Cyberoam.Event(e);
				if(event.getKeyCode() == 9 && jQuery(this.parentNode.parentNode.parentNode).next().attr("id") == undefined)
					mainobject.addRow();
			};
		}else{
			document.getElementById(this.config.id+"_"+myConfig.columns[myConfig.columns.length-1].name+"_"+this.currentIndex+"_"+(myConfig.columns[myConfig.columns.length-1].option.length-1)).onkeydown = function(e){
				var event = new Cyberoam.Event(e);
				if(event.getKeyCode() == 9 && jQuery(this.parentNode.parentNode.parentNode).next().attr("id") == undefined)
					mainobject.addRow();
			};
		}

	this.currentElements.push(this.currentIndex++);
	jQuery("#datatableAdd"+myConfig.id).on('click',function(){
			mainobject.addRow();
	});
};
Cyberoam.DataTable.prototype.setValueByIndex = function(data,index){
	var myConfig = this.config;
	var tr = document.getElementById("datatable_"+myConfig.id+"_"+index);
	if(!tr){
		this.addRow(true);
		tr = document.getElementById("datatable_"+myConfig.id+"_"+index);
	}
	var record = {};
	for(var j=0;j<this.config.columns.length;j++){
		var column = this.config.columns[j];
		if(data[column.name]){		
			if(column.type == "textbox")
				tr.childNodes[j].childNodes[0].childNodes[0].value = data[column.name];
			if(column.type == "textarea")
				tr.childNodes[j].childNodes[0].childNodes[0].value = data[column.name];
			else if(column.type == "password")
				tr.childNodes[j].childNodes[0].childNodes[0].value = data[column.name];
			else if(column.type == "hyperlink")
				tr.childNodes[j].childNodes[0].childNodes[0].value = data[column.name];
			else if(column.type == "select"){
				var cnt = 0;
				for(var k in column.option){
					if(data[column.name] == k){						
						tr.childNodes[j].childNodes[0].childNodes[0].options[cnt].selected = true;
					}
					cnt++;
				}
			}else if(column.type == "checkbox"){
				record[column.name] = [];
				for(var k=0;k<column.option.length;k++){
					if(typeof data[column.name] == "string"){
						if(column.option[k].key == data[column.name])
							this.checkBox.selectById(this.config.id+"_"+column.name+"_"+index+"_"+k,true);
						else
							this.checkBox.selectById(this.config.id+"_"+column.name+"_"+index+"_"+k,false);
					}else{
						if(Cyberoam.findItemInArray(column.option[k].key,data[column.name]) != -1)
							this.checkBox.selectById(this.config.id+"_"+column.name+"_"+index+"_"+k,true);
					}
				}
			}else if(column.type == "CRController" && typeof data[column.name] != "undefined"){
				if(typeof data[column.name] == "string"){
					this.CRController[index][j].setCategory(column.config.category[0].name,new Array(data[column.name]));
				}else{
					this.CRController[index][j].setCategory(column.config.category[0].name,data[column.name]);
				}
			}else if(column.type == "radio"){
				record[column.name] = [];
				for(var k=0;k<column.option.length;k++){
					tr.childNodes[j].childNodes[0].childNodes[0].checked = true;
					if(data[column.name] == column.option[k].key){
						tr.childNodes[j].childNodes[0].childNodes[k*2].checked = true;
					}
				}
			}
		}
	}
}
Cyberoam.DataTable.prototype.setValue = function(data){
	for(var i=0;i<data.length;i++){
		this.setValueByIndex(data[i],i+1);
	}
}
Cyberoam.DataTable.prototype.getValueInArray = function(){
	var record = {}; 
	for(var j=0;j<this.config.columns.length;j++){
		record[this.config.columns[j].name] = [];
	}
	var myConfig = this.config;
	for(var i=0;i<this.currentElements.length;i++){	
		var tr = document.getElementById("datatable_"+myConfig.id+"_"+this.currentElements[i]);
		for(var j=0;j<this.config.columns.length;j++){
			var column = this.config.columns[j];
			var value=null;
			if(column.type == "textbox"){
				value=tr.childNodes[j].childNodes[0].childNodes[0].value;
			}else if(column.type == "password"){
				value=tr.childNodes[j].childNodes[0].childNodes[0].value;
			}else if(column.type == "hyperlink"){
				//value=tr.childNodes[j].childNodes[0].childNodes[0].value;
				value ="";
			}else if(column.type == "textarea"){
				value=tr.childNodes[j].childNodes[0].childNodes[0].value;
			}
			else if(column.type == "select"){
				if(!column.returnKey){
					value=tr.childNodes[j].childNodes[0].childNodes[0].options[tr.childNodes[j].childNodes[0].childNodes[0].selectedIndex].text;
				}else{
					value=tr.childNodes[j].childNodes[0].childNodes[0].value;
				}
			}else if(column.type == "checkbox"){
				record1 = [];
				for(var k=0;k<column.option.length;k++){
					var val = this.checkBox.getValueById(this.config.id+"_"+column.name+"_"+this.currentElements[i]+"_"+k);
					if(val != false)
						record1.push(val);
				}
				value =record1;				
			}else if(column.type == "CRController"){
				if(typeof column.config.category[0].radioBox != "undefind" && column.config.category[0].radioBox == true )
					value = this.CRController[i][j].getSelectedKeys().toString();	
				else
					value = this.CRController[i][j].getSelectedKeys();	
			}else if(column.type == "radio"){
				record1= [];
				for(var k=0;k<column.option.length;k++){
					if(tr.childNodes[j].childNodes[0].childNodes[k*2].checked)
						record1.push(tr.childNodes[j].childNodes[0].childNodes[k*2].value);
				}
				value = record1;
				
			}
			if(value){
				if(typeof value == "string"){
					value = Cyberoam.trim(value);
					value = value.replace(/\s+/g, " ");
					value = Cyberoam.replaceAll(value,"\\","\\\\");
					value = Cyberoam.replaceAll(value,"\'","\\\'");
				}else{
					for(var cnt=0;cnt<value.length;cnt++){
						value[cnt] = Cyberoam.trim(value[cnt]);
						value[cnt] = value[cnt].replace(/\s+/g, " ");
						value[cnt] = Cyberoam.replaceAll(value[cnt],"\\","\\\\");
						value[cnt] = Cyberoam.replaceAll(value[cnt],"\'","\\\'");
					}
				}
			}
			record[this.config.columns[j].name].push(value);
		}
	}
	return record;
}
Cyberoam.DataTable.prototype.getValue = function(){
	var dataTableValue = [];
	var status = true;
	var myConfig = this.config;
	for(var i=0;i<this.currentElements.length;i++){			
			dataTableValue.push(this.getRecordByIndex(this.currentElements[i]));
	}
	return dataTableValue;
}
Cyberoam.DataTable.prototype.getRecordByIndex = function(index){
	var myConfig = this.config;
	var tr = document.getElementById("datatable_"+myConfig.id+"_"+index);
	var record = {};
	if(tr){
		for(var j=0;j<this.config.columns.length;j++){
			var column = this.config.columns[j];
			if(column.type == "textbox"){
				record[column.name] = tr.childNodes[j].childNodes[0].childNodes[0].value;
			}else if(column.type == "password"){
				record[column.name] = tr.childNodes[j].childNodes[0].childNodes[0].value;	
			}else if(column.type == "hyperlink"){
				//record[column.name] = tr.childNodes[j].childNodes[0].childNodes[0].value;	
				record[column.name] = "";	
			}else if(column.type == "textarea"){
				record[column.name] = tr.childNodes[j].childNodes[0].childNodes[0].value;	
			}else if(column.type == "select"){
				record[column.name] = tr.childNodes[j].childNodes[0].childNodes[0].value;
			}else if(column.type == "checkbox"){
				record[column.name] = [];
				for(var k=0;k<column.option.length;k++){
					var val = this.checkBox.getValueById(this.config.id+"_"+column.name+"_"+index+"_"+k);
					if(val != false)
						record[column.name].push(val);
				}
			}else if(column.type == "CRController"){
				if(typeof column.config.category[0].radioBox != "undefind" && column.config.category[0].radioBox == true )
					record[column.name] = this.CRController[index][j].getSelectedKeys().toString();	
				else
					record[column.name] = this.CRController[index][j].getSelectedKeys();		
			}else if(column.type == "radio"){
				record[column.name] = [];
				for(var k=0;k<column.option.length;k++){
					if(tr.childNodes[j].childNodes[0].childNodes[k*2].checked)
						record[column.name].push(tr.childNodes[j].childNodes[0].childNodes[k*2].value);
				}
			}
			if(typeof record[column.name] == "string"){
				record[column.name] = Cyberoam.replaceAll(record[column.name],"\\","\\\\");
				record[column.name] = Cyberoam.replaceAll(record[column.name],"\'","\\\'");
			}else{
				for(var cnt=0;cnt<record[column.name].length;cnt++){
					record[column.name][cnt] = Cyberoam.replaceAll(record[column.name][cnt],"\\","\\\\");
					record[column.name][cnt] = Cyberoam.replaceAll(record[column.name][cnt],"\'","\\\'");
				}
			}
			
		}
	}
	return record;
}
Cyberoam.DataTable.prototype.deleteRow = function(index){
	for(var i=0;i<this.currentElements.length;i++){
		if(this.currentElements[i] == index){
			this.currentElements.splice(i,1);
			break;
		}
	}
	jQuery("#datatable_"+this.config.id+"_"+index).remove();
	if(this.config.afterDelete != null){
		this.config.afterDelete(this,index);
	}
	if(this.currentElements.length == 0){
		this.addRow(true);
	}
}

Cyberoam.DataTable.prototype.addRow = function(validationFlag){
	var mainobject = this;
	var myConfig = this.config;
	var status = true;
	if(typeof validationFlag == "undefined" && myConfig.validator != null){
		status = myConfig.validator(this);
	}
	if(status == true){
		var width = "auto";
		dataTableHTML = [];
		dataTableHTML.push("<tr class=\"datatable-content-row\" id=datatable_"+myConfig.id+"_"+this.currentIndex+">");
		for(var i=0;i<myConfig.columns.length;i++){
			dataTableHTML.push("<td class=tabletext >"+this.createFromElement(myConfig.columns[i])+"</td>");
		}
		dataTableHTML.push("<td class=tabletext align='center' style='width:20px;padding-right:12px'><div class=\"datatableDelete\" id='datatableDelete"+myConfig.id+"_"+this.currentIndex+"' index='"+this.currentIndex+"'><i class=\"fa fa-minus-circle\"></i></div></td>");
		dataTableHTML.push("</tr>");
		jQuery("#tbody"+myConfig.id).append(jQuery(dataTableHTML.join("")));
		this.CRController[this.currentIndex]={};
		for(var i=0;i<myConfig.columns.length;i++){			
			if(myConfig.columns[i].type == "checkbox"){
				for(var j=0;j<myConfig.columns[i].option.length;j++){
					if(typeof myConfig.columns[i].value!="undefined" && myConfig.columns[i].option[j].key == myConfig.columns[i].value)
						this.checkBox.insert({id:this.config.id+"_"+myConfig.columns[i].name+"_"+this.currentIndex+"_"+j,name:myConfig.columns[i].name,label:myConfig.columns[i].option[j].label,value:myConfig.columns[i].option[j].key,checked:true});
					else
						this.checkBox.insert({id:this.config.id+"_"+myConfig.columns[i].name+"_"+this.currentIndex+"_"+j,name:myConfig.columns[i].name,label:myConfig.columns[i].option[j].label,value:myConfig.columns[i].option[j].key});
				}
			}else if(myConfig.columns[i].type == "CRController"){
				myConfig.columns[i].config["id"] = this.config.id+"_"+myConfig.columns[i].name+"_"+this.currentIndex;
				this.CRController[this.currentIndex][i] = new Cyberoam.CRController(myConfig.columns[i].config);
				this.CRController[this.currentIndex][i].create();
			}
		}
		jQuery("#datatableDelete"+myConfig.id+"_"+this.currentIndex).on('click',function(){
			mainobject.deleteRow(this.getAttribute("index"));
		});
		if(myConfig.afterAdd != null){
			myConfig.afterAdd(this,document.getElementById("datatable_"+myConfig.id+"_"+this.currentIndex),this.currentIndex);
		}
		if(myConfig.columns[myConfig.columns.length-1].type == "textbox" || myConfig.columns[myConfig.columns.length-1].type == "textarea" || myConfig.columns[myConfig.columns.length-1].type == "select" || myConfig.columns[myConfig.columns.length-1].type == "password" || myConfig.columns[myConfig.columns.length-1].type == "hyperlink"){
			document.getElementById(this.config.id+"_"+myConfig.columns[myConfig.columns.length-1].name+"_"+this.currentIndex).onkeydown = function(e){
				var event = new Cyberoam.Event(e);
				if(event.getKeyCode() == 9 && jQuery(this.parentNode.parentNode.parentNode).next().attr("id") == undefined)
					mainobject.addRow();
			};
		}else{
			document.getElementById(this.config.id+"_"+myConfig.columns[myConfig.columns.length-1].name+"_"+this.currentIndex+"_"+(myConfig.columns[myConfig.columns.length-1].option.length-1)).onkeydown = function(e){
					var event = new Cyberoam.Event(e);
					if(event.getKeyCode() == 9 && jQuery(this.parentNode.parentNode.parentNode).next().attr("id") == undefined)
						mainobject.addRow();
			};
		}
		this.currentElements.push(this.currentIndex++);
	}
}

Cyberoam.DataTable.prototype.createFromElement = function(object){
		var eleHTML = ["<div style='width:"+(parseInt(object.width)+5)+"px' >"];
        if(object.type=="textarea")
            eleHTML = ["<div style='margin-right:5px' >"];       	
		var eleoption = object.option;		
		if(object.type=="textbox" || object.type=="password" || object.type=="hyperlink"){
			var maxlength = "";
			var value = "";
			if(object.maxlength != null)
				maxlength = "maxlength="+object.maxlength;
			if(typeof object.value != undefined && object.value != "" && object.value != null)                                                                                      
                value = "value="+object.value;
				if(object.type=="textbox"){
						eleHTML.push("<input type=\"text\" id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"\" name=\""+object.name+"\" "+maxlength+" " + value + " style='height:23px;min-width:30px;width:"+(parseInt(object.width)-15)+"px'");
			}else if(object.type=="password"){
						eleHTML.push("<input type=\"password\" id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"\" name=\""+object.name+"\" "+maxlength+" " + value + " style='height:23px;width:"+(parseInt(object.width)-15)+"px;padding: 5px 1px;min-width: 30px;'");
			}else{
						eleHTML.push("<a id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"\"  name=\""+object.name+"\" "+maxlength+" " + value + " style='width:"+(parseInt(object.width)-5)+"px' ");
			}
			if(object.events){
				for(var key in object.events) {
					if (object.events.hasOwnProperty(key)) {
						eleHTML.push(key + "=" + "'" + object.events[key] + "' ");
					}
				}
			}
			if(object.type=="hyperlink"){
				eleHTML.push(">"+object.value+"</a>");					
			}else{
				eleHTML.push(">");					
			}
		}else if(object.type=="textarea"){
			var value = "";
			if(typeof object.value != undefined && object.value != "" && object.value != null)                                                                                      
                value = object.value;
			if(object.title != "")
				eleHTML.push("<textarea placeholder=\""+Cyberoam.getTranslatedMSG(object.title)+"\" class=\"textareacss\" id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"\" name=\""+object.name+"\" style='width:"+(parseInt(object.width)-15)+"px' >" + value + "</textarea>");
			else
				eleHTML.push("<textarea class=\"textareacss\" id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"\" name=\""+object.name+"\"  style='width:"+(parseInt(object.width)-5)+"px' >" + value + "</textarea>");
		}else if(object.type=="checkbox"){
			if(eleoption.length != 0)
				for(var i=0;i<eleoption.length;i++){
					eleHTML.push("<div class=\"checkBox\" id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"_"+i+"\" ></div>");
				}
		}else if(object.type=="radio"){
			if(eleoption.length != 0)
				for(var i=0;i<eleoption.length;i++){
					eleHTML.push("<input type=\"radio\" id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"_"+i+"\" name=\""+object.name+"_"+this.currentIndex+"\" value=\"" +eleoption[i].key+ "\"  style='width:"+(parseInt(object.width)-5)+"px'>" + eleoption[i].label+"    ");
				}
		}else if(object.type=="CRController"){
				eleHTML.push("<div id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"\" ></div>");
		}else if(object.type=="select"){
			var value = "";
			if(typeof object.value != undefined && object.value != "" && object.value != null)                                                                                      
                value = object.value;
			eleHTML.push("<select name=\""+object.name+"\" id=\""+this.config.id+"_"+object.name+"_"+this.currentIndex+"\" style='width:"+(parseInt(object.width)-5)+"px' ");
			if(object.events){
				for(var key in object.events) {
					if (object.events.hasOwnProperty(key)) {
						eleHTML.push(key + "=" + "'" + object.events[key] + "' ");
					}
				}
			}
			eleHTML.push(">");
			if(eleoption.length != 0)
				for(var i in eleoption) {
					if (eleoption.hasOwnProperty(i)) {
						var key = i;
						if (typeof eleoption[i].key != "undefined")
							key = eleoption[i].key;
						if (value != "" && value == key) {
							eleHTML.push("<option value=\"" + key + "\" selected='selected' title=\"" + eleoption[i].label + "\">" + Cyberoam.getTranslatedMSG(eleoption[i].label) + "</option>");
						} else {
							eleHTML.push("<option value=\"" + replaceAll(key, "\"", "&quot;") + "\" >" + replaceAll(Cyberoam.getTranslatedMSG(eleoption[i].label), "<", "&lt;") + "</option>");
						}
					}
				}
			eleHTML.push("</select>");
		}
		eleHTML.push("</div>");
		return eleHTML.join("");
	}

function replaceAll(string,value,replaceValue){
	while((string.indexOf(value)) > -1){
		string = string.replace(value,replaceValue);
	}
	return string;
}

