////	if(!$(object).is(".dragList_item_select_disable") && !$(object).is(".dragList_item_unselect_disable") )
////		$(object).addClass("highlight");
//};
//Cyberoam.dragList.prototype.mouseOutEvent = function(event, object){
////	 $(object).removeClass("highlight");
//};
Cyberoam.dragList.prototype.show = function(){
	if(!this.config.disabled)  {
		var comboObject = jQuery("#"+this.config.id);
		var obj = document.getElementById("DragList_body"+this.config.id);
		if(Cyberoam.pageLayer > 0)
			obj.style.zIndex = Cyberoam.pageLayer*200 + 5;
		obj.style.top = (comboObject.offset().top + comboObject.height())+"px";
		obj.style.left = (comboObject.offset().left)+"px";
		obj.style.display="";
		Cyberoam.currentObject = this;
	}
};
Cyberoam.dragList.prototype.hide = function(){
	document.getElementById("DragList_body"+this.config.id).style.display="none";
	Cyberoam.currentObject = null;
};
Cyberoam.dragList.prototype.getOffsetPosition = function(){
	var bodyObject = document.getElementById("DragList_body"+this.config.id);
	return [new Cyberoam.Point(parseInt(bodyObject.style.left),parseInt(bodyObject.style.top)),new Cyberoam.Point((parseInt(bodyObject.style.left)+bodyObject.offsetWidth),(parseInt(bodyObject.style.top) + bodyObject.offsetHeight))];
};

Cyberoam.dragList.prototype.setSelectAllItems= function(isSelected,applyOnDisabled) {
	if(isSelected == undefined)
		isSelected = true;
	if(applyOnDisabled == undefined)
		applyOnDisabled = false;
	var kids=document.getElementById("DragList_body"+this.config.id).childNodes[0].childNodes;
	for(var i=0;i<kids.length;i++) {
		var $a = $(kids[i]).find(".dragList1_item");
		if($a.is(".disabled")) { //Is checkbox is disabled ?
			if(!applyOnDisabled) continue;
			if(isSelected) {
				$a.removeClass("selected").addClass("selected");
			} else {
				$a.removeClass("selected");
			}
		} else { // Is not disabled checkbox?
			if(isSelected) {
				$a.removeClass("selected").addClass("selected");
			} else {
				$a.removeClass("selected");
			}
		}
	}
	this.setIndexAndItem();
};


Cyberoam.dragList.prototype.removeItem= function(key) {
	for(var i=0;i<this.selectedItem.length;i++){
		if(this.selectedItem[i]["key"] == key){
			this.selectedItem.splice(i,1);
			this.selectedIndex.splice(i,1);
		}
	}
}

Cyberoam.dragList.prototype.dragListYUI = function() {
	var id = this.config.id;
	var Dom = YAHOO.util.Dom;
	var Event = YAHOO.util.Event;
	var DDM = YAHOO.util.DragDropMgr;
	YAHOO.example.DDApp = {
		init: function() {
			var target = new YAHOO.util.DDTarget("DragList_Items"+id);
			var ele = document.getElementById("DragList_Items"+id);
			for (i=0;i<ele.childNodes.length;i=i+1) {
				if(ele.childNodes[i].className.indexOf("_disable") == -1){
					var list = new YAHOO.example.DDList(ele.childNodes[i].id);
				}
			}
		}
	};

	//////////////////////////////////////////////////////////////////////////////
	// custom drag and drop implementation
	//////////////////////////////////////////////////////////////////////////////

	YAHOO.example.DDList = function(id, sGroup, config) {

		YAHOO.example.DDList.superclass.constructor.call(this, id, sGroup, config);
		var el = this.getDragEl();
		Dom.setStyle(el, "opacity", 0.67); // The proxy is slightly transparent
		this.goingUp = false;
		this.lastY = 0;
	};

	YAHOO.extend(YAHOO.example.DDList, YAHOO.util.DDProxy, {

		startDrag: function(x, y) {
			// make the proxy look like the source element
			var dragEl = this.getDragEl();
			var clickEl = this.getEl();
			try{
			if(document.getElementById("dragdiv"))
				clickEl.removeChild(document.getElementById("dragdiv"));
			}catch(exception){}
			dragEl.innerHTML = clickEl.innerHTML;
			Dom.setStyle(dragEl, "color", Dom.getStyle(clickEl, "color"));
			Dom.setStyle(dragEl, "backgroundColor", Dom.getStyle(clickEl, "backgroundColor"));
			Dom.setStyle(dragEl, "border", "2px solid gray");
		},

		endDrag: function(e) {

			var srcEl = this.getEl();
			var proxy = this.getDragEl();

			// Show the proxy element and animate it to the src element's location
			Dom.setStyle(proxy, "visibility", "");
			//Dom.removeClass(clickEl.id,"dragElementSpace");
			var a = new YAHOO.util.Motion(
				proxy, {
					points: {
						to: Dom.getXY(srcEl)
					}
				},
				0.2,
				YAHOO.util.Easing.easeOut
			)
			var proxyid = proxy.id;
			var thisid = this.id;

			// Hide the proxy and show the source element when finished with the animation
			a.onComplete.subscribe(function() {
					Dom.setStyle(proxyid, "visibility", "hidden");
					//Dom.setStyle(thisid, "visibility", "");
					Dom.removeClass(thisid,"dragElementSpace");
				});
			a.animate();
		},

		onDragDrop: function(e, id) {

			// If there is one drop interaction, the li was dropped either on the list,
			// or it was dropped on the current location of the source element.
			if (DDM.interactionInfo.drop.length === 1) {

				// The position of the cursor at the time of the drop (YAHOO.util.Point)
				var pt = DDM.interactionInfo.point;

				// The region occupied by the source element at the time of the drop
				var region = DDM.interactionInfo.sourceRegion;

			}
		},

		onDrag: function(e) {

			// Keep track of the direction of the drag for use during onDragOver
			var y = Event.getPageY(e);

			if (y < this.lastY) {
				this.goingUp = true;
			} else if (y > this.lastY) {
				this.goingUp = false;
			}

			this.lastY = y;
		},

		onDragOver: function(e, id) {

			var srcEl = this.getEl();
			var destEl = Dom.get(id);

			// We are only concerned with list items, we ignore the dragover
			// notifications for the list.
			if (destEl.nodeName.toLowerCase() == "li") {
				var orig_p = srcEl.parentNode;
				var p = destEl.parentNode;

				if (this.goingUp) {
					p.insertBefore(srcEl, destEl); // insert above
				} else {
					p.insertBefore(srcEl, destEl.nextSibling); // insert below
				}

				DDM.refreshCache();
			}
		}
	});
	Event.onDOMReady(YAHOO.example.DDApp.init, YAHOO.example.DDApp, true);
}

/* this is used to create DragList which also have search option

Example :
var dl = new Cyberoam.dragListWithSearch( {id:"Nirav",labelDisplay:"Select Item",data:[{label:"id",key:"d1",selected:false,disable:false},{label:"Name",key:"d2",selected:false,disable:false},{label:"Identity",key:"d3",selected:false,disable:false},{label:"Application Filter",key:"d4",selected:false,disable:false},{label:"QoS",key:"d5",selected:false,disable:false},{label:"Upload Data",key:"d6",selected:false,disable:false},{label:"Download Data",key:"d7",selected:false,disable:false}],style:"",height:300,width:170,afterOk:abc,dragable:true} );

		1)parameter: 	1)id
						2)data : label
								 key
								 selected : true    selected
											false   unselected
								 Disable  : true  Disable
										  : false : Enable

						3)style
						4)height
						5)width

						6)afterOk : pass which function you want to call after pressing Ok Button of DragList

						7)Dragable : true allow to drage data component
									 false not allow

		2) You will get selected Keys or key.
			c.getSelectedKeys()
		3) You will get label of Selected Nodes. in single select you get only one node.
			c.getSelectedLabels()
		4) You will get selected Nodes.
			c.getSelectedItems()

*/


Cyberoam.dragListWithSearch = function(d) {
	this.config = {id:"",data:[],style:"",height:"auto",width:150,labelDisplay:"select",afterOk:"",dragable:true,dragListType:Cyberoam.dragListWithSearch.SELECT_COLUNM};
	this.selectedItem = [];
	this.selectedKeys = [];
	this.selectedItemByIndex=null;
	for (var key in d) {
		if(this.config[key] != "undefined" ){
			this.config[key] = d[key];
		}else{
			 Cyberoam.messageBox({message: "Wrong Combobox Configuration "+key});
			 this.config = {"id":"","data":[],style:"",height:200,width:150,addOperation:""};
			 return;
		}
	}
};

Cyberoam.dragListWithSearch.SELECT_COLUNM = 0;
