Cyberoam.dragListWithSearch.prototype.create = function()	{
	$("#"+this.config.id).html("");
	var myobject=this;
	var id=this.config.id;

	var $contrainer = jQuery("#"+id).addClass("draglist_container").on('click',function() {
		var obj = document.getElementById("DragList_body"+myobject.config.id);
		if(obj.style.display==""){
			myobject.hide();
		}else{
			myobject.show();
		}
	});

	jQuery("#"+id).on('mouseover',function(){
		$(this).addClass("draglist_container_hilite");
		$("#DragList_item_"+id).addClass("draglist_select_hilite");
		$("#Combo_button"+id).addClass("draglist_button_hilite");
	});
	jQuery("#"+id).on('mouseout',function(){
		$(this).removeClass("draglist_container_hilite");
		$("#DragList_item_"+id).removeClass("draglist_select_hilite");
		$("#Combo_button"+id).removeClass("draglist_button_hilite");

	});
	var $title1 = $("<div></div>").addClass("draglist-type-filter-title").html(myobject.config.labelDisplay).hide().appendTo($contrainer);
	var $subContrainer = $("<div></div>").attr("id","DragList_item_"+id).addClass("draglist_select").html(myobject.config.labelDisplay).appendTo($contrainer);
	var $subContrainer2 = $("<div></div>").attr("id","Combo_button"+id).addClass("draglist_button").html("").appendTo($contrainer);

	var className2 = "";
	if(Cyberoam.dragListWithSearch.SELECT_FILTER == this.config.dragListType) {
		$contrainer.addClass("draglist-container-type-filter")
		$subContrainer.addClass("draglist-type-filter");
		className2 = "draglist-combo-body-filter";
		$title1.show();
		$subContrainer.empty();
		var $icon1 = $("<i></i>").addClass("fa").addClass("fa-sort").addClass("fa-1x").css({"float":"right","margin-top":"3px"}).appendTo($subContrainer);
		var $label = $("<div></div>").css({"float":"left","overflow":"hidden","white-space":"nowrap","text-overflow":"ellipsis","width":"88%"}).addClass("draglist-filter-label").appendTo($subContrainer);
	}
	$("body").append(jQuery("<div id=DragList_body"+id + " class ='Combo_body draglist-combo-body "+className2+"' style='display:none'></div>"));
	this.setBody() ;
};//create

Cyberoam.dragListWithSearch.prototype.setIndexAndItem = function(){
	var myobject=this;
	var kids=document.getElementById("DragList_body"+myobject.config.id).childNodes[1].childNodes;

	for(var i=0;i<kids.length;i++) {
		var $a = $(kids[i]).find(".dragList1_item");
		if( $a.is(".selected")){ //Item should be selected and not disabled then put in to array for selected list
				myobject.pushKeyInSelectedKeys(myobject, kids[i].getAttribute("key"), kids[i].getAttribute("label"));
		} else {
			myobject.removeItem(kids[i].getAttribute("key"));
		}
	}
	if(this.selectedItem.length == 0 && Cyberoam.dragListWithSearch.SELECT_FILTER == this.config.dragListType) {
		$("#DragList_item_"+myobject.config.id+" .draglist-filter-label").eq(0).html(Language.All);
	}
};

Cyberoam.dragListWithSearch.prototype.getSelectedKeys = function() {
	return this.selectedKeys;
};
Cyberoam.dragListWithSearch.prototype.getSelectedLabels = function() {
	var arr=[];
	for(var i=0;i<this.selectedKeys.length;i++){
		arr.push(this.selectedItem[i].label);
	}
	return arr;
};
Cyberoam.dragListWithSearch.prototype.getSelectedItems = function() {
	return this.selectedItem;
};
Cyberoam.dragListWithSearch.prototype.hideAndGetSelected = function() {
	this.setIndexAndItem();
	var obj = document.getElementById("DragList_body"+this.config.id);
	if(obj.style.display==""){
			this.hide();
	}
};
Cyberoam.dragListWithSearch.prototype.getItemByIndex=function(index){
	if(this.config.data[index])
		return this.config.data[index];
};
Cyberoam.dragListWithSearch.prototype.divClickEvent = function(event,object) {
	var myobject=this;
	var $div = $(object).find(".dragList1_item");
	var key = $(object).attr("key");
	var label = $(object).attr("label");
	if(!$div.is(".disabled")) {
		if($div.is(".selected")) {
			$div.removeClass("selected");
			myobject.removeItem(key);
		} else {
			$div.addClass("selected");
			myobject.pushKeyInSelectedKeys(myobject, key, label);
		}
	}
};
Cyberoam.dragListWithSearch.prototype.show = function(){
	if(!this.config.disabled)  {
		var comboObject = jQuery("#"+this.config.id);
		var obj = document.getElementById("DragList_body"+this.config.id);
		if(Cyberoam.pageLayer > 0)
			obj.style.zIndex = Cyberoam.pageLayer*200 + 5;
		obj.style.top = (comboObject.offset().top + comboObject.height())+"px";
		obj.style.left = (comboObject.offset().left)+"px";
		obj.style.display="";
		Cyberoam.currentObject = this;
	}
};
Cyberoam.dragListWithSearch.prototype.hide = function(){
	document.getElementById("DragList_body"+this.config.id).style.display="none";
	Cyberoam.currentObject = null;
};
Cyberoam.dragListWithSearch.prototype.getOffsetPosition = function(){
	var bodyObject = document.getElementById("DragList_body"+this.config.id);
	return [new Cyberoam.Point(parseInt(bodyObject.style.left),parseInt(bodyObject.style.top)),new Cyberoam.Point((parseInt(bodyObject.style.left)+bodyObject.offsetWidth),(parseInt(bodyObject.style.top) + bodyObject.offsetHeight))];
};
Cyberoam.dragListWithSearch.prototype.removeItem= function(key) {
	for(var i=0;i<this.selectedItem.length;i++){
		if(this.selectedItem[i]["key"] == key){
			this.selectedItem.splice(i,1);
			this.selectedKeys.splice(this.selectedKeys.indexOf(key), 1);
		}
	}
}
Cyberoam.dragListWithSearch.prototype.setSelectAllItems= function(isSelected,applyOnDisabled) {
	if(isSelected == undefined)
		isSelected = true;
	if(applyOnDisabled == undefined)
		applyOnDisabled = false;
	var kids=document.getElementById("DragList_body"+this.config.id).childNodes[1].childNodes;
	for(var i=0;i<kids.length;i++) {
		var $a = $(kids[i]).find(".dragList1_item");
		if($a.is(".disabled")) { //Is checkbox is disabled ?
			if(!applyOnDisabled) continue;
			if(isSelected) {
				$a.removeClass("selected").addClass("selected");
			} else {
				$a.removeClass("selected");
			}
		} else { // Is not disabled checkbox?
			if(isSelected) {
				$a.removeClass("selected").addClass("selected");
			} else {
				$a.removeClass("selected");
			}
		}
	}
	this.setIndexAndItem();
};

Cyberoam.dragListWithSearch.prototype.dragListYUI = function() {
	var id = this.config.id;
	var Dom = YAHOO.util.Dom;
	var Event = YAHOO.util.Event;
	var DDM = YAHOO.util.DragDropMgr;
	YAHOO.example.DDApp = {
		init: function() {
			var target = new YAHOO.util.DDTarget("DragList_Items"+id);
			var ele = document.getElementById("DragList_Items"+id);
			for (i=0;i<ele.childNodes.length;i=i+1) {
				if(ele.childNodes[i].className.indexOf("_disable") == -1){
					var list = new YAHOO.example.DDList(ele.childNodes[i].id);
				}
			}
		}
	};
}
Cyberoam.dragListWithSearch.prototype.searchArray = function(e,data,html) {
	var getValue;
	var that = this;
	setTimeout(function() {
		getValue = document.getElementById(data.id).value;
		var searchArray = that.search(getValue,that);
		if(data.id != "") {
			Cyberoam.dragListWithSearch.prototype.setBody_i(that,searchArray,html);
		}
	}, 0)
}
Cyberoam.dragListWithSearch.prototype.search = function(searchName, currentObject){
	var arrayNew = [];
	var data = JSON.parse(JSON.stringify(currentObject.config.data));
    for (var i = 0; i < data.length; i++) {
    	var t1 = data[i].label.toLowerCase();
    	var t2 = searchName.toLowerCase();
    	if (t1.startsWith(t2)) {
            arrayNew.push(data[i]);
    		if (currentObject.selectedKeys.indexOf(data[i].key) != -1) {
    			arrayNew[arrayNew.length-1].isSelected = true;
    		}
        }
    }
    return arrayNew;
}
Cyberoam.dragListWithSearch.prototype.setBody_i = function(myobject,arr,html) {
	var id = myobject.config.id;
	var searchVal = $('#DragList_body'+id).find(".comboSearchInput").val();
	$("#DragList_Items"+id+" li").remove();
	for(var i=0;i<arr.length;i++){
		if(searchVal && arr[i].label == Language.All) {
			continue;
		}
			var divIconConfig = {tag:"div"};
			var divTextObjConfig  = {tag:"div"};
			var config = {tag:"li",id:"Combo_item_"+id+"_"+arr[i].key};

			if(myobject.selectedItemtemp != undefined && myobject.selectedItemtemp.length > 0) {
				for(var j=0; j < myobject.selectedItemtemp.length; j++ ){
					if(myobject.selectedItemtemp[j].key == arr[i].key ){
						arr[i].tempSelected = true;
					}
				}
			}
			if(arr[i].disable && arr[i].isSelected ){
				divIconConfig["className"] = 'dragList1_item selected disabled';
				myobject.pushKeyInSelectedKeys(myobject, arr[i].key);
			}else if(arr[i].disable && !arr[i].isSelected ){
				divIconConfig["className"] = 'dragList1_item disabled';
			}else if(!arr[i].disable && arr[i].isSelected){
				divIconConfig["className"] = 'dragList1_item selected';
				myobject.pushKeyInSelectedKeys(myobject, arr[i].key);
			}else{
				divIconConfig["className"] = 'dragList1_item';
			}


			var liObject = Cyberoam.createElement(config,html);
			var divIcon = Cyberoam.createElement(divIconConfig,liObject);
			var divTextObj = Cyberoam.createElement(divTextObjConfig,liObject);
			liObject.setAttribute("key", arr[i].key);
			liObject.setAttribute("label", arr[i].label);
			$(liObject).css({"list-style":"none"});
			$(divTextObj).css({"white-space":"nowrap","text-overflow": "ellipsis","overflow": "hidden"});
			$(divTextObj).attr('title',arr[i].label);
			liObject.onclick = function(e){myobject.divClickEvent(e,this)};
			divTextObj.appendChild(document.createTextNode(arr[i].label));
	}//for

	this.bindEvent(id, myobject);
}

Cyberoam.dragListWithSearch.prototype.bindEvent = function(id, myobject) {
	var $mainBody = $('#DragList_body'+id+' li');
	var idOfAll = "Combo_item_"+id+"_0";
	var $allEle = $("#"+idOfAll);
	if ($allEle.length && $mainBody.find("div.selected").length == ($mainBody.length -1)) {
		myobject.setSelectAllItems(true,false);
	}
	$mainBody.on('click',function(){
		if($(this).attr('id') == idOfAll){
			var temp = $allEle.find( ".selected" );
			if(temp.length){
				myobject.setSelectAllItems(true,false);
			 }else{
				 myobject.setSelectAllItems(false,false);
			 }
		}else{
			var temp = $allEle.find( ".selected" );
			if(temp.length){
				$allEle.find(".selected").removeClass("selected");
			} else if ($allEle.length && $mainBody.find("div.selected").length == ($mainBody.length -1)) {
				//To select 'All' option when user manually select every item in list
				myobject.setSelectAllItems(true,false);
			}
		}
	});
}
Cyberoam.dragListWithSearch.prototype.pushKeyInSelectedKeys = function(myobject, key, label){
	if(myobject.selectedKeys.indexOf(key) == -1 && key != "0"){
		myobject.selectedKeys.push(key);
		myobject.selectedItem.push({key:key,label:label});
	}
}


//=======================================================================
/*

this file is user to create DragList qhich support filter tags too

	functions

	---------
	var dl = new Cyberoam.dragListWithFilter( {id:"Nirav",labelDisplay:"Select Item",data:[{label:"id",key:"d1",selected:false,disable:false},{label:"Name",key:"d2",selected:false,disable:false},{label:"Identity",key:"d3",selected:false,disable:false},{label:"Application Filter",key:"d4",selected:false,disable:false},{label:"QoS",key:"d5",selected:false,disable:false},{label:"Upload Data",key:"d6",selected:false,disable:false},{label:"Download Data",key:"d7",selected:false,disable:false}] ,
	style:"", height:300,width:170,afterOk:abc,dragable:true} );

		1)parameter: 	1)id
						2)data : label
								 key
								 selected : true    selected
											false   unselected
								 Disable  : true  Disable
										  : false : Enable

						3)style
						4)height
						5)width

						6)afterOk : pass which function you want to call after pressing Ok Button of DragList

						7)Dragable : true allow to drage data component
									 false not allow

		2) You will get selected Keys or key.
			c.getSelectedKeys()
		3) You will get label of Selected Nodes. in single select you get only one node.
			c.getSelectedLabels()
		4) You will get selected Nodes.
			c.getSelectedItems()

*/


Cyberoam.dragListWithFilter = function(d) {
	this.config = {id:"",data:[],style:"",height:"auto",width:150,labelDisplay:"select",afterOk:"",dragable:true,dragListType:Cyberoam.dragListWithFilter.SELECT_COLUNM};
	this.selectedItem = [];
	this.selectedIndex = [] ;
	this.selectedItemByIndex=null;
	for (var key in d) {
		if(this.config[key] != "undefined" ){
			this.config[key] = d[key];
		}else{
			 Cyberoam.messageBox({message: "Wrong Combobox Configuration "+key});
			 this.config = {"id":"","data":[],style:"",height:200,width:150,addOperation:""};
			 return;
		}
	}
};

Cyberoam.dragListWithFilter.SELECT_COLUNM = 0;
Cyberoam.dragListWithFilter.SELECT_FILTER = 1;


Cyberoam.dragListWithFilter.prototype.setBody = function() {
	$("#DragList_body"+this.config.id).html("");
	var myobject=this;
	var id=this.config.id;
	var arr=[];
	arr=this.config.data;
	var mainElement = document.getElementById("DragList_body"+id);
	var html = Cyberoam.createElement({tag:"div",id:"DragList_Items"+id,className:"DragList-Items-class"},mainElement);
	html.style.overflowX ="hidden";
	html.style.overflowY ="auto";
	html.style.maxHeight ="200px";
	var label1 = "";
	myobject.searchTag = new Cyberoam.searchTag(myobject);
	if(id != ""){
		var i=0;
			for(i=0;i<arr.length;i++){
				var divIconConfig = {tag:"div"};
				var divTextObjConfig  = {tag:"div"};
				var config = {tag:"li",id:"Combo_item_"+id+"_"+arr[i].key};
				if(arr[i].disable && arr[i].selected ){
					divIconConfig["className"] = 'dragList1_item selected disabled';
					myobject.selectedItem.push({key:arr[i].key,label:arr[i].label});
					myobject.selectedIndex.push(i);
				}else if(arr[i].disable && !arr[i].selected ){
					divIconConfig["className"] = 'dragList1_item disabled';
				}else if(!arr[i].disable && arr[i].selected){
					divIconConfig["className"] = 'dragList1_item selected';
					myobject.selectedItem.push({key:arr[i].key,label:arr[i].label});
					myobject.selectedIndex.push(i);
				}else{
					divIconConfig["className"] = 'dragList1_item';
				}
				var liObject = Cyberoam.createElement(config,html);
				var divIcon = Cyberoam.createElement(divIconConfig,liObject);
				var divTextObj = Cyberoam.createElement(divTextObjConfig,liObject);
				liObject.setAttribute("key", arr[i].key);
				liObject.setAttribute("label", arr[i].label);
				$(liObject).css({"list-style":"none"});
				$(divTextObj).css({"white-space":"nowrap","text-overflow": "ellipsis","overflow": "hidden"});
				$(divTextObj).attr('title',arr[i].label);
				liObject.onclick = function(e){myobject.divClickEvent(e,this)};
				divTextObj.appendChild(document.createTextNode(arr[i].label));
				if(arr[i].selected && Cyberoam.dragListWithFilter.SELECT_FILTER == this.config.dragListType) {
					if(label1 != "")
						label1 = label1 + ", ";
					label1 = label1 +arr[i].label;
				}
				//TO REMOVE
				if(arr[i].selected && Cyberoam.dragListWithFilter.SELECT_COLUNM == this.config.dragListType) {
					if(label1 != "")
						label1 = label1 + ", ";
					label1 = label1 +arr[i].label;
				}
			}//for
			if(myobject.selectedItem.length){
				myobject.searchTag.create();
			}
			divObject = Cyberoam.createElement({tag:"div"},mainElement);
			divObject.style.backgroundColor="#FFF";
			divObject.style.paddingTop = "8px";
			divObject.style.paddingBottom = "5px";
			divObject.setAttribute("align","center");
			inputObject = Cyberoam.createElement({id:"draglist_okBtn_"+myobject.config.id,tag:"input",className:"draglist-primary-btn",type:"button"},divObject);
			inputObject.onclick = function(e) {
				myobject.hideAndGetSelected(e,this);
				if(myobject.config.dragListType == Cyberoam.dragListWithFilter.SELECT_FILTER) {
					var $subContrainer = $("#DragList_item_"+myobject.config.id+" .draglist-filter-label");
					var lbl = myobject.getSelectedLabels().join(", ");
					if(lbl == "")
						$subContrainer.html(Language.All);
					else
						$subContrainer.html(lbl);
				}

				//TO REMOVE
				if(myobject.config.dragListType == Cyberoam.dragListWithFilter.SELECT_COLUNM) {
					var $subContrainer = $("#DragList_item_"+myobject.config.id  + " .text");
					var $iconSpan = $("#DragList_item_"+myobject.config.id + " .iconSpanDiv");
					var lbl = myobject.getSelectedLabels().join(", ");
					if(lbl == "") {
						$iconSpan.hide();
					}else {
						$iconSpan.show();
					}
				}

				if(myobject.config.displaySelectedTag){
					myobject.searchTag.create();
				}

				if(myobject.config.afterOk != ""){
					myobject.config.afterOk(myobject);
				}
			};
			if(this.config.dragable && myobject.config.dragListType != Cyberoam.dragListWithFilter.SELECT_FILTER) {
				$("<label></label>").text(Language.dragToMoveColumn).css({"color":"#7f8b93","font-size":"11px","font-family":"'SophosSansRegular',arial,sans-serif","padding":"0px 0px 1px 4px"}).appendTo(mainElement);
			}
			if(myobject.config.dragListType == Cyberoam.dragListWithFilter.SELECT_FILTER) {
				inputObject.setAttribute("value",Language.Save);
			} else {
				inputObject.setAttribute("value",Language.OkCC);
			}

		}
	mainElement.style.height = "auto";
	mainElement.style["border-radius"] = "3px";
	mainElement.style.width = this.config.width+30+"px";

	if(jQuery(mainElement).height() > parseInt(this.config.height)+5){
		mainElement.childNodes[0].style.height = (this.config.height - 25)+"px";
		mainElement.style.height = this.config.height+"px";
	}
	if(this.config.dragable){
		this.dragListYUI();
	}
	if(Cyberoam.dragListWithFilter.SELECT_FILTER == this.config.dragListType) {
		var $subContrainer = $("#DragList_item_"+myobject.config.id+" .draglist-filter-label");
		if(label1 == ""){
			$subContrainer.html(Language.All);
		}else{
			$subContrainer.html(label1);
		}
	}

	//TO REMOVE
	if(Cyberoam.dragListWithFilter.SELECT_COLUNM == this.config.dragListType) {
		var $subContrainer = $("#DragList_item_"+myobject.config.id + " .text");
		var $iconSpan = $("#DragList_item_"+myobject.config.id + " .iconSpanDiv");
		$subContrainer.html(myobject.config.labelDisplay);
		if(label1 == ""){
			$iconSpan.hide();
		}else {
			$iconSpan.show();
		}
	}
};

Cyberoam.dragListWithFilter.prototype.create = function()	{
	$("#"+this.config.id).html("");
	var myobject=this;
	var id=this.config.id;

	var $contrainer = jQuery("#"+id).addClass("draglist_container").on('click',function() {
		var obj = document.getElementById("DragList_body"+myobject.config.id);
		if(obj.style.display==""){
			myobject.hide();
		}else{
			myobject.show();
		}
	});

	$contrainer.wrap('<div id="'+myobject.config.id+'Div" class="dragFilterContainer"></div>');
	$contrainer.after('<span class="iconspan"><i class="fa fa-caret-down"></i></span>');

	$("#"+myobject.config.id+"Div .iconspan").on('click',function(e){
		$(this).closest(".dragFilterContainer").find(".draglist_container").trigger('click');
	});

	jQuery("#"+id).on('mouseover',function(){
		$(this).addClass("draglist_container_hilite");
		$("#DragList_item_"+id).addClass("draglist_select_hilite");
		$("#Combo_button"+id).addClass("draglist_button_hilite");
	});
	jQuery("#"+id).on('mouseout',function(){
		$(this).removeClass("draglist_container_hilite");
		$("#DragList_item_"+id).removeClass("draglist_select_hilite");
		$("#Combo_button"+id).removeClass("draglist_button_hilite");

	});
	var $title1 = $("<div></div>").addClass("draglist-type-filter-title").html(myobject.config.labelDisplay).hide().appendTo($contrainer);
	var $subContrainer = $("<div></div>").attr("id","DragList_item_"+id).addClass("draglist_select").html('<span class="text">'+myobject.config.labelDisplay+'</span><span class="icon-circle-check iconSpanDiv"></span>').appendTo($contrainer);
	var $subContrainer2 = $("<div></div>").attr("id","Combo_button"+id).addClass("draglist_button").html("").appendTo($contrainer);

	var className2 = "";
	if(Cyberoam.dragListWithFilter.SELECT_FILTER == this.config.dragListType) {
		$contrainer.addClass("draglist-container-type-filter")
		$subContrainer.addClass("draglist-type-filter");
		className2 = "draglist-combo-body-filter";
		$title1.show();
		$subContrainer.empty();
		var $icon1 = $("<i></i>").addClass("fa").addClass("fa-sort").addClass("fa-1x").css({"float":"right","margin-top":"3px"}).appendTo($subContrainer);
		var $label = $("<div></div>").css({"float":"left","overflow":"hidden","white-space":"nowrap","text-overflow":"ellipsis","width":"88%"}).addClass("draglist-filter-label").appendTo($subContrainer);
	}

	if(!Cyberoam.isCCC)
		jQuery("#mainbody").parent().append(jQuery("<div id=DragList_body"+id + " class ='Combo_body draglist-combo-body "+className2+"' style='display:none'></div>"));
	else
		jQuery("#wrapper").parent().append(jQuery("<div id=DragList_body"+id + " class ='Combo_body draglist-combo-body "+className2+"' style='display:none'></div>"));
	this.setBody() ;
};//create

Cyberoam.dragListWithFilter.prototype.setIndexAndItem = function(){
	var myobject=this;
	myobject.selectedItem=[];
	myobject.selectedIndex=[];
	var kids=document.getElementById("DragList_body"+myobject.config.id).childNodes[0].childNodes;

	for(var i=0;i<kids.length;i++) {
		var $a = $(kids[i]).find(".dragList1_item");
		if( $a.is(".selected")){ //Item should be selected and not disabled then put in to array for selected list
				myobject.selectedItem.push({key:kids[i].getAttribute("key"),label:kids[i].getAttribute("label")});
				myobject.selectedIndex.push(i);
		}
	}

	if(this.selectedItem.length == 0 && Cyberoam.dragListWithFilter.SELECT_FILTER == this.config.dragListType) {
		$("#DragList_item_"+myobject.config.id+" .draglist-filter-label").eq(0).html(Language.All);
	}
	//TO REMOVE
	if(this.selectedItem.length == 0 && Cyberoam.dragListWithFilter.SELECT_COLUNM == this.config.dragListType) {
		var $mainDiv = $("#DragList_item_"+myobject.config.id);
		$mainDiv.find(".text").html(myobject.config.labelDisplay);
		$mainDiv.find(".text").attr("title", myobject.config.labelDisplay);
		$mainDiv.find(".iconSpanDiv").hide();
	}
};

Cyberoam.dragListWithFilter.prototype.getSelectedKeys = function() {
	var arr=[];
	for(var i=0;i<this.selectedIndex.length;i++){
		arr.push(this.selectedItem[i].key);
	}
	return arr;
};
Cyberoam.dragListWithFilter.prototype.getSelectedLabels = function() {
	var arr=[];
	for(var i=0;i<this.selectedIndex.length;i++){
		arr.push(this.selectedItem[i].label);
	}
	return arr;
};
Cyberoam.dragListWithFilter.prototype.getSelectedItems = function() {
	return this.selectedItem;
};
Cyberoam.dragListWithFilter.prototype.hideAndGetSelected = function() {
	this.setIndexAndItem();
	var obj = document.getElementById("DragList_body"+this.config.id);
	if(obj.style.display==""){
			this.hide();
	}
};
Cyberoam.dragListWithFilter.prototype.getItemByIndex=function(index){
	if(this.config.data[index])
		return this.config.data[index];
};
Cyberoam.dragListWithFilter.prototype.divClickEvent = function(event,object) {
	var myobject=this;
	var $div = $(object).find(".dragList1_item");
	if(!$div.is(".disabled")) {
		if($div.is(".selected")) {
			$div.removeClass("selected");
		} else {
			$div.addClass("selected");
		}
	}

};

Cyberoam.dragListWithFilter.prototype.show = function(){
	if(!this.config.disabled)  {
		var comboObject = jQuery("#"+this.config.id);
		var obj = document.getElementById("DragList_body"+this.config.id);
		if(Cyberoam.pageLayer > 0)
			obj.style.zIndex = Cyberoam.pageLayer*200 + 5;
		obj.style.top = (comboObject.offset().top + comboObject.height())+"px";
		obj.style.left = (comboObject.offset().left)-1+"px";
		obj.style.display="";
		obj.style["min-height"]="auto";
		Cyberoam.currentObject = this;
	}
};
Cyberoam.dragListWithFilter.prototype.hide = function(){
	document.getElementById("DragList_body"+this.config.id).style.display="none";
	Cyberoam.currentObject = null;
};
Cyberoam.dragListWithFilter.prototype.getOffsetPosition = function(){
	var bodyObject = document.getElementById("DragList_body"+this.config.id);
	return [new Cyberoam.Point(parseInt(bodyObject.style.left),parseInt(bodyObject.style.top)),new Cyberoam.Point((parseInt(bodyObject.style.left)+bodyObject.offsetWidth),(parseInt(bodyObject.style.top) + bodyObject.offsetHeight))];
};

Cyberoam.dragListWithFilter.prototype.setSelectAllItems= function(isSelected,applyOnDisabled) {
	if(isSelected == undefined)
		isSelected = true;
	if(applyOnDisabled == undefined)
		applyOnDisabled = false;
	var kids=document.getElementById("DragList_body"+this.config.id).childNodes[0].childNodes;
	for(var i=0;i<kids.length;i++) {
		var $a = $(kids[i]).find(".dragList1_item");
		if($a.is(".disabled")) { //Is checkbox is disabled ?
			if(!applyOnDisabled) continue;
			if(isSelected) {
				$a.removeClass("selected").addClass("selected");
			} else {
				$a.removeClass("selected");
			}
		} else { // Is not disabled checkbox?
			if(isSelected) {
				$a.removeClass("selected").addClass("selected");
			} else {
				$a.removeClass("selected");
			}
		}
	}
	this.setIndexAndItem();
};


Cyberoam.dragListWithFilter.prototype.removeItem= function(key) {
	for(var i=0;i<this.selectedItem.length;i++){
		if(this.selectedItem[i]["key"] == key){
			this.selectedItem.splice(i,1);
			this.selectedIndex.splice(i,1);
		}
	}
}

Cyberoam.dragListWithFilter.prototype.dragListYUI = function() {
	var id = this.config.id;
	var Dom = YAHOO.util.Dom;
	var Event = YAHOO.util.Event;
	var DDM = YAHOO.util.DragDropMgr;
	YAHOO.example.DDApp = {
		init: function() {
			var target = new YAHOO.util.DDTarget("DragList_Items"+id);
			var ele = document.getElementById("DragList_Items"+id);
			for (i=0;i<ele.childNodes.length;i=i+1) {
				if(ele.childNodes[i].className.indexOf("_disable") == -1){
					var list = new YAHOO.example.DDList(ele.childNodes[i].id);
				}
			}
		}
	};
}

Cyberoam.dragListWithFilter.prototype.clearFilter= function() {
	this.setSelectAllItems(false,false);
	this.config.afterOk(this);
}


