//Init Search Tag
Cyberoam.searchTag = function(mainObj) {
	this.tagConfig = mainObj.config.tagConfig;
	if(!mainObj.config.displaySelectedTag){
		return;
	} else if(!mainObj.config.tagConfig){
		Cyberoam.messageBox({message: "Config parameters are missing" });
		return;
	}
	if(!this.tagConfig.maximumCharToDisplay){
		this.tagConfig.maximumCharToDisplay = 35;
	}
	if(this.tagConfig.inputId){
		this.tagConfig.getSelectedLabelMethod = "none";
	}
	var configParam = {parentContainerId : "", tagContainerId : "", clearFilterMethod : "", getSelectedLabelMethod :"", displayLabel:""}
	for (var key in configParam) {
		if(!(this.tagConfig[key] && this.tagConfig[key] != "undefined") ){
			//alert("Wrong Configuration : "+key);
			// return;
		}
	}
	var $parentContainer = $("#" + this.tagConfig.parentContainerId);
	if(!$parentContainer.length){
		Cyberoam.messageBox({message: "Container div is not available"});
		return;
	}
	if(this.tagConfig.inputId){
		var $inputBox = $("#" + this.tagConfig.inputId);
		if(!$inputBox.length){
			Cyberoam.messageBox({message: "Input box is not available" });
			return;
		}
	} else {
		this.parentThisObj = mainObj;
		/*var selectedLableMethod = this.tagConfig.getSelectedLabelMethod;
		if(!this.parentThisObj[selectedLableMethod]){
			alert("Undefined method : "+selectedLableMethod);
			return;
		}*/
		var clearMethod = this.tagConfig.clearFilterMethod;
		if(!this.parentThisObj[clearMethod]){
			//alert("Undefined method : "+clearMethod);
			//return;
		}
	}
};

//Create selected label tags
Cyberoam.searchTag.prototype.create = function(){
	var fieldKey, thisObj = this;
	var selectedLableMethod = thisObj.tagConfig.getSelectedLabelMethod;
    $parentContainer = $("#" + thisObj.tagConfig.parentContainerId);
	$tagContainer = $("#" + thisObj.tagConfig.tagContainerId);
	var title = lbl = "";
	if(thisObj.tagConfig.getTagsLabel){
		title = lbl = thisObj.parentThisObj.getTagsLabel();
		fieldKey = thisObj.parentThisObj.getKeyFilterVal().key;
	} else if(thisObj.tagConfig.inputId){
		title = lbl = $("#" + thisObj.tagConfig.inputId).val();
	} else {
		title = lbl = thisObj.parentThisObj[selectedLableMethod]().join(", ");
	}
	if(lbl) {
		if(thisObj.tagConfig.displayLabel){
			lbl = thisObj.tagConfig.displayLabel + " : " + lbl;
		}
		if(lbl.length > thisObj.tagConfig.maximumCharToDisplay){
			lbl = lbl.substr(0, thisObj.tagConfig.maximumCharToDisplay) + "...";
		}
		if($tagContainer.length){
			$("#"+thisObj.tagConfig.tagContainerId + " .searchTagLbl").text(lbl);
			$("#"+thisObj.tagConfig.tagContainerId + " .searchTagLbl").attr("title", title);
		} else {
			var $html = $('<span class="searchTagMaindiv '+thisObj.tagConfig.tagClass+'"> \
							<span class="searchTagFilterDiv"> \
								<span class="searchTagLbl" style="vertical-align: middle;"></span> \
								<span class="removeTag icomoon-x '+thisObj.tagConfig.tagRemoveClass+'" style="cursor:pointer;vertical-align: middle;" ></span> \
							</span> \
						</span>');

			$html.attr("parentKey", fieldKey);
			$html.attr("id", thisObj.tagConfig.tagContainerId);
			$html.find(".searchTagLbl").attr("title", title);
			$html.find(".searchTagLbl").text(lbl);
			$parentContainer.append($html);
			$("#" + thisObj.tagConfig.tagContainerId + " .removeTag").on('click',function(){
				thisObj.remove($(this));
			});
		}
	} else {
		thisObj.remove();
	}
};//create

//Remove widget
Cyberoam.searchTag.prototype.remove = function($this){
	var thisObj = this;
	var clearMethod = thisObj.tagConfig.clearFilterMethod;
	var key;
	if($this && $this.length){
		key = $this.closest(".searchTagMaindiv").attr("parentkey");
		$this.closest(".searchTagMaindiv").remove();
	} else {
		$("#" + thisObj.tagConfig.tagContainerId).remove();
	}
	if(this.tagConfig.inputId){
		$("#" + thisObj.tagConfig.inputId).val("");
		thisObj.tagConfig.clearFilterMethod();
	} else if (thisObj.parentThisObj[clearMethod]){
		thisObj.parentThisObj[clearMethod]();
	} else if (thisObj.tagConfig.clearFilterMethod){
		if($this && $this.length){
			thisObj.tagConfig.clearFilterMethod(key, "");
		}
	}
}
//Remove widget
Cyberoam.searchTag.prototype.removeTag = function(){
	var thisObj = this;

	if(this.tagConfig.inputId){
		$("#" + thisObj.tagConfig.inputId).val("");
	}
	$("#" + thisObj.tagConfig.tagContainerId).remove();
}
