Cyberoam.advanceFilterComponent = function (mainObj) {
	this.config = mainObj;
	if(this.config.placeholderId){
		this.createButton();
	} else {
		Cyberoam.messageBox({message: "Placeholder Div is not defined"});
	}
}

Cyberoam.advanceFilterComponent.prototype.createButton = function(){
	var myObject = this;
	var $div = $("#" + myObject.config.placeholderId);
	if($div.length){
		$div.append('<div id="advanceFilterButton" title="Add filter"><label>'+myObject.config.buttonLable+'</label><div class="advanceFilterIcon fa fa-sort-desc"></div><div class="fa fa-caret-down" style="margin-left: 5px; font-size: 15px;></div></div>');
		$("#advanceFilterButton").on('click',function(){
			if($("#advanceFilterOpenBox").length){
				$("#advanceFilterOpenBox").remove();
			} else {
				$div.append(myObject.returnPopupHtml());
			}
			myObject.bindEvents($div);
		});
	} else {
		Cyberoam.messageBox({message: "Placeholder Div is not found"});
	}
}

Cyberoam.advanceFilterComponent.prototype.returnPopupHtml = function(){
	var myObject = this;
	var key = conditionOptionHtml = "";
	for (key in myObject.config.field) {
		if(myObject.config.field.hasOwnProperty(key)) {
			var obj = myObject.config.field[key];
			conditionOptionHtml += '<option tagLable="' + obj.TagLable + '" value="' + obj.Value + '" filtertype="' + obj.filterType + '">' + obj.ComponentLable + '</option>';
		}
	}
	var mainDivHtml = $('<div id="advanceFilterOpenBox" class="advanceFilterPopupOpenBox">\
							<div class="advanceFilterWrapperDiv">\
								<div class="advanceFilterBoxFirstLineDiv">\
									<div class="advanceFilterBoxFontFiled advanceFilterBoxSecondLineDiv"><label id="Language.Add_Filter">Add filter</label></div>\
									<div id="advanceFilterBoxSecondLineDivClose" class="fa fa-times fa-3x advanceFilterBoxSecondLineDivClose"></div>\
								</div>\
								<div class="advanceFilterBoxFieldsText"><label id="Language.Field">Field</label>: </div>\
								<div>\
									<select id="advancefieldselection"  class="advanceFieldSelection">\
									'+conditionOptionHtml+'\
									</select>\
								</div>\
								<div class="advanceFilterBoxFieldsText adavnceFilterConditionDiv"><label id="Language.Condition">Condition</label>: </div>\
								<div><select id="advanceconditionselection" class="adavnceFilterConditionDiv advanceFieldSelection"></select></div>\
								<div class="advanceFilterBoxFieldsText thirdBox"></div>\
								<div id="advanceFilterBoxValue" style="margin:30px 0px 0px 5px;"></div>\
								<div class="advanceFilterBoxSubmitButtonDiv"><input type="submit" id="advanceFilterBoxSubmit" class="cp-btn cp-green-btn" value="'+Language.Add_Filter+'"></div>\
							</div>\
						</div>');
	
	return 	mainDivHtml;
}

Cyberoam.advanceFilterComponent.prototype.bindEvents = function($div){
	var myObject = this;
	$("#advanceFilterBoxSecondLineDivClose").on('click',function(){
		myObject.hidePopup();
	});

	$(document).on('click',function(e){
		var container = $("#advanceFilterOpenBox, #advanceFilterButton, .CNS-multi-selector-div");
		// if the target of the click isn't the container nor a descendant of the container
		if (!container.is(e.target) && container.has(e.target).length === 0){
			if(!($(".CNS-single-selector-div").length 
				|| $(".CNS-multi-selector-div").length
				|| $(".messegeBoxcontent").length)){
				myObject.hidePopup();
			}
		}
	});

	$("#advancefieldselection").on('change',function(){
		$("#advanceFilterBoxValue").html("");
		var $selectedOption = $("#advancefieldselection :selected");
		var filterType = $selectedOption.attr("filtertype");
		var optionHtml = "";
		for (key in myObject.config.condition[filterType]) {
			if(myObject.config.condition[filterType].hasOwnProperty(key)) {
				var obj = myObject.config.condition[filterType][key];
				optionHtml += '<option tagLable="' + obj.TagLable + '"  value="' + obj.value + '" filtertype="' + filterType + '" subfiltertype="' + key + '">' + obj.label + '</option>';
			}
		}
		$("#advanceconditionselection").html("").append(optionHtml).trigger("change");
		//$("#advanceconditionselection").trigger("change");
	});

	$("#advanceconditionselection").on('change',function(){
		$("#advanceFilterBoxValue").html("");
		$("#advanceFilterOpenBox .thirdBox").html("");
		var $selectedOption = $("#advanceconditionselection :selected");
		var filterType = $selectedOption.attr("filtertype");
		var subfiltertype = $selectedOption.attr("subfiltertype");
		var title="", thirdHtml ="";
		var type = myObject.config.condition[filterType][subfiltertype].type;

		if(type) {
			if(type == "text"){
				title = "Value :";
				thirdHtml = '<input type="text" id="advanceInputBox" class="advanceInputBox" value="" maxlength="255"><select id="advanceValueSelection" class="advanceFieldSelection" style="display:none;"></select>\
							<div alt="paste" class="paste manageicon" onclick="LogViewer.pasteAnonymizedFilterTxt();" title="Paste from temporary variable" id="advancepasteicon" style="display: none;"></div>';
							$("#advanceFilterBoxValue").html(thirdHtml);
			} else if (type ==  "SingleSelector" || type == "MultiSelector"){
				title = "Select :";
				var data = myObject.config.condition[filterType][subfiltertype].data;
				var defaultOption = myObject.config.condition[filterType][subfiltertype].defaultOption;
				var searchableItems = myObject.config.condition[filterType][subfiltertype].searchableItems;
				if(searchableItems == undefined || searchableItems == null){
					searchableItems = []
				};
				myObject.initSingleSelector(data, type, defaultOption, searchableItems);
			}
			$("#advanceFilterOpenBox .thirdBox").html("<label>"+title+"</label>");
		}
		if(myObject.config.condition[filterType][subfiltertype].hidden){
			$(".adavnceFilterConditionDiv").hide();
		} else {
			$(".adavnceFilterConditionDiv").show();
		}
	});

	$("#advanceFilterBoxSubmit").on('click',function(){
		if(myObject.validateAdvanceFilterData()) {
			var tmpID = $("#advancefieldselection").val();
			if(!tmpID){
				tmpID = $("#advanceconditionselection :selected").val();
			}
			//var tagId = "advancefieldselection" + $("#advancefieldselection").val().replace(/ /g,"_");
			var tagId = "advancefieldselection" + tmpID.replace(/[^A-Z0-9]/ig, "_");
			myObject.config.tagConfig.tagContainerId = tagId;
			if(myObject.config.displaySelectedTag){
				myObject.config.searchTag = new Cyberoam.searchTag(myObject);
				myObject.config.searchTag.create();
			}
			if(myObject.config.afterOk){
				var obj = myObject.getKeyFilterVal();
				myObject.config.afterOk(obj.key,obj.val, obj.selectedKey);
			}
			myObject.hidePopup();
		}
	});
	$("#advancefieldselection").trigger("change");
}

Cyberoam.advanceFilterComponent.prototype.validateAdvanceFilterData = function(){
	var returnVal = true;
	var condition = $("#advanceconditionselection option:selected").attr("value");
	var $inputBox = $("#advanceFilterOpenBox #advanceInputBox");
	var isThirdLevel = $("#advanceFilterOpenBox .thirdBox").children().length;

	if(!isThirdLevel){
		finalVal = condition;
	} else {
		if($inputBox.length){
			finalVal = $inputBox.val();
			if(!finalVal){
				Cyberoam.messageBox({message:Language.FwPleaseEnterVal});		
				returnVal = false;
			}
		} else if(this.selectorData && this.selectorData.selectorObj){
			var selectedLabel = this.selectorData.selectorObj.object.getSelectedLabels();
			if(!selectedLabel.length){
				Cyberoam.messageBox({message:Language.FwSelectOne});		
				returnVal = false;
			}
		}
	}
	return returnVal;
}

Cyberoam.advanceFilterComponent.prototype.initSingleSelector = function(data, type, defaultOption, searchableItems){
	var objType =  type;
	this.selectorData = {
		 selectorObj : {
			objType: objType,
			config: {
				defaultOption : defaultOption,
				id: "advanceFilterBoxValue",
				isSearchBox: true,
				defaultLabel: Language.Select,
				searchableItems:searchableItems,
				data: data
			}
		}
	};
	Cyberoam.initEntityObject(null,this.selectorData);
}

Cyberoam.advanceFilterComponent.prototype.hidePopup = function(){
	$("#advanceFilterOpenBox").remove();
}

