Cyberoam.ListBox = function(c) {
	this.config = {"id":"","data":[],height:150,returnKey:false,"formater":"","addValidation":"","deleteValidation":"",addOperation:"",deleteOperation:"","draggable":false,style:"",disabled:false,width:150,"textValidation":true};
	this.searchInterval = null;
	this.searchData = [];
	this.listSearchThread = null;
	this.lastSearch = "";
	this.myDTDrags = [];
	for (var key in c) {
		if(this.config[key] != undefined){
			this.config[key] = c[key];
		}else{
			 Cyberoam.messageBox({message: "Wrong ListBox Configuration "+key});
			 this.config = {"id":"","data":[],"addValidation":"","deleteValidation":"","draggable":false};
			 return;
		}
	}
	if(typeof this.config.data == "undefined"){
		this.config.data = {};
		this.config.data.length = 0;
	}
};
Cyberoam.ListBox.prototype.isDisabled = function(){
	return this.config.disabled;
}
Cyberoam.ListBox.prototype.disabled = function(value){
	this.config.disabled = value;
	if(value){
		document.getElementById("btnAddItem"+this.config.id).disabled = true;
	}else{
		document.getElementById("btnAddItem"+this.config.id).disabled = false;
	}
}
Cyberoam.ListBox.prototype.deleteOperationBySystem  = function(object){
	if(!this.config.disabled){
		var status = true;
		if(this.config.deleteValidation != "")
				status = this.config.deleteValidation(object.parent().parent(),object.prev().prev().attr("key"),this);			
		if(status){
			object.addClass("processing");
			var key = object.prev().prev().attr("key");
			var index = -1;
			var cnt =0;
			for(var i in this.config.data){
				if(i == key){
					index = cnt;
					break;
				}
				cnt++;
			}
			if(this.config.deleteOperation != ""){
				status = this.config.deleteOperation(object.parent().parent(),key,index,this);
				if(!status){
					object.removeClass("processing");
				}
			}else{
				delete this.config.data[key];
				try{
					this.config.data.length--;
				}catch(e){}
				for(var i in this.searchData){
					if(this.searchData[i].label == key){
						this.searchData.splice(i, 1);
					}
				}
				this.setListBody();
			}
		}
	}
};
Cyberoam.ListBox.prototype.deleteNode  = function(node){
	if(!this.config.disabled){
		var index = -1;
		var cnt =0;
		var deleteFlag = false;		
		for(var i in this.config.data){			
			if(i == node.key){				
				index = cnt;
				deleteFlag = true;
				break;
			}
			if(i != "length")
				cnt++;
		}		
		if(deleteFlag){
			delete this.config.data[node.key];
			try{
				this.config.data.length--;
			}catch(e){}
			var cnt=0;
			for(var i in this.searchData){
				if(this.searchData[i].label == node.label){
					this.searchData.splice(i, 1);
					index=cnt;
				}
				cnt++;
			}
			var element = document.getElementById("listbody"+this.config.id).childNodes[0].childNodes[0];
			if(element.childNodes[index])
				element.removeChild(element.childNodes[index]);
		}
	}
};
Cyberoam.ListBox.prototype.deleteAll = function(){
	this.config.data = {};
	this.config.data.length = 0;
	this.setListBody();
}
Cyberoam.ListBox.prototype.deleteNodeByIndex  = function(index){
	if(!this.config.disabled){
		if(this.config.data.length > index){
			delete this.config.data[document.getElementById("listbody"+this.config.id).childNodes[0].childNodes[0].childNodes[0].innerHTML];
			try{
				this.config.data.length--;
			}catch(e){}
			var element = document.getElementById("listbody"+this.config.id).childNodes[0].childNodes[0];
			if(element.childNodes[index])
				element.removeChild(element.childNodes[index]);
		}
	}
};
Cyberoam.ListBox.prototype.insertOperationBySystem  = function(object){
	if(!this.config.disabled){		
		var myobject = this.config;
		var status = true;
		var txtValue=	jQuery("#txtListItem"+this.config.id).val() ;
		
		if(!myobject.textValidation || (txtValue != "" && txtValue != Language.SearchOrAdd)){
			document.getElementById("listbody"+this.config.id).innerHTML = "<div class='processing'>&nbsp;</div>";
			if(myobject.addValidation != "")
				status = myobject.addValidation(txtValue,this);			
			if(status){
				if(myobject.addOperation != ""){
					status = myobject.addOperation(txtValue,this);
					if(!status){
						this.afterInsertNode();
					}
				}else{
					myobject.data[txtValue] = ({"label":txtValue,"key":txtValue});
					this.afterInsertNode();
				}
			}else{
				this.afterInsertNode();
			}
		}
		jQuery("#txtListItem"+this.config.id).val("");
		jQuery("#txtListItem"+this.config.id).css("color","#000");
		if(status)
			jQuery("#txtListItem"+this.config.id).trigger('focus');
	}
};
Cyberoam.ListBox.prototype.ListBoxNodes = function(){
	return this.config.data;
}
Cyberoam.ListBox.prototype.insertNode  = function(node){
	if(!this.config.disabled){
		var myobject = this;
		if(node.label != "" && node.label != Language.SearchOrAdd){
			myobject.config.data[node.key] =node;
			myobject.config.data.length++;
		}
		this.afterInsertNode();
	}
};
Cyberoam.ListBox.prototype.afterInsertNode = function(){
	this.setListBody();
}
Cyberoam.ListBox.prototype.searchListBox  = function(object){
	if(this.searchInterval != null )
		clearTimeout(this.searchInterval);
	var myobject = this;
	var arr = this.config.data;
	var val = object.val();	
	this.searchProcess = function(val,arr){
			var eles = document.getElementById("listbody"+this.config.id);
			if(this.lastSearch.length > val.length){
				this.searchData = [];
			}else if(this.searchData.length > 0){
				arr = this.searchData;
				this.searchData = [];
			}			
			if(val != "" && document.getElementById("txtListItem"+this.config.id).style.color != "rgb(204, 204, 204)" ){
				val = val.toLowerCase();
				jQuery("#listbody"+this.config.id).html("");
				var mainElement = document.getElementById("listbody"+this.config.id);
				var tableMainObject =  Cyberoam.createElement({tag:"table",className:"box"},mainElement);
				tableMainObject.setAttribute("cellspacing","1");
				tableMainObject.setAttribute("width","100%");
				var tableObject =  Cyberoam.createElement({tag:"tbody"},tableMainObject);
				var flag = true;
				for(var i in arr) {
					if(i != "length"){
						if(arr[i].label.toLowerCase().indexOf(val) == 0){		
							this.searchData.push(arr[i]);
							var tr,td;
							var trObject =  Cyberoam.createElement({tag:"tr"},tableObject);
							var tdObject =  Cyberoam.createElement({tag:"td"},trObject);
							flag = false;
							var spanObject =  Cyberoam.createElement({tag:"span"},tdObject);
							spanObject.style.display="none";
							spanObject.setAttribute("key",arr[i].label);
							var divnObject =  Cyberoam.createElement({tag:"div",title:arr[i].label},tdObject);
							if(Cyberoam.isIE)
								divnObject.style.styleFloat = "left";
							else
								divnObject.style.cssFloat = "left";
							divnObject.style.marginLeft = "5px";
							divnObject.style.width = (this.config.width - 48) + "px";
							divnObject.appendChild(document.createTextNode(arr[i].label));
							divnObject =  Cyberoam.createElement({tag:"div",className:"listclose",title:arr[i].label},tdObject);
							divnObject.onclick = function(){myobject.deleteOperationBySystem(jQuery(this))};
						}
					}
				}
				if(flag){
					var trObject =  Cyberoam.createElement({tag:"tr",className:"noRecordFound"},tableObject);
					var tdObject =  Cyberoam.createElement({tag:"td"},trObject);
					tdObject.appendChild(document.createTextNode(Cyberoam.getTranslatedMSG('Language.NoRecord')));
				}
				
			}else{
				this.searchData = [];
				this.setListBody();
			}
			this.lastSearch = val;
	};
	if(val !="" || (val=="" && this.lastSearch != ""))
		this.searchInterval = setTimeout(function(){myobject.searchProcess(val,arr)},1000);
};
Cyberoam.ListBox.prototype.refresh = function(){
	this.setListBody();
}
Cyberoam.ListBox.prototype.setListBody = function(dataArray){	
	if(this.searchInterval != null )
		clearTimeout(this.searchInterval);
	var arr = [];
	if(dataArray == undefined)
		arr = this.config.data;
	else{
		this.config.data = dataArray;
		arr = dataArray;
	}
		
	jQuery("#listbody"+this.config.id).html("");
	var mainElement = document.getElementById("listbody"+this.config.id);
	var myobject = this;
	var html = [];
	var tableMainObject =  Cyberoam.createElement({tag:"table",className:"box"},mainElement);
	tableMainObject.setAttribute("cellspacing","1");
	tableMainObject.setAttribute("width","100%");
	var tableObject =  Cyberoam.createElement({tag:"tbody"},tableMainObject);
	if(typeof arr.length == "undefined"){
		arr.length = 0; //length set to 0
		for(var i in arr) {
			if (arr.hasOwnProperty(i)) {
				arr.length++;
			} // length ++ till arr values
		}
	}
	var flag = true;
	for(var i in arr) {
		if (arr.hasOwnProperty(i)) {
			var tr, td;
			if (i == "length")
				continue;

			if (typeof arr[i].label == "undefined")
				arr[i].label = i;

			if (this.config.draggable) {
				var trObject = Cyberoam.createElement({tag: "tr", id: i + "_node", label: arr[i].label}, tableObject);
				trObject.style.cursor = "move";
				trObject.setAttribute("key", i);
			} else {
				var trObject = Cyberoam.createElement({tag: "tr"}, tableObject);
			}
			var tdObject = Cyberoam.createElement({tag: "td"}, trObject);
			if (arr[i].label == null || arr[i].label == "")
				arr[i].label = i;
			flag = false;
			var spanObject = Cyberoam.createElement({tag: "span"}, tdObject);
			spanObject.style.display = "none";
			spanObject.setAttribute("key", i);
			var divnObject = Cyberoam.createElement({tag: "div", title: arr[i].label}, tdObject);
			if (Cyberoam.isIE)
				divnObject.style.styleFloat = "left";
			else
				divnObject.style.cssFloat = "left";
			divnObject.style.marginLeft = "5px";
			divnObject.style.width = (this.config.width - 48) + "px";
			divnObject.appendChild(document.createTextNode(arr[i].label));

			divnObject = Cyberoam.createElement({tag: "div", className: "listclose", title: arr[i].label}, tdObject);
			divnObject.onclick = function () {
				myobject.deleteOperationBySystem(jQuery(this))
			};

		}
	}
	if(flag){
		var trObject =  Cyberoam.createElement({tag:"tr",className:"noRecordFound"},tableObject);
		var tdObject =  Cyberoam.createElement({tag:"td"},trObject);
		tdObject.appendChild(document.createTextNode(Cyberoam.getTranslatedMSG('Language.NoRecord')));
	}
	if(this.config.draggable)
		this.dragDropTableRow();
};
Cyberoam.ListBox.prototype.getRecord = function(){
	return this.config.data;
}
Cyberoam.ListBox.prototype.getRecordKey = function(){
    var keys = [];
    for(var i in this.config.data){
    	if(i=="length")
    		continue;
        keys.push(i);
    }
    return keys;
}
Cyberoam.ListBox.prototype.getRecordLabel = function(){
    var labels = [];
    for(var i in this.config.data){
    	if(i=="length")
    		continue;
        labels.push(this.config.data[i].label);
    } 
    
    return labels;
} 
Cyberoam.ListBox.prototype.create = function(){
	if(this.id != ""){
		var myobject = this;
		jQuery("#"+this.config.id).attr("class","listBoxContainer");
		jQuery("#"+this.config.id).attr("style",this.config.style);
		var width = parseInt(document.getElementById(this.config.id).style.width);
		this.config.width = width;
		jQuery("#"+this.config.id).html("<table align=\"center\" cellspacing=\"1\" cellpadding=\"0\" style=\"width:"+jQuery("#"+this.config.id).width()+"px;\">"+
					"<tr><td>"+ 
					"<input type=\"text\" id=\"txtListItem"+this.config.id+"\"  style=\"width:100%;height: 17px;color:#CCCCCC\" value='"+Cyberoam.getTranslatedMSG("Language.SearchOrAdd")+"'/></td><td width=\"40px\">"+
					"<input type=\"button\" id=\"btnAddItem"+this.config.id+"\" style=\"margin-right:0px;height: 23px;margin-left: 4px;font-size: 12px;\"  value='"+Cyberoam.getTranslatedMSG("Language.Add")+"'/>"+
					"</td></tr></table>"+
					"<div id=\"listbody"+this.config.id+"\" style=\"height:150px;overflow:auto;\"></div>");
		
		if(typeof this.config.style != "undefined"){
			var height=parseInt(document.getElementById(this.config.id).style.height);
			
			if(isNaN(height))
				height=150;		
			document.getElementById("listbody"+this.config.id).style.height = (height - 35) + "px";
		}

		jQuery("#btnAddItem"+this.config.id).on('click',function(){ myobject.insertOperationBySystem(jQuery(this)) });
		jQuery("#txtListItem"+this.config.id).on('keyup',function(){ myobject.searchListBox(jQuery(this))});
		//jQuery("#txtListItem"+this.config.id).blur(function(){ clearTimeout(myobject.searchInterval);});
		jQuery("#txtListItem"+this.config.id).on('focus',function(e){
			Cyberoam.textEmptyFocus(this,Cyberoam.getTranslatedMSG("Language.SearchOrAdd"));
		});
		jQuery("#txtListItem"+this.config.id).on('blur',function(e){
			Cyberoam.textEmptyBlur(this,Cyberoam.getTranslatedMSG("Language.SearchOrAdd"));
		});
	
		this.setListBody();
		this.disabled(this.config.disabled);
	}
};

Cyberoam.ListBox.prototype.dragDropTableRow = function (){
		var tbody = document.getElementById("listbody"+this.config.id).childNodes[0].childNodes[0];
		if(tbody){
			var totalTR = tbody.childNodes.length;
			var Dom = YAHOO.util.Dom;
			var Event = YAHOO.util.Event;
			var DDM = YAHOO.util.DragDropMgr;
			var mainObject = this;
			YAHOO.example.DDApp = {
			init: function() {
					var target = new YAHOO.util.DDTarget("listbodynirav");		
					for(j = 0;j < totalTR;j++){ // NOSONAR - totalTR does not need to be modified
						if (mainObject.myDTDrags[tbody.childNodes[j].id]) {
							 mainObject.myDTDrags[tbody.childNodes[j].id].unreg();
							 delete mainObject.myDTDrags[tbody.childNodes[j].id];
						}
						mainObject.myDTDrags[tbody.childNodes[j].id] = new YAHOO.example.DDList(tbody.childNodes[j].id);
					}
				}
			};
			YAHOO.example.DDList = function(id, sGroup, config) {
				YAHOO.example.DDList.superclass.constructor.call(this, id, sGroup, config);
				var el = this.getDragEl();
				Dom.setStyle(el, "opacity", 0.67); 
				this.goingUp = false;
				this.lastY = 0;
			};
			YAHOO.extend(YAHOO.example.DDList, YAHOO.util.DDProxy, {
				startDrag: function(x, y) {
					if(!mainObject.config.disabled){
						var dragEl = this.getDragEl();
						var clickEl = this.getEl();
						dragEl.innerHTML = clickEl.innerHTML;
						Dom.setStyle(dragEl, "color", Dom.getStyle(clickEl, "color"));
						Dom.setStyle(dragEl, "backgroundColor", Dom.getStyle(clickEl, "backgroundColor"));
						Dom.setStyle(dragEl, "border", "2px solid gray");
					}
				},
				endDrag: function(e) {
					var srcEl = this.getEl();
					var proxy = this.getDragEl();
					Dom.setStyle(proxy, "visibility", "");
					var a = new YAHOO.util.Motion(
					proxy, {points: {to: Dom.getXY(srcEl)}},0.2,YAHOO.util.Easing.easeOut)
					var proxyid = proxy.id;
					var thisid = this.id;
					a.onComplete.subscribe(function() {
					Dom.setStyle(proxyid, "visibility", "hidden");
					Dom.setStyle(thisid, "visibility", "");
					});
					a.animate();
					mainObject.config.data = [];
					for(j = 0;j < totalTR;j++){ // NOSONAR - totalTR does not need to be modified
						if(tbody.childNodes[j])
						mainObject.config.data[tbody.childNodes[j].getAttribute("key")] = {label:tbody.childNodes[j].childNodes[0].childNodes[2].getAttribute("title"),key:tbody.childNodes[j].getAttribute("key")};
					}
				},	
				onDragDrop: function(e, id) {
					if(!mainObject.config.disabled){
					if (DDM.interactionInfo.drop.length === 1) {
						var pt = DDM.interactionInfo.point;
						var region = DDM.interactionInfo.sourceRegion;
						if (!region.intersect(pt)) {
							var destEl = Dom.get(id);
							if(destEl.nodeName.toLowerCase() == "tbody"){
								var destDD = DDM.getDDById(id);
								destEl.appendChild(this.getEl());
								destDD.isEmpty = false;
								DDM.refreshCache();
							}
						}
			
					}
					}
				},	
				onDrag: function(e) {
					if(!mainObject.config.disabled){
						var y = Event.getPageY(e);		
						if (y < this.lastY) {
							this.goingUp = true;
						} else if (y > this.lastY) {
							this.goingUp = false;
						}		
						this.lastY = y;
					}
				},	
				onDragOver: function(e, id) {
					if(!mainObject.config.disabled){
						var srcEl = this.getEl();
						var destEl = Dom.get(id);
						if (destEl.nodeName.toLowerCase() == "tr") {
							var orig_p = srcEl.parentNode;
							var p = destEl.parentNode;	
							if(p.nodeName.toLowerCase() == "tbody"){
								if (this.goingUp) {
									p.insertBefore(srcEl, destEl); // insert above
								} else {
									p.insertBefore(srcEl, destEl.nextSibling); // insert below
								}
							}
							DDM.refreshCache();
						}
					}
				}
			}); //end of YAHOO.extend	
			Event.onDOMReady(YAHOO.example.DDApp.init, YAHOO.example.DDApp, true);
		}
	}
Cyberoam.Menu = function(config){
	 this.config = {"id":"",menuItems:[],currentURL:null,contextPath:"/webconsole"};
	 for(var key in config){
		 if(this.config[key] != "undifiend"){
			 this.config[key] = config[key];
		 }else{
			 Cyberoam.messageBox({message: "Wrong Configuration for Menu"+key});
		 }
	 }
}
Cyberoam.Menu.prototype.create = function(){
	var mainObject = this;
	this.currentTabs = null;
	jQuery("#"+this.config.id).html("<div id='"+this.config.id+"_menu0_data' class='main_data'></div>");
	var arr = null;
	if(typeof this.config.type != "undefined" && this.config.type.toLowerCase() == "array"){
		this.config.menuItems = this.menuArrayToJSON(this.config.menuItems);
	}
	arr = this.config.menuItems;
	
	var createMenu = function(arr,lavel,parentNode,module){
		for(var index = 0;index<arr.length;index++){
			var status = true;
			if(!arr[index].module)
				arr[index].module = module;
			if(arr[index].validator){
				status = arr[index].validator(arr[index].module,arr[index].aclEntity);
			}
			if(status){
				mainObject.createMenuItem(index,parentNode,arr[index].label,arr[index].url,lavel,arr[index].linktype,arr[index].imagePosition,arr[index].module,arr[index].childNodes,arr[index].title,arr[index].aclEntity,arr[index].beforeOperation,arr[index].appController);
				if(arr[index].childNodes)
					createMenu(arr[index].childNodes,lavel+1,parentNode+"_"+index,arr[index].module);
			}
		}
	}
	var clearNoneMenu = function(){
		var menuElement = document.getElementById("mymenu");
		var lavel1Items = Cyberoam.getElementsByClassName("lavel1_menu",menuElement);
		var length = lavel1Items.length;
		for(var i=0;i<length;i++){
			if(document.getElementById(lavel1Items[i].id+"_data").innerHTML == ""){
				$("#"+lavel1Items[i].id+"_data").remove();
				$("#"+lavel1Items[i].id+"_select").remove();
				$("#"+lavel1Items[i].id).remove();
			}
		}
		
		var lavel0tems = Cyberoam.getElementsByClassName("lavel0_menu",menuElement);
		var length = lavel0tems.length;
		for(var i=0;i<length;i++){
			if(document.getElementById(lavel0tems[i].id+"_data").innerHTML == ""){
				$("#"+lavel0tems[i].id+"_data").remove();
				$("#"+lavel0tems[i].id+"_select").remove();
				$("#"+lavel0tems[i].id+"_subscription").remove();
				$("#"+lavel0tems[i].id).remove();
			}
		}
	}
	createMenu(arr,0,0,"");
	//clearNoneMenu();
}
Cyberoam.Menu.prototype.menuArrayToJSON = function(arr){
	var index = 0;
	var lavel = 0;		
	var getMenuJSON = function(){	
		var jsonArray = [];
		for(;index<arr.length;){
			var jsonObject = {};
			jsonObject.label = arr[index][0];
			if(arr[index][2] == 0){
				jsonObject.module = arr[index][1];
				jsonObject.imagePosition = arr[index][3];
			}else{
				if(arr[index][1] != "")
					jsonObject.url = arr[index][1];
				if(typeof arr[index][3] != "undefined")
					jsonObject.module = arr[index][3];
				if(typeof arr[index][4] != "undefined")
					jsonObject.linktype = arr[index][4]
			}
			jsonObject.validator = function(module){return validateMenuItem(module)};
			if(arr[index+1]){
				if(arr[index+1][2] == lavel){
					jsonArray.push(jsonObject);
					index++;
				}else if(arr[index+1][2] > lavel){
					lavel++;
					index++;
					jsonObject.childNodes = getMenuJSON();
					if(arr[index] && arr[index][2] != lavel){
						lavel--;
						jsonArray.push(jsonObject);
						return jsonArray;
					}
					jsonArray.push(jsonObject);
				}else if(arr[index+1][2] < lavel){
					jsonArray.push(jsonObject);
					index++;
					lavel--;
					return jsonArray;
				}
			}else{
				index++;
			}
		}
		return jsonArray;
	}
	return getMenuJSON();
}
Cyberoam.Menu.prototype.goToURL = function(url){
	this.config.currentURL = url;
	if(typeof this.config.type != "undefined" && this.config.type.toLowerCase() == "array"){
		document.getElementById('mainframe').src = this.config.contextPath+url;
	}else{
		Cyberoam.setMainFrame(url);
	}
}
Cyberoam.Menu.prototype.getCurrentURL = function(){
	return this.config.currentURL;
};
Cyberoam.Menu.prototype.showCurrentURL = function(){
	if(this.config.currentURL == null)
		return null;
	this.displayMenuByURL(this.config.currentURL);
}
Cyberoam.Menu.prototype.displayMenuByNumber = function(number){
	if(this.currentTabs != null && typeof this.currentTabs[number-1] != "undefined"){
		this.displayMenuByURL(this.currentTabs[number-1].url);
	}
}
Cyberoam.Menu.prototype.displayMenuByURL = function(url,redirectPage){
	var mainObject = this;
	var getMenuID = function(arr,lavel,parentNode){
		for(var index = 0;index<arr.length;index++){
			if(url.indexOf(arr[index].url) != -1 && parentNode){
				var ids = parentNode.split("_");
				var obj = document.getElementById(mainObject.config.id+"_menu"+ids[0]+"_"+ids[1]);
				$(".menudata0").hide();
				$("#"+obj.id+"_data").show();
				$(".lavel0_menu").attr("class","lavel0_menu");
				$(".lavel0_menu").each(function(index) {
					this.childNodes[0].style.backgroundPosition = "-4px "+this.childNodes[0].style.backgroundPosition.split(" ")[1];
				});
				$(".menu0select").hide();
				$(obj).next().show();
				$(obj).addClass("lavel0_menu_select");
				obj.childNodes[0].style.backgroundPosition = "-29px "+obj.childNodes[0].style.backgroundPosition.split(" ")[1];
				
				var secondObj = null;
				if(lavel == 1){
					secondObj = document.getElementById(mainObject.config.id+"_menu"+ids[0]+"_"+ids[1]+"_"+index);
					index = 0;
				}else{
					secondObj = document.getElementById(mainObject.config.id+"_menu"+ids[0]+"_"+ids[1]+"_"+ids[2]);
				}
				$(".lavel1_menu").attr("class","lavel1_menu");
				$(secondObj).addClass("lavel1_menu_select");
				document.getElementById("tab_menu").className="menutab";
				document.getElementById("tab_menu").innerHTML = document.getElementById(secondObj.id+"_data").innerHTML;
				$(".menu1select").hide();
				$(secondObj).next().show();
				$(secondObj).next().css("top",$(secondObj).offset().top);
				var node  = document.getElementById("tab_menu").childNodes[index];
				node.childNodes[0].className += " "+node.childNodes[0].className+"_select";
				node.childNodes[1].className +=  " "+node.childNodes[1].className+"_select";
				node.childNodes[2].className += " "+ node.childNodes[2].className+"_select";
				mainObject.currentTabs = arr;
				
				if(arr[index].appController)
					Cyberoam.appController = arr[index].appController;
				  else
					Cyberoam.appController = Cyberoam.defaultController;
				
				if(lavel == 2)
					$("#tab_menu .tablavel2_menu").off().on('click',function(){mainObject.displayMenu(this,2,arr)});
				else
					$("#tab_menu .tablavel2_menu").off().on('click',function(){mainObject.displayMenu(this,2,[{label:arr[index].label,url:arr[index].url}])});
				 if(typeof redirectPage == "undefined")
				     mainObject.goToURL(url);
				    else
				     mainObject.goToURL(redirectPage);
				return true;
			}else{
				if(url.indexOf(arr[index].url) != -1){
					var obj = document.getElementById(mainObject.config.id+"_menu0_"+index);
					if(obj)
						$(obj).addClass("lavel0_menu_select");
					
					mainObject.goToURL(url);
					return true;
				}
				
			}				
			if(arr[index].childNodes)
				if(getMenuID(arr[index].childNodes,lavel+1,parentNode+"_"+index))
					return true;
		}
		return false;
	}
	if(!getMenuID(this.config.menuItems,0,0)){
		//alert("Page Not Found");
		mainObject.goToURL(url);
	}
	/*var ele = jQuery("#"+this.config.id+"_menu0_data");
	if(ele.height()+document.getElementById(this.config.id).scrollTop > (document.documentElement.clientHeight - ele.offset().top - 20) ){
		document.getElementById("menu_uparrow").style.display = "block";
		document.getElementById("menu_downarrow").style.display = "block";
	}else{
		document.getElementById("menu_uparrow").style.display = "none";
		document.getElementById("menu_downarrow").style.display = "none";
	}*/
}
Cyberoam.Menu.prototype.createMenuItem = function(id,pid,content,url,lavel,linktype,position,module,childNodes,title,aclEntityValue,beforeOperation,appController){
	var eleMenu = $("#"+this.config.id+"_menu"+pid+"_data");
	var mainObject = this;
	var index = id;
	var id = pid+"_"+id;	
	htmlCon = "";
	if(lavel == 0){
		var subscription = "";
		/*if(!Cyberoam.checkModuleSebscription(module)){			
			subscription = "<div class='subscription' id='"+this.config.id+"_menu"+id+"_subscription' onclick='setTimeout(\"openLicensing()\",1)' title='"+Language["subscription"][module]+"'></div>";
		}*/
		if(typeof title == "undefined")                                                                              
            title=content;
	
		if(linktype == 2){
			if(beforeOperation)
				htmlCon = "<a href='"+Cyberoam.contextPath+"/"+url+"' onclick=' return "+ beforeOperation  +"()'>";
			else
				htmlCon = "<a href='"+Cyberoam.contextPath+"/"+url+"'>";
		}else if(linktype == 1)
			htmlCon = "<a href='"+Cyberoam.contextPath+"/"+url+"' target='_blank'>";
		
		htmlCon += '<div class="lavel0_menu" id="'+this.config.id+'_menu'+id+'" title="'+title+'" ><div class="menu0image" style="background-position:-4px -'+position+'px;"></div><div class="menu0text" style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" >'+content+'</div></div>'+subscription+'<div class="menu0select" id="'+this.config.id+'_menu'+id+'_select"></div><div id="'+this.config.id+'_menu'+id+'_data" class="menudata0" style="display:none" ></div>';
		
		if(linktype == 2 || linktype == 1)
			htmlCon += "</a>";

	}else if(lavel == 1){
		if(linktype == 1)
			htmlCon = "<a href='"+Cyberoam.contextPath+"/"+url+"' target='_blank' >";
		
			
		
		if(childNodes){
			htmlCon += '<div class="lavel1_menu" id="'+this.config.id+'_menu'+id+'" ><div class="menu1image" ></div>'+content+'</div><div class="menu1select" id="'+this.config.id+'_menu'+id+'_select" ></div>';
			htmlCon += '<div id="'+this.config.id+'_menu'+id+'_data" class="menudata1" style="display:none" ></div>';
		}else{
			htmlCon += '<div class="lavel1_menu" id="'+this.config.id+'_menu'+id+'" pageelementid='+aclEntityValue+'><div class="menu1image" ></div>'+content+'</div><div class="menu1select" id="'+this.config.id+'_menu'+id+'_select" ></div>';
			htmlCon += '<div id="'+this.config.id+'_menu'+id+'_data" class="menudata1" style="display:none" ><div id="'+this.config.id+'_menu'+id+'" class="tablavel2_menu" style="display:none" index=0 pageelementid='+aclEntityValue+' ><div class="tablavel2_menu_left"></div>'+
			'<div class="tablavel2_menu_middel">'+content+'</div><div class="tablavel2_menu_right"></div></div></div>';
		}
		if(linktype == 1)
			htmlCon += "</a>";

	}else{		
		htmlCon = "<div id=\""+this.config.id+"_menu"+id+"\" class=\"tablavel2_menu\" style=\"display:none\" index='"+index+"' pageelementid='"+aclEntityValue+"'><div class=\"tablavel2_menu_left\"></div>"+
					"<div class=\"tablavel2_menu_middel\">"+content+"</div><div class=\"tablavel2_menu_right\"></div></div>";
	}
	eleMenu.append(htmlCon);
	if(!linktype)
		$("#"+this.config.id+"_menu"+id).on('click',function(){mainObject.displayMenu(this,lavel,childNodes,url,appController)});
}
Cyberoam.Menu.prototype.refreshMenu = function(){
	$(".menudata0").hide();
	$(".menu0select").hide();
	$(".menu1select").hide();
	$(".lavel1_menu").attr("class","lavel1_menu");
	document.getElementById("tab_menu").innerHTML = "";
	document.getElementById("tab_menu").className = "";
	$(".lavel0_menu").each(function(index) {
		this.childNodes[0].style.backgroundPosition = "-4px "+this.childNodes[0].style.backgroundPosition.split(" ")[1];
		this.className = "lavel0_menu";
	});
}
Cyberoam.Menu.prototype.displayMenu = function(obj,lavel,childs,url,appController){
	var mainObject = this;
	if(appController)
		Cyberoam.appController = appController;
	else
		Cyberoam.appController = Cyberoam.defaultController;

	if(lavel == 0){
		if($("#"+obj.id).hasClass("lavel0_menu_select"))
		{
			$("#"+obj.id+"_data").hide();
			$(obj).removeClass("lavel0_menu_select");
			obj.childNodes[0].style.backgroundPosition = "-4px "+obj.childNodes[0].style.backgroundPosition.split(" ")[1];
			$(".menu0select").hide();
		}else{
			$(".menudata0").hide();
			$("#"+obj.id+"_data").show();
			$(".lavel0_menu").attr("class","lavel0_menu");
			$(".lavel0_menu").each(function(index) {
				this.childNodes[0].style.backgroundPosition = "-4px "+this.childNodes[0].style.backgroundPosition.split(" ")[1];
			});
			$(".menu0select").hide();
			$(obj).next().show();
			
			if($(obj).next().next())
				$(obj).next().next().show();
			
			$(obj).addClass("lavel0_menu_select");
			obj.childNodes[0].style.backgroundPosition = "-29px "+obj.childNodes[0].style.backgroundPosition.split(" ")[1];
		}
		if(url)
			this.goToURL(url);
	}else if(lavel == 1){
		$(".lavel1_menu").attr("class","lavel1_menu");
		$(obj).addClass("lavel1_menu_select");
		document.getElementById("tab_menu").className="menutab";
		document.getElementById("tab_menu").innerHTML = document.getElementById(obj.id+"_data").innerHTML;
		$(".menu1select").hide();
		$(obj).next().show();
		$(obj).next().css("top",$(obj).offset().top);
		if(childs){
			var index = obj.getAttribute("index");
			if(!index){
				var node = document.getElementById("tab_menu").childNodes[0];
				for(var i=0;i<childs.length;i++){
					if(node.id == obj.id+"_"+i){
						index = i;
						break;
					}
				}
			} else{
					var childNodes = document.getElementById("tab_menu").childNodes;
					for(var i in childNodes){
						if(childNodes[i].id == obj.id+"_"+index){
							var node = childNodes[i];
							break;
						}
					}
			}
			if(node){
				node.childNodes[0].className += " "+node.childNodes[0].className+"_select";
				node.childNodes[1].className +=  " "+node.childNodes[1].className+"_select";
				node.childNodes[2].className += " "+ node.childNodes[2].className+"_select";
				node
			}
			$("#tab_menu .tablavel2_menu").each(function(index) {
			  this.onclick = function(){mainObject.displayMenu(this,2,childs)};
			  });
			Cyberoam.pageElementId=childs[index].aclEntity;
			this.goToURL(childs[index].url);
			this.currentTabs = childs;
		}else{
			var node  = document.getElementById("tab_menu").childNodes[0];
			node.childNodes[0].className +=  " "+node.childNodes[0].className+"_select";
			node.childNodes[1].className +=  " "+node.childNodes[1].className+"_select";
			node.childNodes[2].className +=  " "+node.childNodes[2].className+"_select";
			var content = node.childNodes[1].innerHTML;
			$("#tab_menu .tablavel2_menu").each(function(index) {
				  this.onclick = function(){mainObject.displayMenu(this,2,[{label:content,url:url}])};
				  });
			this.currentTabs = null;
			//$("#tab_menu .tablavel2_menu").click(function(){mainObject.displayMenu(this,2,[{label:content,url:url}])});
			Cyberoam.pageElementId=obj.getAttribute("pageelementid");
			this.goToURL(url);
		}
		
	}else{
		$("#tab_menu .tablavel2_menu_left").attr("class","tablavel2_menu_left");
		$("#tab_menu .tablavel2_menu_right").attr("class","tablavel2_menu_right");
		$("#tab_menu .tablavel2_menu_middel").attr("class","tablavel2_menu_middel");
		obj.childNodes[0].className +=  " "+obj.childNodes[0].className+"_select";
		obj.childNodes[1].className +=  " "+obj.childNodes[1].className+"_select";
		obj.childNodes[2].className +=  " "+obj.childNodes[2].className+"_select";			
		var index = obj.getAttribute("index");
		url = childs[index].url;
		var id = obj.id.substring(0,obj.id.lastIndexOf("_"));
		$("#"+id).attr("index",index);
		Cyberoam.pageElementId=obj.getAttribute("pageelementid");
		this.goToURL(url);
	}

	/*var ele = jQuery("#"+this.config.id+"_menu0_data");
	if(ele.height()+document.getElementById(this.config.id).scrollTop > (document.documentElement.clientHeight - ele.offset().top - 20) ){
		document.getElementById("menu_uparrow").style.display = "block";
		document.getElementById("menu_downarrow").style.display = "block";
	}else{
		document.getElementById("menu_uparrow").style.display = "none";
		document.getElementById("menu_downarrow").style.display = "none";
	}*/
	Cyberoam.setStatusBarMessage("","");
}
/* this file is user to create MultiList component

	functions

	---------

	1) config() used for Configuration 
		parameter:	1)id		
					2)data
					3)function name : on ok which function calls
					
					4)dragable : dragging mode is on or off

					  disabled : Elements selecting mode is disable or not
					  style    : Style css for div elememt
	2) insertMultiListSelElement() used to insert Element in MultiList

		parameter:	1)index

	3) removeMultiListSelElement() Remove element from selected list
		parameter:	1)id

	4) isDisabled() return true if selecting element mode is disabled
	5) isEnabled()  return false if
selecting element mode is enabled
	6) getSelectedItems() to get array of selected labels and keys
	7) getSelectedKeys()  to get array of selected keys
	8) getSelectedLables() to get array of selected labels
*/

Cyberoam.MultListBox = function(c) {
	this.config = {"id":"","data":[],returnKey:false,getOpcodeValue:"",selectOperation:"",deleteOperation:"",leftHeader:"",rightHeader:"","dragable":false,"disabled":false,style:"",selectedItems:[],height:200,width:350,createItem:{},popupDiv:""};
	this.searchInterval = null;
	this.searchData = [];
	for (var key in c) {
		if(this.config[key] != undefined){
			this.config[key] = c[key];
		}else{
			 Cyberoam.messageBox({message: "Wrong ListBox Configuration "+key});
			 this.config = {"id":"","data":[],"dragable":false,"disabled":false};
			 return;
		}
	}
};

Cyberoam.MultListBox.prototype.create = function(){
	if(this.id != ""){
		var myobject = this;
		if(this.config.leftHeader == "" || this.config.leftHeader == null)
			var leftheader = "All List";
		else
			var leftheader = this.config.leftHeader;
		var multiobject = jQuery("#"+this.config.id);
		multiobject.attr("style",this.config.style);
		if(this.config.height!=200){
			multiobject.height(parseInt(this.config.height));
		}
		if(this.config.width!=350){
			multiobject.width(parseInt(this.config.width));
		}
		if(this.config.rightHeader == "" || this.config.rightHeader == null)
			var rightheader = "Selected List";
		else
			var rightheader = this.config.rightHeader;
		var headerWidth = parseInt((multiobject.width()-35)/2);
		jQuery("#"+this.config.id).attr("class","maincontainer");
		jQuery("#"+this.config.id).html("<table width=\"100%\"><tr class=\"multilistheader\" ><td width=\"50%\"> <div class=\"left\" title=\""+leftheader+"\" style='width:"+headerWidth+"px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;'>"+leftheader+"</div></td><td><div class=\"right\" title=\""+rightheader+"\" style='width:"+headerWidth+"px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;'>"+rightheader+"</div></td></tr><tr><td valign=\"top\"><div id=\"defaultlist"+this.config.id +"\"style=\"float:left;\" ></div></td><td valign=\"top\"><div class=\"selectboxcontainer\" style=\"height:"+(jQuery("#"+this.config.id).height()-33)+"px;width:99% !important;\" ><ul id=\"sellist"+this.config.id +"\" class=\"selmultlist\"></ul></div></td></tr></table>");
		jQuery("#defaultlist"+this.config.id).attr("class","listBoxContainer");
		var widthSearchBox = 96;
		if(!Cyberoam.isCCC && this.config.createItem && this.config.createItem.url) {
			widthSearchBox = 68;
		}
		jQuery("#defaultlist"+this.config.id).html("<table width=\"100%\" align=\"center\" cellspacing=\"0\" cellpadding=\"0\">"+
					"<tr><td>"+ 
					//"<input type=\"text\" id=\"txtListItem"+this.config.id+"\" class=\"searchtext\" style=\"height:22px;padding-left: 5px;width:96% !important;border-radius: 4px;\" value='"+Cyberoam.getTranslatedMSG("Language.Search")+"'/>"+
					"<input type=\"text\" id=\"txtListItem"+this.config.id+"\" placeholder=\""+Cyberoam.getTranslatedMSG("Language.typeToSearch")+"\" class=\"searchtext\" style=\"color:#334653;height:22px;padding-left: 5px;width:"+widthSearchBox+"% !important;border-radius: 4px;\" />"+
					"<div id='MutliListItemCreateNewLabel"+this.config.id+"' style='display:none'></div></td></tr></table>"+
					"<div id=\"listbody"+this.config.id+"\" style=\"height:"+(jQuery("#"+this.config.id).height()-70)+"px;"+"min-width:200px;"+"overflow-y:auto\"></div>");
					//"<div id=\"listbody"+this.config.id+"\" style=\"height:"+(jQuery("#"+this.config.id).height()-70)+"px;overflow-y:auto\"></div>");
		jQuery("#txtListItem"+this.config.id).on('keyup',function(){ myobject.searchListBox(jQuery(this))});
		//Create new Item
		if(!Cyberoam.isCCC && this.config.createItem && this.config.createItem.url) {
			var popupDiv;
			if(this.config.popupDiv == "") { // If popup div no provide crate own
				popupDiv = $("<div></div>").attr("id","MutliListPopupDiv"+this.config.id).appendTo(multiobject);
				var thisheight = (-$("#"+this.config.id).height())
				popupDiv.css({"position":"relative","top":thisheight+"px"});
				this.config["popupDiv"] = "MutliListPopupDiv"+this.config.id; // Add in current divObject
			}
			var createLabel = "Create";
			if(this.config.createItem.label) {
				createLabel = Cyberoam.getTranslatedMSG(this.config.createItem.label);
			}
			$("#txtListItem"+this.config.id).css({"float":"left"});  
			var ele = $("#MutliListItemCreateNewLabel"+this.config.id);
			ele.show();
			ele.text(createLabel);
			ele.css({"float": "left","text-overflow":"ellipsis","white-space":"nowrap","width":"30%","overflow":"hidden","color":"#005bc8","cursor":"pointer","padding-left":"2px"});
			var _this = this;
			ele.on('click',function(){
				//_this.config.createItem.events.click(_this);
				if(_this.config.createItem.url && _this.config.createItem.url != "") {
					Cyberoam.showWidgetPopup({title:_this.config.createItem.pageTitle,URL:_this.config.createItem.url+'&multilist='+_this.config.id,width:620,height:400,popupDiv:_this.config.popupDiv}); // Show widget popup
				}
			});
		}
//		jQuery("#txtListItem"+this.config.id).focus(function(e){
//			Cyberoam.textEmptyFocus(this,Cyberoam.getTranslatedMSG("Language.Search"));
//		});
//		jQuery("#txtListItem"+this.config.id).blur(function(e){
//			Cyberoam.textEmptyBlur(this,Cyberoam.getTranslatedMSG("Language.Search"));
//		});
		var selectedNodes = [];
		if(typeof this.config.selectedItems != "undefined"){
			var selectedNodes = this.config.selectedItems;
			for(var i=0;i<selectedNodes.length;i++){
				this.config.data[selectedNodes[i]].selected = true;
			}
		 }
		this.config.selectedItems = "";
		this.setListBody();
		for(var i=0;i<selectedNodes.length;i++){
			var cnt = this.config.data[selectedNodes[i]].index;
			var selele = document.getElementById("sellist"+this.config.id);
			var ele = document.createElement("li");
			if(this.config.dragable)
				ele.style.cursor = "move";
			ele.className = "List_item_single";
			ele.id= "sellist_"+this.config.id+"_"+ selectedNodes[i];		
			ele.title = this.config.data[selectedNodes[i]].label;
			var title = this.config.data[selectedNodes[i]].label;		
			/*if(title.length > 20){
	    			 title = title.substr(0,20)+"...";
			}*/
			
//			var divObject = Cyberoam.createElement({tag:"div",id:"sellistval_"+this.config.id+"_"+selectedNodes[i],className:"listclose",title:this.config.data[selectedNodes[i]].label},ele);
//			divObject.style.paddingLeft = "20px";
//			divObject.style.paddingTop = "2px";
//			divObject.style.width = (this.config.width/2)+"px";
//			divObject.appendChild(document.createTextNode(title));
//			divObject.setAttribute("key",selectedNodes[i]);
//			divObject.setAttribute("label",this.config.data[selectedNodes[i]].label);		
//			this.config.data[selectedNodes[i]].selected = true;
//			selele.appendChild(ele);
			
			var divWrap = Cyberoam.createElement({tag:"div",className:"multilist-item-wrapper"},ele);
			var divIconClose = Cyberoam.createElement({tag:"div",id:"sellistval_"+this.config.id+"_"+selectedNodes[i],className:"multilist-item-icon",title:"remove"},divWrap);
			var divText = Cyberoam.createElement({tag:"div",className:"multilist-item-text"},divWrap);
			divWrap.setAttribute("key",selectedNodes[i]);
			divWrap.setAttribute("label",this.config.data[selectedNodes[i]].label);
			divWrap.style.width = (this.config.width/2)+"px";
			divText.appendChild(document.createTextNode(title));
			var iIconClose = Cyberoam.createElement({tag:"i",className:"fa fa-remove"},divIconClose);
			iIconClose.style.fontSize="1.4em";
			selele.appendChild(ele);
			this.config.data[selectedNodes[i]].selected = true;
			
			if(typeof this.config.data[selectedNodes[i]].disabled == "undefined" || this.config.data[selectedNodes[i]].disabled == false){
				divIconClose.onclick = function() {
					var ids = this.id.split("_");
					var id = ids[2];
					for(var i=3;i<ids.length;i++)
						id = id + "_"+ids[i]
					myobject.removeMultiListSelElement(id);
				}
			}
		}
		if(this.config.dragable == true){
		   this.MultiListYUI();
		}
	}
};
