Cyberoam.MultListBox.prototype.setListBody = function(dataArray){
	var arr = [];
	if(dataArray == undefined)
		arr = this.config.data;
	else
		arr = dataArray;
	jQuery("#listbody"+this.config.id).html("");
	jQuery("#sellist"+this.config.id).html("");
	
	var myobject = this;
	var mainElement = document.getElementById("listbody"+this.config.id);
	var mainSelElement = document.getElementById("sellist"+this.config.id);
	var tableMainObject =  Cyberoam.createElement({tag:"table",className:"box"},mainElement);
	tableMainObject.setAttribute("cellspacing","1");
	tableMainObject.setAttribute("cellpadding","0");
	tableMainObject.setAttribute("style","background-color:transparent;");
	tableMainObject.setAttribute("width","100%");
	var tableObject =  Cyberoam.createElement({tag:"tbody"},tableMainObject);
	var cnt = 0;
	if(typeof arr.length == "undefined"){
		arr.length = -1;
		for(var i in arr) {
			if(arr.hasOwnProperty(i)) {
				arr.length++;
			}
		}
	}
	var selectedItemsHTML = {};
	for(var i in arr){
		if(i=="length")
			continue;
		tr =  Cyberoam.createElement({tag:"tr"},tableObject);
		
		if(this.config.draggable) {
			td =  Cyberoam.createElement({tag:"td"},tr);
			td.style.cursor="move";
		}else {
			td =  Cyberoam.createElement({tag:"td"},tr);
			td.style.cursor="pointer";
		}
		arr[i].index = cnt;
		if(arr[i].label ==null || arr[i].label =="")
			arr[i].label=i;
	
		var title = arr[i].label;
		/*if(title.length > 20){
		     title = title.substr(0,20)+"...";
		}*/
		var config = {tag:"div",className:"multiselect_item_label",id:"mainlist_"+this.config.id+"_"+i,title:arr[i].label};
		var configIcon = {tag:"div",id:"mainlist_"+this.config.id+"_icon_"+i,title:arr[i].label};
		if(arr[i].selected==true){			
			if(typeof arr[i].disabled != "undefined" && arr[i].disabled == true)
				configIcon["className"]="multiselect_item_select_disabled";
			else
				configIcon["className"]="multiselect_item_select";
			
			if(this.config.selectedItems != ""){
				var ele = document.createElement("li");
				if(this.config.dragable)
					ele.style.cursor = "move";
				ele.className = "List_item_single";
				ele.id= "sellist_"+this.config.id+"_"+ i;		
				ele.title = arr[i].label;
				var title = arr[i].label;		
				/*if(title.length > 20){
		    			 title = title.substr(0,20)+"...";
				}*/
//				var divObject = Cyberoam.createElement({tag:"div",id:"sellistval_"+this.config.id+"_"+i,className:"listclose",title:arr[i].label},ele);
//				divObject.style.paddingLeft = "20px";
//				divObject.style.paddingTop = "2px";
//				divObject.style.width = (this.config.width/2)+"px";
//				divObject.appendChild(document.createTextNode(title));
//				divObject.setAttribute("key",i);
//				divObject.setAttribute("label",arr[i].label);		

				var divWrap = Cyberoam.createElement({tag:"div",className:"multilist-item-wrapper"},ele);
				var divIconClose = Cyberoam.createElement({tag:"div",id:"sellistval_"+this.config.id+"_"+i,className:"multilist-item-icon",title:"remove"},divWrap);
				var divText = Cyberoam.createElement({tag:"div",className:"multilist-item-text"},divWrap);
				divWrap.setAttribute("key",i);
				divWrap.setAttribute("label",arr[i].label);
				divWrap.style.width = (this.config.width/2)+"px";
				divText.appendChild(document.createTextNode(title));
				var iIconClose = Cyberoam.createElement({tag:"i",className:"fa fa-remove"},divIconClose);
				iIconClose.style.fontSize="1.4em";
				//selele.appendChild(ele);
//				divIconClose.onclick = function() {
//						myobject.removeMultiListSelElement(id);
//				}
				
				mainSelElement.appendChild(ele);
				if(typeof arr[i].disabled == "undefined" || arr[i].disabled == false){
					divIconClose.onclick = function() {
						var ids = this.id.split("_");
						var id = ids[2];
						for(var i=3;i<ids.length;i++)
							id = id + "_"+ids[i]
						myobject.removeMultiListSelElement(id);
					}
				}
			}
		}else{
			if(typeof arr[i].disabled != "undefined" && arr[i].disabled == true)
				configIcon["className"]="multiselect_item_disabled";
			else
				configIcon["className"]="multiselect_item";
			
		}
		
		
		divIcon =  Cyberoam.createElement(configIcon,td);
		$(divIcon).attr("divtype","icon");
		div =  Cyberoam.createElement(config,td);
		
		if(typeof arr[i].disabled == "undefined" ||  arr[i].disabled != true) {
			div.onclick = function(){myobject.insertMultiListSelElement(this)};
			divIcon.onclick = function(){myobject.insertMultiListSelElement(this)};
		}
		div.setAttribute("key",i);
		div.style.width = ((this.config.width/2)-25)+"px";
		div.setAttribute("label",arr[i].label);
		div.appendChild(document.createTextNode(title));
		cnt++;
	}
	if(typeof arr.length == "undefined" || arr.length == 0){
		var trObject =  Cyberoam.createElement({tag:"tr",className:"noRecordFound"},tableObject);
		var tdObject =  Cyberoam.createElement({tag:"td"},trObject);
		tdObject.appendChild(document.createTextNode(Cyberoam.getTranslatedMSG('Language.NoRecord')));
	}
	if(this.config.dragable == true){
		   this.MultiListYUI();
		}
};
Cyberoam.MultListBox.prototype.removeMultiListSelElement = function(id){
	if(!this.config.disabled){
		var mainlist = document.getElementById("mainlist_"+this.config.id+"_"+id);
		var mainlistIcon = document.getElementById("mainlist_"+this.config.id+"_icon_"+id);
		mainlistIcon.className = "multiselect_item";
		this.config.data[mainlist.getAttribute("key")].selected = false;
		var selele = document.getElementById("sellist"+this.config.id);
		selele.removeChild(document.getElementById("sellist_"+this.config.id+"_"+id));
		if(selele.scrollHeight == parseInt(selele.style.height)){
			selele.style.height = "auto";
			selele.style.overflowY = "";
		}
		if(this.config.deleteOperation != "")
			this.config.deleteOperation(mainlist.getAttribute("key"),mainlist.getAttribute("label"));
	}
};
Cyberoam.MultListBox.prototype.isDisabled = function(){
	return this.config.disabled;
}
Cyberoam.MultListBox.prototype.isEnabled = function(){
	return !this.config.disabled;
}
Cyberoam.MultListBox.prototype.setDisabled = function(value){
	this.config.disabled = value;
}
Cyberoam.MultListBox.prototype.setEnabled = function(value){
	this.config.disabled = !value;
}
Cyberoam.MultListBox.prototype.insertMultiListSelElement = function(object){
	if(!this.config.disabled){
		var myobject = this;
		var elements = document.getElementById("listbody"+this.config.id).childNodes[0].childNodes[0].childNodes;
		var iconObj = $(object).parent().find("[divtype='icon']").get(0);
		var labelObj = $(object).parent().find(".multiselect_item_label").get(0);
		var getselectid = labelObj.id;
		var seltid = getselectid.split("_");
		var id = seltid[2];
		for(var i=3;i<seltid.length;i++)
			id = id + "_"+seltid[i]
		
		var classname = iconObj.className;
		if(classname == "multiselect_item_select"){
			iconObj.className = "multiselect_item";
			myobject.removeMultiListSelElement(id);
			var key = labelObj.getAttribute("key");
			this.config.data[key].selected = false;
		}else{
			iconObj.className = "multiselect_item_select";
			var selele = document.getElementById("sellist"+this.config.id);
			var ele = document.createElement("li");
			if(this.config.dragable)
				ele.style.cursor = "move";
			ele.className = "List_item_single";
			ele.id= "sellist_"+this.config.id+"_"+ id;				
			var key = labelObj.getAttribute("key");
			var label = labelObj.getAttribute("label");
			ele.title = label;
			
			var title = label;		
			/*if(title.length > 20){
	    			 title = title.substr(0,20)+"...";
			}*/
			
			/*var divObject = Cyberoam.createElement({tag:"div",id:"sellistval_"+this.config.id+"_"+id,className:"listclose",title:"remove"},ele);
			//divObject.style.paddingLeft = "20px";
			divObject.style.paddingTop = "2px";
			divObject.appendChild(document.createTextNode(title));
			divObject.setAttribute("key",key);
			divObject.setAttribute("label",label);
			divObject.style.width = (this.config.width/2)+"px";			
			selele.appendChild(ele);
			divObject.onclick = function() {
					myobject.removeMultiListSelElement(id);
			}
			*/
			
			var divWrap = Cyberoam.createElement({tag:"div",className:"multilist-item-wrapper"},ele);
			var divIconClose = Cyberoam.createElement({tag:"div",id:"sellistval_"+this.config.id+"_"+id,className:"multilist-item-icon",title:"remove"},divWrap);
			var divText = Cyberoam.createElement({tag:"div",className:"multilist-item-text"},divWrap);
			divWrap.setAttribute("key",key);
			divWrap.setAttribute("label",label);
			divWrap.style.width = (this.config.width/2)+"px";
			divText.appendChild(document.createTextNode(title));
			var iIconClose = Cyberoam.createElement({tag:"i",className:"fa fa-remove"},divIconClose);
			iIconClose.style.fontSize="1.4em";
			selele.appendChild(ele);
			divIconClose.onclick = function() {
					myobject.removeMultiListSelElement(id);
			}
			
			
			this.config.data[key].selected = true;
	   }
		if(this.config.selectOperation != "")
			this.config.selectOperation(key,label);
		if(this.config.dragable == true){
		   this.MultiListYUI();
		}
	}
};

Cyberoam.MultListBox.prototype.afterInsertNode = function(){
	this.setListBody();
}
