Cyberoam.getCorporatePageInDiv = function(URL,div){
	var url = Cyberoam.contextPath+"/webpages"+URL;
	Cyberoam.addOverLay();
	var requestForPage = function(url){
		$.ajax({
			url: url,
			success: function(html){
				//check if exist then only empty and pageload
				if($("#"+div).length > 0){
					$("#"+div).empty().append(html);
					Cyberoam.pageLoad(module);
				}
				Cyberoam.removeOverLay();
			}
		});
	}
	var requestForScript = function(module){
		var responseHandler = function(data, textStatus) {
			// textStatus is 'parsererror' when CSRFCheckFilter sends session timeout JSON
			if (textStatus === 'parsererror' && data.responseText && !isSessionValid(JSON.parse(data.responseText))) {
				return;
			}
			requestForPage(url);
		};
		$.ajax({ url:Cyberoam.contextPath+"/javascript/validation/"+module+".js?ver="+Cyberoam.version,
			dataType: 'script',
			cache:true,
			success: responseHandler,
			error: function (e) {
				Cyberoam.removeOverLay();
				Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
			}
		});
	};
	var requestForDataObject = function(module){
		var postURL=Cyberoam.contextPath+"/Controller?"+URL.substring(URL.indexOf("?")+1);
		$.ajax({ url:postURL,
			cache:false,
			success: function(data){
						try{
							if(data.indexOf("Language.PageDenied") != -1){
								Cyberoam.fillContentInDiv(data,width,height);
								Cyberoam.removeOverLay();
								return;
							}
						}catch(e){}
						var requestObj = JSON.parse(data);
						if (!isSessionValid(requestObj)) {
							return;
						}else if(requestObj.status != 599)
							requestForScript(module);
						else{
							Cyberoam.removeOverLay();
							Cyberoam.sendPageRequest("/AccessPermissionDenied.jsp");
						}
						Cyberoam.pageObject[Cyberoam.pageLayer].dataObject = requestObj;
						Cyberoam.getDataObject = requestObj;
				},
				error: function (e) {
					Cyberoam.removeOverLay();
					Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
				}
		});
	};
	var isSessionValid = function(response) {
		var isValid = true;
		if (response.status == CSCConstants.SESSION_EXPIRED) {
			isValid = false;
			if (typeof loginFrom != "undefined" && loginFrom == "userportal") {
				location.href = "/userportal/webpages/myaccount/login.jsp";
			} else {
				location.href = Cyberoam.contextPath + "/webpages/login.jsp";
			}
		}
		return isValid;
	};
	var module = URL.substring(0, URL.indexOf("."));
	module = module.substring(module.lastIndexOf("/")+1);
	if(URL.indexOf(".jsp") != -1) {
		url = Cyberoam.getURL(url, 't', new Date().getTime());
	}else {
		url = Cyberoam.getURL(url, 't', Cyberoam.version);
	}
	Cyberoam.pageObject[Cyberoam.pageLayer].module = module;
	Cyberoam.pageObject[Cyberoam.pageLayer].objectID = Cyberoam.getRequestParam(url,"objectID");
	if(Cyberoam.getRequestParam(url,"mode") == "300" && URL.indexOf(".jsp") == -1)
		requestForDataObject(module);
	else
		requestForScript(module);
}
Cyberoam.getiviewPageInDiv = function(URL,div){
	var url="";
	if(URL.indexOf(".jsp") == -1)
		url = "/iview/webpages/"+URL;
	else
		url = Cyberoam.contextPath+"/webpages/iview/"+URL;

	Cyberoam.addOverLay();
	var requestForPage = function(url){
		$.ajax({
			url: url,
			contentType: "application/x-www-form-urlencoded; charset=utf-8",
			success: function(html){
				$("#"+div).html(html);
				Cyberoam.pageLoad(module);
				Cyberoam.removeOverLay();
			}
		});
	};
	var requestForLanguageScript = function(module){
		var responseHandler = function(data) {
			if (typeof data !== 'string' && data.responseText && !isSessionValid(JSON.parse(data.responseText))) {
				return;
			}
			requestForPage(url);
		};
		$.ajax({ url:"/iview/javascript/lang/"+Cyberoam.currentLanguage+"/"+module+".js?ver="+Cyberoam.version,
			dataType: 'script',
			cache:true,
			success: responseHandler,
			error: function (e) {
				Cyberoam.removeOverLay();
				Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
			}
		});
	};
	var requestForScript = function(module){
		var responseHandler = function(data, textStatus) {
			// textStatus is 'parsererror' when CSRFCheckFilter sends session timeout JSON
			if (textStatus === 'parsererror' && data.responseText && !isSessionValid(JSON.parse(data.responseText))) {
				return;
			}
			requestForPage(url);
		};
		$.ajax({ url:"/iview/javascript/validation/"+module+".js?ver="+Cyberoam.version,
			dataType: 'script',
			cache:true,
			success: responseHandler,
			error: function (e) {
				Cyberoam.removeOverLay();
				Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
			}
		});
	};
	var requestForDataObject = function(module){
		var postURL=Cyberoam.contextPath+"/AjaxController";
		var params = URL.substring(URL.indexOf("?")+1);
		if(params.match("json")=="json" && params.match("startdate")=="startdate" && params.match("edndate")=="edndate"){
			params=params.split("startdate:")[0]+"startdate:"+Cyberoam.start+",edndate:"+Cyberoam.end+"}";
		}
		$.ajax({ url:postURL,
			cache:false,
			data:params,
			type: "POST",
			contentType: "application/x-www-form-urlencoded; charset=utf-8",
			success: function(data){
				try{
					if(data.indexOf("Language.PageDenied") != -1){
						Cyberoam.fillContentInDiv(data,width,height);
						Cyberoam.removeOverLay();
						return;
					}
				}catch(e){}
				var requestObj = JSON.parse(data);
				if (!isSessionValid(requestObj)) {
					return;
				}else if(requestObj.status == 597){
					location.href=Cyberoam.contextPath+"/webpages/login.jsp";
				}else if(requestObj.status != 599){
					requestForScript(module);
				}else {
					Cyberoam.removeOverLay();
					Cyberoam.sendPageRequest("/AccessPermissionDenied.html");
				}
				Cyberoam.pageObject[Cyberoam.pageLayer].dataObject = requestObj;
				Cyberoam.getDataObject = requestObj;
		},
		error: function (e) {
			Cyberoam.removeOverLay();
			Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
		}
		});
	};
	var isSessionValid = function(response) {
		var isValid = true;
		if (response.status == CSCConstants.SESSION_EXPIRED) {
			isValid = false;
			location.href = Cyberoam.contextPath + "/webpages/login.jsp";
		}
		return isValid;
	};
	var module = URL.substring(0, URL.indexOf("."));
	module = module.substring(module.lastIndexOf("/")+1);
	if(URL.indexOf(".jsp") != -1) {
		url = Cyberoam.getURL(url, 't', new Date().getTime());
	}else {
		url = Cyberoam.getURL(url, 't', Cyberoam.version);
	}
	Cyberoam.pageObject[Cyberoam.pageLayer].module = module;
	Cyberoam.pageObject[Cyberoam.pageLayer].objectID = Cyberoam.getRequestParam(url,"objectID");
	if(URL.indexOf(".jsp") == -1)
		requestForDataObject(module);
	else
		requestForScript(module);
}
Cyberoam.getPageInDiv = function(URL,div){
	if(Cyberoam.getController() && Cyberoam.getController() == "iview"){
		Cyberoam.getiviewPageInDiv(URL,div);
	}else{
		Cyberoam.getCorporatePageInDiv(URL,div);
	}
}

Cyberoam.corporatePageRequest = function(URL,width,height){
	var div = "popup"+(Cyberoam.pageLayer);
	var url = Cyberoam.contextPath+"/webpages"+URL;
	url = Cyberoam.getURL(url,'popup',Cyberoam.pageLayer);
	Cyberoam.addOverLay();
	var requestForPage = function(url){
		$.ajax({
			url: url,
			success: function(html){
				Cyberoam.fillContentInDiv(html,width,height);
				if(html.indexOf("Language.PageDenied") == -1)
					Cyberoam.pageLoad(module);
				else{
					if(Cyberoam.pageLayer == 0){
						Cyberoam.setLabelValue(document.getElementById(Cyberoam.mainFrame));
					}else
						Cyberoam.setLabelValue(document.getElementById('popup'+Cyberoam.pageLayer));
					Cyberoam.setPageSize();
				}
				Cyberoam.removeOverLay();
			}
		});
	}
	var requestForScript = function(module){
		var responseHandler = function(data, textStatus) {
			// textStatus is 'parsererror' when CSRFCheckFilter sends session timeout JSON
			if (textStatus === 'parsererror' && data.responseText && !isSessionValid(JSON.parse(data.responseText))) {
				return;
			}
			requestForPage(url);
		};
		$.ajax({ url:Cyberoam.contextPath+"/javascript/validation/"+module+".js?ver="+Cyberoam.version,
			dataType: 'script',
			cache:true,
			success: responseHandler,
			error: function (e) {
				Cyberoam.removeOverLay();
				Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
			}
		});
	};
	var requestForDataObject = function(module){
		var postURL=Cyberoam.contextPath+"/Controller?"+URL.substring(URL.indexOf("?")+1);
		$.ajax({ url:postURL,
			cache:false,
			success: function(data){
						try{
							if(data.indexOf("Language.PageDenied") != -1){
								Cyberoam.fillContentInDiv(data,width,height);
								Cyberoam.removeOverLay();
								return;
							}
						}catch(e){}
						var requestObj = JSON.parse(data);
						if (!isSessionValid(requestObj)) {
							return;
						} else if(requestObj.status != 599 && requestObj.status != 502)
							requestForScript(module);
						else if(requestObj.status == 599){
							Cyberoam.removeOverLay();
							Cyberoam.sendPageRequest("/AccessPermissionDenied.jsp");
						}else if(requestObj.status == 502){
							Cyberoam.removeOverLay();
							Cyberoam.setStatusBarMessage(Message.RecordNotExists,requestObj.status);
							if(Cyberoam.pageObject[0].prevURL != "")
								Cyberoam.setMainFrame(Cyberoam.pageObject[0].prevURL,1);
							return;
						}
						Cyberoam.pageObject[Cyberoam.pageLayer].dataObject = requestObj;
						Cyberoam.getDataObject = requestObj;
				},
          error: function (e){
                        Cyberoam.removeOverLay();
                        Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
               }

		});
	};
	var isSessionValid = function(response) {
		var isValid = true;
		if (response.status == CSCConstants.SESSION_EXPIRED) {
			isValid = false;
			if (typeof loginFrom != "undefined" && loginFrom == "userportal") {
				location.href = "/userportal/webpages/myaccount/login.jsp";
			} else {
				location.href = Cyberoam.contextPath + "/webpages/login.jsp";
			}
		}
		return isValid;
	};
	var module = URL.substring(0, URL.indexOf("."));
	module = module.substring(module.lastIndexOf("/")+1);
	if(URL.indexOf(".jsp") != -1) {
		url = Cyberoam.getURL(url, 't', new Date().getTime());
	}else {
		url = Cyberoam.getURL(url, 't', Cyberoam.version);
	}
	Cyberoam.pageObject[Cyberoam.pageLayer].module = module;
	Cyberoam.pageObject[Cyberoam.pageLayer].objectID = Cyberoam.getRequestParam(url,"objectID");
	if(Cyberoam.getRequestParam(url,"mode") == "300")
		requestForDataObject(module);
	else
		requestForScript(module);
}

Cyberoam.iviewPageRequest = function(URL,width,height){
	var div = "popup"+(Cyberoam.pageLayer);
	var url="";
	if(URL.indexOf(".jsp") == -1)
		url = "/iview/webpages/"+URL;
	else
		url = Cyberoam.contextPath+"/webpages/iview/"+URL;

	url = Cyberoam.getURL(url,'popup',Cyberoam.pageLayer);
	Cyberoam.addOverLay();
	var aUrl = url;
	var params = "";
	if(url.indexOf("?")>0){
		aUrl = url.substring(0,url.indexOf("?"));
		params = url.substring(url.indexOf("?")+1);
	}
	var requestForPage = function(url){
		$.ajax({
			type: "POST",
			url: aUrl,
			data:params,
			contentType: "application/x-www-form-urlencoded; charset=utf-8",
			success: function(html){
				if(typeof html.status != "undefined" && html.status == 597){
					location.href=Cyberoam.contextPath+"/webpages/login.jsp";
				}
				Cyberoam.fillContentInDiv(html,width,height);

				if(html.indexOf("Language.PageDenied") == -1)
					Cyberoam.pageLoad(module);
				else{
					if(Cyberoam.pageLayer == 0){
						Cyberoam.setLabelValue(document.getElementById(Cyberoam.mainFrame));
					}else
						Cyberoam.setLabelValue(document.getElementById('popup'+Cyberoam.pageLayer));
					Cyberoam.setPageSize();
				}
				Cyberoam.removeOverLay();
			}
		});
	};
	var requestForLanguageScript = function(module){
		var responseHandler = function(data) {
			requestForPage(url);
		};
		$.ajax({ url:"/iview/javascript/lang/"+Cyberoam.language+"/"+module+".js?ver="+Cyberoam.version,
			dataType: 'script',
			cache:true,
			success: responseHandler,
			error: function (e) {
				Cyberoam.removeOverLay();
				Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
			}
		});
	};
	var requestForScript = function(module){
		var responseHandler = function(data, textStatus) {
			// textStatus is 'parsererror' when CSRFCheckFilter sends session timeout JSON
			if (textStatus === 'parsererror' && data.responseText && !isSessionValid(JSON.parse(data.responseText))) {
				return;
			}
			requestForPage(url);
		};
		$.ajax({ url:"/iview/javascript/validation/"+module+".js?ver="+Cyberoam.version,
			dataType: 'script',
			cache:true,
			success: responseHandler,
			error: function (e) {
				Cyberoam.removeOverLay();
				Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
			}
		});
	};
	var requestForDataObject = function(module){
		var postURL=Cyberoam.contextPath+"/AjaxController";
		var params = URL.substring(URL.indexOf("?")+1);
		$.ajax({ url:postURL,
			data:params,
			type: "POST",
			cache:false,
			dataType:"json",
			contentType: "application/x-www-form-urlencoded; charset=utf-8",
			success: function(data){
				try{
					if(data.indexOf("Language.PageDenied") != -1){
						Cyberoam.fillContentInDiv(data,width,height);
						Cyberoam.removeOverLay();
						return;
					}
				}catch(e){}
				var requestObj = data;
				if (!isSessionValid(requestObj)) {
					return;
				} else if (typeof requestObj.status == "undefined" || (requestObj.status != 599 && requestObj.status != 502))
					requestForScript(module);
				else if(requestObj.status == 599){
					Cyberoam.removeOverLay();
					Cyberoam.sendPageRequest("/AccessPermissionDenied.jsp");
				}else if(requestObj.status == 502){
					Cyberoam.removeOverLay();
					Cyberoam.setStatusBarMessage(Message.RecordNotExists,requestObj.status);
					if(Cyberoam.pageObject[0].prevURL != "")
						Cyberoam.setMainFrame(Cyberoam.pageObject[0].prevURL,1);
					return;
				}
				Cyberoam.pageObject[Cyberoam.pageLayer].dataObject = requestObj;
				Cyberoam.getDataObject = requestObj;
				},error:function(e){
					Cyberoam.removeOverLay();
					var bodyText=e.responseText;
					if(typeof bodyText !== "undefined") {
					if(bodyText.indexOf("session_ex.png") != -1 || bodyText.indexOf("Language.PageDenied") != -1){
						location.href=Cyberoam.contextPath+"/webpages/login.jsp";
						}
					}else {
						Cyberoam.setStatusBarMessage(Language.noConnectivity,505);
					}
				},
				complete: function() {
				}
		});
	};
	var isSessionValid = function(response) {
		var isValid = true;
		if (response.status == CSCConstants.SESSION_EXPIRED) {
			isValid = false;
			location.href = Cyberoam.contextPath + "/webpages/login.jsp";
		}
		return isValid;
	};
	var module = URL.substring(0, URL.indexOf("."));
	module = module.substring(module.lastIndexOf("/")+1);
	if(URL.indexOf(".jsp") != -1) {
		url = Cyberoam.getURL(url, 't', new Date().getTime());
	}else {
		url = Cyberoam.getURL(url, 't', Cyberoam.version);
	}
	Cyberoam.pageObject[Cyberoam.pageLayer].module = module;
	Cyberoam.pageObject[Cyberoam.pageLayer].objectID = Cyberoam.getRequestParam(url,"objectID");
	if(URL.indexOf(".jsp") == -1)
		requestForDataObject(module);
	else
		requestForScript(module);
}

Cyberoam.sendPageRequest = function(URL,width,height){
	if(Cyberoam.getController() && Cyberoam.getController() == "iview"){
		Cyberoam.iviewPageRequest(URL,width,height);
	}else{
		Cyberoam.corporatePageRequest(URL,width,height);
	}
};

Cyberoam.getController = function(){
    if(Cyberoam.getPageRequestParameter("ctrl") && (Cyberoam.getPageRequestParameter("ctrl") != null || Cyberoam.getPageRequestParameter("ctrl") != "null"))
            Cyberoam.appController = Cyberoam.getPageRequestParameter("ctrl");

    if(typeof Cyberoam.appController == "undefined")
    	Cyberoam.appController = Cyberoam.defaultController;

    return Cyberoam.appController;
}

Cyberoam.parentPage = function(pageLayer){
	if(typeof pageLayer == "undefined")
		return Cyberoam.pageObject[Cyberoam.pageLayer-1].module;
	else
		return Cyberoam.pageObject[pageLayer].module;
};

Cyberoam.getRequestParam = function(url,param){
	if(url.indexOf(param+"=") != -1){
		var start = url.indexOf(param+"=") + param.length+1;
		if(url.indexOf("&",start) != -1)
			return url.substring(start,url.indexOf("&",start));
		else
			return url.substring(start);
	}
	return null;
};
Cyberoam.removeRequestParam = function(url,param){
	if(url.indexOf(param+"=") != -1){
		var start = url.indexOf(param+"=");
		var endindex = url.indexOf("&",start);
		if(endindex == -1)
			return url.substring(0,start);
		else
			return url.substring(0,start)+url.substring(endindex);
	}else{
		return url;
	}
};

//// Popup Movable code start
function getID(id){
    return document.getElementById(id);
};
//Global object to hold drag information.
var dragObj = new Object();
function dragStart(event, id) {
	var x, y;
	dragObj.elNode = getID(id);
	// Get cursor position with respect to the page.
	try {
		x = window.event.clientX + document.documentElement.scrollLeft
		  + document.body.scrollLeft;
		y = window.event.clientY + document.documentElement.scrollTop
		  + document.body.scrollTop;
	}  catch (e) {
		x = event.clientX + window.scrollX;
		y = event.clientY + window.scrollY;
	}
	//Save starting positions of cursor and element.
	dragObj.cursorStartX = x;
	dragObj.cursorStartY = y;
	dragObj.elStartLeft  = parseInt(dragObj.elNode.style.left, 10);
	dragObj.elStartTop   = parseInt(dragObj.elNode.style.top,  10);
	if (isNaN(dragObj.elStartLeft)) dragObj.elStartLeft = 0;
	if (isNaN(dragObj.elStartTop))  dragObj.elStartTop  = 0;
	dragapproved = true;
	document.onmousemove=function(event){dragGo(event);
		var event = new Cyberoam.Event(event);
		event.clearKeyCode();
		return;
	};
	return false;
};
var dragapproved=false;
var z,x,y;
var maxleft,maxtop,maxright,maxbottom;
function dragGo(event) {
    var x, y;
    //Get cursor position with respect to the page.
	try  {
		x = window.event.clientX + document.documentElement.scrollLeft
		  + document.body.scrollLeft;
		y = window.event.clientY + document.documentElement.scrollTop
		  + document.body.scrollTop;

	}  catch (e) {
		x = event.clientX + window.scrollX;
		y = event.clientY + window.scrollY;
	}
    if (dragapproved){
		// Move drag element by the same amount the cursor has moved.
		var drLeft = (dragObj.elStartLeft + x - dragObj.cursorStartX);
		var drTop = (dragObj.elStartTop  + y - dragObj.cursorStartY);
		if (drLeft > 0)  {
		 dragObj.elNode.style.left = drLeft  + "px";
		} else  {
		    dragObj.elNode.style.left = "1px";
		}
		if (drTop > 0)  {
		 dragObj.elNode.style.top  = drTop + "px";
		}  else  {
		    dragObj.elNode.style.top  = "1px";
		}
		if (y >= (document.getElementById("wrapper").offsetHeight - 50)){
		  dragObj.elNode.style.top  = (document.getElementById("wrapper").offsetHeight - 70)+"px";
		}
		if (x >= (document.getElementById("wrapper").offsetWidth - 50)){
			  dragObj.elNode.style.left  = (document.getElementById("wrapper").offsetWidth - 70)+"px";
		}

		return false;
    }
};
document.onmouseup=new Function("dragapproved=false; document.onmousemove=null;");

Cyberoam.showWidgetPopup = function (config){
	if(Cyberoam.currentObject != null)
		Cyberoam.currentObject.hide();
	Cyberoam.pageLayer++;
	Cyberoam.pageObject[Cyberoam.pageLayer] = config;
	Cyberoam.pageObject[Cyberoam.pageLayer].timers = {};
	Cyberoam.pageObject[Cyberoam.pageLayer].widgetPopup = true;
	if(config.popupDiv){
		Cyberoam.pageObject[Cyberoam.pageLayer].popupDiv = config.popupDiv;
		Cyberoam.hideShowWidgetPopupTR(config.popupDiv,"");
	}
	Cyberoam.createWidgetPopupDiv(config);
	document.getElementById('TB_overlay').style.opacity = "0.3";
	
	if(config.hideTitle) {
		document.getElementById("widgetPopupTitle"+(Cyberoam.pageLayer)+"").style.display='none';
	}

	if(config.URL) {
		Cyberoam.pageObject[Cyberoam.pageLayer].operation = Cyberoam.getRequestParam(config.URL,"operation");
		Cyberoam.sendPageRequest(config.URL,config.width,config.height);
	} else if(config.id) {
		Cyberoam.setPopupContent(config.id,config.width,config.height);
	}
	Cyberoam.setStatusBarMessage("","");
	Cyberoam.onEscPopupClose("popupouter"+Cyberoam.pageLayer);
};

Cyberoam.createLightboxOverlay = function() {
	var thickBox = document.getElementById('TB_overlay');
	if(!thickBox){
		thickBox = document.createElement("div");
		thickBox.className = "TB_overlayBG";
		thickBox.id="TB_overlay";
		document.body.appendChild(thickBox);
	}
	thickBox.style.zIndex = 200 * Cyberoam.pageLayer;
	thickBox.style.width = document.body.scrollWidth;
	thickBox.style.height = document.body.scrollHeight;
	return thickBox;
}

Cyberoam.createWidgetPopupDiv = function(config) {
	var closeHTML = "";
	var hideCloseButton = false;

	// popupDiv set related logical
	var popupHostElementId = "";
	if(Cyberoam.pageObject[Cyberoam.pageLayer].popupDiv){
		popupHostElementId = Cyberoam.pageObject[Cyberoam.pageLayer].popupDiv;
	}else if(Cyberoam.pageObject[Cyberoam.pageLayer-1] && Cyberoam.pageObject[Cyberoam.pageLayer-1].popupDiv){
		popupHostElementId = Cyberoam.pageObject[Cyberoam.pageLayer-1].popupDiv;
	}

	var popupHostElement;
	if(!popupHostElementId) {
		jQuery("<div id=widget-popup-"+(Cyberoam.pageLayer)+" class='cp-wrapper'></div>").appendTo(document.body);
		popupHostElement = document.getElementById("widget-popup-"+(Cyberoam.pageLayer)+"");
	} else {
		popupHostElement = document.getElementById("" + popupHostElementId + "");
	}


	$(popupHostElement).addClass("widgetPopup");

	var pageTitle = "";
	if(Cyberoam.pageObject[Cyberoam.pageLayer].title){
		pageTitle = Cyberoam.pageObject[Cyberoam.pageLayer].title;
	}else if(config.title){
		pageTitle = config.title;
	}
	if($("#tabs-container").length == 0){
		$("<div id='tabs-container' class='widgetPopupDiv'><div class='widgetPopupTitle' id='widgetPopupTitle"+(Cyberoam.pageLayer)+"'><div class='widgetPopupHeader-focus'>" + pageTitle + "</div></div><div class='icomoon-x popup-close-icon' onclick='Cyberoam.hidePopup();'></div></div>").appendTo(popupHostElement);
		$("<div id=popupouter"+(Cyberoam.pageLayer)+" class='popupouter'><div id=popup"+(Cyberoam.pageLayer)+" style='position: relative'></div></div>").appendTo($("#tabs-container"));
	}else{
		if(Cyberoam.pageObject[Cyberoam.pageLayer].inlinePopup == false || Cyberoam.pageObject[Cyberoam.pageLayer-1].widgetPopup == true){
			$("#widgetPopupTitle"+(Cyberoam.pageLayer-1)).find(".widgetPopupHeader-focus").addClass("widgetPopupHeader").removeClass("widgetPopupHeader-focus");
			$('#widgetPopupTitle'+(Cyberoam.pageLayer-1)).after('<div class="fa fa-caret-right popup-breadcrumb"></div>');
			$("#popupouter"+(Cyberoam.pageLayer-1)).hide();
		}
		$("<div class='widgetPopupTitle' id='widgetPopupTitle"+(Cyberoam.pageLayer)+"'><div class='widgetPopupHeader-focus'>" + pageTitle + "</div></div>").appendTo("#tabs-container");
		$("<div id=popupouter"+(Cyberoam.pageLayer)+" class='popupouter'><div id=popup"+(Cyberoam.pageLayer)+" style='position: relative'></div></div>").appendTo($("#tabs-container"));
	}

	// create Overlay
	var thickBox = Cyberoam.createLightboxOverlay();

	document.getElementById("popup"+Cyberoam.pageLayer).parentNode.style.zIndex = 200 * Cyberoam.pageLayer + 1;
	document.getElementById("tabs-container").style.zIndex = 200 * Cyberoam.pageLayer + 1;
	document.getElementById("tabs-container").parentNode.style.zIndex = 200 * Cyberoam.pageLayer + 1;


	if(!popupHostElementId) {
		Cyberoam.pageObject[Cyberoam.pageLayer].widgetPopupFixedPosition = true;
		popupHostElement.style.position = "fixed";
		document.getElementById("popup"+Cyberoam.pageLayer).parentNode.style.zIndex = 200 * Cyberoam.pageLayer + 1;
		document.getElementById("tabs-container").style.zIndex = 200 * Cyberoam.pageLayer + 1;
		document.getElementById("tabs-container").parentNode.style.zIndex = 200 * Cyberoam.pageLayer + 1;

		var top = parseInt((document.documentElement.clientHeight - popupHostElement.offsetHeight) / 2);
		var left = parseInt((document.documentElement.clientWidth - popupHostElement.offsetWidth) / 2);
		popupHostElement.style.top = top + "px";
		popupHostElement.style.left = left + "px";
	}
};


/* This function is use to hide and show Widget Popup div's parent TR element.
 * this page check popup div object and takes its parent's parent TR element and make its display as per display argument.
*/
Cyberoam.hideShowWidgetPopupTR = function(popupDiv,display){
	if(popupDiv && $("#"+popupDiv)[0]){
		var popDivObject = $("#"+popupDiv);
		if(popDivObject.parent()[0] && popDivObject.parent().parent()[0] &&
				popDivObject.parent().parent()[0].tagName &&
				popDivObject.parent().parent()[0].tagName.toLowerCase() == "tr"){
			popDivObject.parent().parent()[0].style.display = display;
		}
	}
};
/*
 * messageBox/widgetPopup/popup will close on Esc key press.
 */
Cyberoam.onEscPopupClose = function(popupid) {
	$("#" + popupid).on('keyup',function(e) {
		var event = new Cyberoam.Event(e);
		if (event.getKeyCode() == 27) {
			if (Cyberoam.pageLayer > 0 && (Cyberoam.pageObject[Cyberoam.pageLayer].widgetPopup || typeof Cyberoam.pageObject[Cyberoam.pageLayer].inlinePopup == "undefined")) {
				if (Cyberoam.pageObject[Cyberoam.pageLayer].close == undefined && Cyberoam.pageObject[Cyberoam.pageLayer].close != false) {
					Cyberoam.hidePopup();
					return;
				}
			}
		}
	});
}


/** The Calendar object constructor. */
Calendar = function (firstDayOfWeek, dateStr, onSelected, onClose) {
	// member variables
	this.activeDiv = null;
	this.currentDateEl = null;
	this.getDateStatus = null;
	this.timeout = null;
	this.onSelected = onSelected || null;
	this.onClose = onClose || null;
	this.dragging = false;
	this.hidden = false;
	this.minYear = 1970;
	this.maxYear = 2050;
	this.dateFormat = Calendar._TT["DEF_DATE_FORMAT"];
	this.ttDateFormat = Calendar._TT["TT_DATE_FORMAT"];
	this.isPopup = true;
	this.weekNumbers = true;
	this.mytab = false;
	this.firstDayOfWeek = firstDayOfWeek; // 0 for Sunday, 1 for Monday, etc.
	this.showsOtherMonths = false;
	this.dateStr = dateStr;
	this.ar_days = null;
	this.showsTime = false;
	this.time24 = true;
	this.yearStep = 2;
	this.timeFormatOnToday = 0;
	// HTML elements
	this.table = null;
	this.element = null;
	this.tbody = null;
	this.firstdayname = null;
	// Combo boxes
	this.monthsCombo = null;
	this.yearsCombo = null;
	this.hilitedMonth = null;
	this.activeMonth = null;
	this.hilitedYear = null;
	this.activeYear = null;
	// Information
	this.dateClicked = false;

	// one-time initializations
	if (typeof Calendar._SDN == "undefined") {
		// table of short day names
		if (typeof Calendar._SDN_len == "undefined")
			Calendar._SDN_len = 3;
		var ar = new Array();
		for (var i = 8; i > 0;) {
			ar[--i] = Calendar._DN[i].substr(0, Calendar._SDN_len);
		}
		Calendar._SDN = ar;
		// table of short month names
		if (typeof Calendar._SMN_len == "undefined")
			Calendar._SMN_len = 3;
		ar = new Array();
		for (var i = 12; i > 0;) {
			ar[--i] = Calendar._MN[i].substr(0, Calendar._SMN_len);
		}
		Calendar._SMN = ar;
	}
};

// ** constants

/// "static", needed for event handlers.
Calendar._C = null;

/// detect a special case of "web browser"
Calendar.is_ie = ( /msie/i.test(navigator.userAgent) &&
		   !/opera/i.test(navigator.userAgent) );

Calendar.is_ie5 = ( Calendar.is_ie && /msie 5\.0/i.test(navigator.userAgent) );

/// detect Opera browser
Calendar.is_opera = /opera/i.test(navigator.userAgent);

/// detect KHTML-based browsers
Calendar.is_khtml = /Konqueror|Safari|KHTML/i.test(navigator.userAgent);

// detect Chrome browser
Calendar.is_chrome = /chrome/i.test(navigator.userAgent);
// BEGIN: UTILITY FUNCTIONS; beware that these might be moved into a separate
//        library, at some point.

Calendar.getAbsolutePos = function(el) {
	var SL = 0, ST = 0;
	var is_div = /^div$/i.test(el.tagName);
	if (is_div && el.scrollLeft)
		SL = el.scrollLeft;
	if (is_div && el.scrollTop)
		ST = el.scrollTop;
	var r = { x: el.offsetLeft - SL, y: el.offsetTop - ST };
	if (el.offsetParent) {
		var tmp = this.getAbsolutePos(el.offsetParent);
		r.x += tmp.x;
		r.y += tmp.y;
	}
	return r;
};

Calendar.isRelated = function (el, evt) {
	var related = evt.relatedTarget;
	if (!related) {
		var type = evt.type;
		if (type == "mouseover") {
			related = evt.fromElement;
		} else if (type == "mouseout") {
			related = evt.toElement;
		}
	}
	/*while (related) {
		if (related == el) {
			return true;
		}
		related = related.parentNode;
	}*/
	return false;
};

Calendar.removeClass = function(el, className) {
	if (!(el && el.className)) {
		return;
	}
	var cls = el.className.split(" ");
	var ar = new Array();
	for (var i = cls.length; i > 0;) {
		if (cls[--i] != className) {
			ar[ar.length] = cls[i];
		}
	}
	el.className = ar.join(" ");
};

Calendar.addClass = function(el, className) {
	Calendar.removeClass(el, className);
	el.className += " " + className;
};

Calendar.getElement = function(ev) {
	if (Calendar.is_ie) {
		return window.event.srcElement;
	} else {
		return ev.currentTarget;
	}
};

Calendar.getTargetElement = function(ev) {
	if (Calendar.is_ie) {
		return window.event.srcElement;
	} else {
		return ev.target;
	}
};

Calendar.stopEvent = function(ev) {
	ev || (ev = window.event);
	if (Calendar.is_ie) {
		ev.cancelBubble = true;
		ev.returnValue = false;
	} else {
		ev.preventDefault();
		ev.stopPropagation();
	}
	return false;
};

Calendar.addEvent = function(el, evname, func) {
	if (el.attachEvent) { // IE
		el.attachEvent("on" + evname, func);
	} else if (el.addEventListener) { // Gecko / W3C
		el.addEventListener(evname, func, true);
	} else {
		el["on" + evname] = func;
	}
};

Calendar.removeEvent = function(el, evname, func) {
	if (el.detachEvent) { // IE
		el.detachEvent("on" + evname, func);
	} else if (el.removeEventListener) { // Gecko / W3C
		el.removeEventListener(evname, func, true);
	} else {
		el["on" + evname] = null;
	}
};

Calendar.createElement = function(type, parent) {
	var el = null;
	if (document.createElementNS) {
		// use the XHTML namespace; IE won't normally get here unless
		// _they_ "fix" the DOM2 implementation.
		el = document.createElementNS("http://www.w3.org/1999/xhtml", type);
	} else {
		el = document.createElement(type);
	}
	if (typeof parent != "undefined") {
		parent.appendChild(el);
	}
	return el;
};

// END: UTILITY FUNCTIONS

// BEGIN: CALENDAR STATIC FUNCTIONS

/** Internal -- adds a set of events to make some element behave like a button. */
Calendar._add_evs = function(el) {
	with (Calendar) {
		addEvent(el, "mouseover", dayMouseOver);
		addEvent(el, "mousedown", dayMouseDown);
		addEvent(el, "mouseout", dayMouseOut);
		if (is_ie) {
			addEvent(el, "dblclick", dayMouseDblClick);
			el.setAttribute("unselectable", true);
		}
	}
};
Calendar.myeve = function(el) {
	with (Calendar) {
		addEvent(el, "mousedown", dayMouseDown);
		if (is_ie) {
			//addEvent(el, "dblclick", dayMouseDblClick);
			el.setAttribute("unselectable", true);
		}
	}
};


Calendar.findMonth = function(el) {
	if (typeof el.month != "undefined") {
		return el;
	} else if (typeof el.parentNode.month != "undefined") {
		return el.parentNode;
	}
	return null;
};

Calendar.findYear = function(el) {
	if (typeof el.year != "undefined") {
		return el;
	} else if (typeof el.parentNode.year != "undefined") {
		return el.parentNode;
	}
	return null;
};

Calendar.showMonthsCombo = function () {
	var cal = Calendar._C;
	if (!cal) {
		return false;
	}
	var cal = cal;
	var cd = cal.activeDiv;
	var mc = cal.monthsCombo;
	if (cal.hilitedMonth) {
		Calendar.removeClass(cal.hilitedMonth, "hilite");
	}
	if (cal.activeMonth) {
		Calendar.removeClass(cal.activeMonth, "active");
	}
	var mon = cal.monthsCombo.getElementsByTagName("div")[cal.date.getMonth()];
	Calendar.addClass(mon, "active");
	cal.activeMonth = mon;
	var s = mc.style;
	s.display = "block";
	if (cd.navtype < 0)
		s.left = cd.offsetLeft + "px";
	else {
		var mcw = mc.offsetWidth;
		if (typeof mcw == "undefined")
			// Konqueror brain-dead techniques
			mcw = 50;
		s.left = (cd.offsetLeft + cd.offsetWidth - mcw) + "px";
	}
	s.top = (cd.offsetTop + cd.offsetHeight) + "px";
};

Calendar.showYearsCombo = function (fwd) {
	var cal = Calendar._C;
	if (!cal) {
		return false;
	}
	var cal = cal;
	var cd = cal.activeDiv;
	var yc = cal.yearsCombo;
	if (cal.hilitedYear) {
		Calendar.removeClass(cal.hilitedYear, "hilite");
	}
	if (cal.activeYear) {
		Calendar.removeClass(cal.activeYear, "active");
	}
	cal.activeYear = null;
	var Y = cal.date.getFullYear() + (fwd ? 1 : -1);
	var yr = yc.firstChild;
	var show = false;
	for (var i = 12; i > 0; --i) {
		if (Y >= cal.minYear && Y <= cal.maxYear) {
			yr.firstChild.data = Y;
			yr.year = Y;
			yr.style.display = "block";
			show = true;
		} else {
			yr.style.display = "none";
		}
		yr = yr.nextSibling;
		Y += fwd ? cal.yearStep : -cal.yearStep;
	}
	if (show) {
		var s = yc.style;
		s.display = "block";
		if (cd.navtype < 0)
			s.left = cd.offsetLeft + "px";
		else {
			var ycw = yc.offsetWidth;
			if (typeof ycw == "undefined")
				// Konqueror brain-dead techniques
				ycw = 50;
			s.left = (cd.offsetLeft + cd.offsetWidth - ycw) + "px";
		}
		s.top = (cd.offsetTop + cd.offsetHeight) + "px";
	}
};

// event handlers

Calendar.tableMouseUp = function(ev) {
	var cal = Calendar._C;
	if (!cal) {
		return false;
	}
	if (cal.timeout) {
		clearTimeout(cal.timeout);
	}
	var el = cal.activeDiv;
	if (!el) {
		return false;
	}
	var target = Calendar.getTargetElement(ev);
	ev || (ev = window.event);
	Calendar.removeClass(el, "active");
	if (target == el || target.parentNode == el) {
		Calendar.cellClick(el, ev);
	}
	var mon = Calendar.findMonth(target);
	var date = null;
	if (mon) {
		date = new Date(cal.date);
		if (mon.month != date.getMonth()) {
			date.setMonth(mon.month);
			cal.setDate(date);
			cal.dateClicked = false;
			if(!cal.params.dateStatusFunc(date)){
				cal.callHandler();
			}
		}
	} else {
		var year = Calendar.findYear(target);
		if (year) {
			date = new Date(cal.date);
			if (year.year != date.getFullYear()) {
				date.setFullYear(year.year);
				cal.setDate(date);
				cal.dateClicked = false;
				if(!cal.params.dateStatusFunc(date)){
					cal.callHandler();
				}
			}
		}
	}
	with (Calendar) {
		removeEvent(document, "mouseup", tableMouseUp);
		removeEvent(document, "mouseover", tableMouseOver);
		removeEvent(document, "mousemove", tableMouseOver);
		cal._hideCombos();
		_C = null;
		return stopEvent(ev);
	}
};

Calendar.tableMouseOver = function (ev) {
	var cal = Calendar._C;
	if (!cal) {
		return;
	}
	var el = cal.activeDiv;
	var target = Calendar.getTargetElement(ev);
	if (target == el || target.parentNode == el) {
		Calendar.addClass(el, "hilite active");
		Calendar.addClass(el.parentNode, "rowhilite");
	} else {
		if (typeof el.navtype == "undefined" || (el.navtype != 50 && (el.navtype == 0 || Math.abs(el.navtype) > 2)))
			Calendar.removeClass(el, "active");
		Calendar.removeClass(el, "hilite");
		Calendar.removeClass(el.parentNode, "rowhilite");
	}
	ev || (ev = window.event);
	/*if (el.navtype == 50 && target != el) {
		var pos = Calendar.getAbsolutePos(el);
		var w = el.offsetWidth;
		var x = ev.clientX;
		var dx;
		var decrease = true;
		if (x > pos.x + w) {
			dx = x - pos.x - w;
			decrease = false;
		} else
			dx = pos.x - x;

		if (dx < 0) dx = 0;
		var range = el._range;
		var current = el._current;
		var count = Math.floor(dx / 10) % range.length;
		for (var i = range.length; --i >= 0;)
			if (range[i] == current)
				break;
		while (count-- > 0)
			if (decrease) {
				if (--i < 0)
					i = range.length - 1;
			} else if ( ++i >= range.length )
				i = 0;
		var newval = range[i];
		el.value = newval;

		cal.onUpdateTime();
	}*/
	var mon = Calendar.findMonth(target);
	if (mon) {
		if (mon.month != cal.date.getMonth()) {
			if (cal.hilitedMonth) {
				Calendar.removeClass(cal.hilitedMonth, "hilite");
			}
			Calendar.addClass(mon, "hilite");
			cal.hilitedMonth = mon;
		} else if (cal.hilitedMonth) {
			Calendar.removeClass(cal.hilitedMonth, "hilite");
		}
	} else {
		if (cal.hilitedMonth) {
			Calendar.removeClass(cal.hilitedMonth, "hilite");
		}
		var year = Calendar.findYear(target);
		if (year) {
			if (year.year != cal.date.getFullYear()) {
				if (cal.hilitedYear) {
					Calendar.removeClass(cal.hilitedYear, "hilite");
				}
				Calendar.addClass(year, "hilite");
				cal.hilitedYear = year;
			} else if (cal.hilitedYear) {
				Calendar.removeClass(cal.hilitedYear, "hilite");
			}
		} else if (cal.hilitedYear) {
			Calendar.removeClass(cal.hilitedYear, "hilite");
		}
	}
	return Calendar.stopEvent(ev);
};

Calendar.tableMouseDown = function (ev) {
	if (Calendar.getTargetElement(ev) == Calendar.getElement(ev)) {
		return Calendar.stopEvent(ev);
	}
};

Calendar.calDragIt = function (ev) {
	var cal = Calendar._C;
	if (!(cal && cal.dragging)) {
		return false;
	}
	var posX;
	var posY;
	if (Calendar.is_ie) {
		posY = window.event.clientY + document.body.scrollTop;
		posX = window.event.clientX + document.body.scrollLeft;
	} else {
		posX = ev.pageX;
		posY = ev.pageY;
	}
	cal.hideShowCovered();
	var st = cal.element.style;
	st.left = (posX - cal.xOffs) + "px";
	st.top = (posY - cal.yOffs) + "px";
	return Calendar.stopEvent(ev);
};

Calendar.calDragEnd = function (ev) {
	var cal = Calendar._C;
	if (!cal) {
		return false;
	}
	cal.dragging = false;
	with (Calendar) {
		removeEvent(document, "mousemove", calDragIt);
		removeEvent(document, "mouseup", calDragEnd);
		tableMouseUp(ev);
	}
	cal.hideShowCovered();
};

Calendar.dayMouseDown = function(ev) {
	var el = Calendar.getElement(ev);
	if (el.disabled) {
		return false;
	}
	var cal = el.calendar;
	if(!eval(cal)) { return; }
	cal.activeDiv = el;
	Calendar._C = cal;
	if (el.navtype != 300) with (Calendar) {
		if (el.navtype == 50) {
			el._current = el.value;
			addEvent(document, "mousemove", tableMouseOver);
		} else
			addEvent(document, Calendar.is_ie5 ? "mousemove" : "mouseover", tableMouseOver);
		addClass(el, "hilite active");
		addEvent(document, "mouseup", tableMouseUp);
	} else if (cal.isPopup) {
		cal._dragStart(ev);
	}
	if (el.navtype == -1 || el.navtype == 1) {
		if (cal.timeout) clearTimeout(cal.timeout);
		cal.timeout = setTimeout("Calendar.showMonthsCombo()", 250);
	} else if (el.navtype == -2 || el.navtype == 2) {
		if (cal.timeout) clearTimeout(cal.timeout);
		cal.timeout = setTimeout((el.navtype > 0) ? "Calendar.showYearsCombo(true)" : "Calendar.showYearsCombo(false)", 250);
	} else {
		cal.timeout = null;
	}
	return Calendar.stopEvent(ev);
};

Calendar.dayMouseDblClick = function(ev) {
	Calendar.cellClick(Calendar.getElement(ev), ev || window.event);
	if (Calendar.is_ie) {
		document.selection.empty();
	}
};

Calendar.dayMouseOver = function(ev) {
	var el = Calendar.getElement(ev);
	if (Calendar.isRelated(el, ev) || Calendar._C || el.disabled) {
		return false;
	}
	if (el.ttip) {
		if (el.ttip.substr(0, 1) == "_") {
			el.ttip = el.caldate.print(el.calendar.ttDateFormat) + el.ttip.substr(1);
		}
		el.calendar.tooltips.firstChild.data = el.ttip;
	}

	if (el.navtype != 300 && el.tagName!="IMG") {
		Calendar.addClass(el, "hilite");
		if (el.caldate) {
			Calendar.addClass(el.parentNode, "rowhilite");
		}
	}
	return Calendar.stopEvent(ev);
};

Calendar.dayMouseOut = function(ev) {
	with (Calendar) {
		var el = getElement(ev);
		if (isRelated(el, ev) || _C || el.disabled) {
			return false;
		}
		removeClass(el, "hilite");
		if (el.caldate) {
			removeClass(el.parentNode, "rowhilite");
		}
		el.calendar.tooltips.firstChild.data = _TT["DRAG_TO_MOVE"];
		return stopEvent(ev);
	}
};

/**
 *  A generic "click" handler :) handles all types of buttons defined in this
 *  calendar.
 */
Calendar.cellClick = function(el, ev) {
	var cal = el.calendar;
	if(!eval(cal)) { return; }
	var closing = false;
	var newdate = false;
	var date = null;
	if (typeof el.navtype == "undefined") {
		Calendar.removeClass(cal.currentDateEl, "selected");
		Calendar.addClass(el, "selected");
		closing = (cal.currentDateEl == el);
		if (!closing) {
			cal.currentDateEl = el;
		}
		el.caldate.setHours(cal.date.getHours());
        el.caldate.setMinutes(cal.date.getMinutes());
		cal.date = new Date(el.caldate);
		date = cal.date;
		newdate = true;
		// a date was clicked
		if (!(cal.dateClicked = !el.otherMonth))
			cal._init(cal.firstDayOfWeek, date);
	} else {
		if (el.navtype == 200) {
			Calendar.removeClass(el, "hilite");
			cal.callCloseHandler();
			return;
		}
		date = (el.navtype == 0) ? new Date() : new Date(cal.date);
		// unless "today" was clicked, we assume no date was clicked so
		// the selected handler will know not to close the calenar when
		// in single-click mode.
		// cal.dateClicked = (el.navtype == 0);
		cal.dateClicked = false;
		var year = date.getFullYear();
		var mon = date.getMonth();
		function setMonth(m) {
			var day = date.getDate();
			var max = date.getMonthDays(m);
			if (day > max) {
				date.setDate(max);
			}
			date.setMonth(m);
		};
		switch (el.navtype) {
		    case 400:
			Calendar.removeClass(el, "hilite");
			var text = Calendar._TT["ABOUT"];
			if (typeof text != "undefined") {
				text += cal.showsTime ? Calendar._TT["ABOUT_TIME"] : "";
			} else {
				// FIXME: this should be removed as soon as lang files get updated!
				text = "Help and about box text is not translated into this language.\n" +
					"If you know this language and you feel generous please update\n" +
					"the corresponding file in \"lang\" subdir to match calendar-en.js\n" +
					"and send it back to <mishoo@infoiasi.ro> to get it into the distribution  ;-)\n\n" +
					"Thank you!\n" +
					"http://dynarch.com/mishoo/calendar.epl\n";
			}
			callme(el.id);
			return;
		    case -2:
			if (year > cal.minYear) {
				date.setFullYear(year - 1);
			}
			break;
		    case -1:
			if (mon > 0) {
				setMonth(mon - 1);
			} else if (year-- > cal.minYear) {
				date.setFullYear(year);
				setMonth(11);
			}
			break;
		    case 1:
			if (mon < 11) {
				setMonth(mon + 1);
			} else if (year < cal.maxYear) {
				date.setFullYear(year + 1);
				setMonth(0);
			}
			break;
		    case 2:
			if (year < cal.maxYear) {
				date.setFullYear(year + 1);
			}
			break;
		    case 100:
			cal.setFirstDayOfWeek(el.fdow);
			return;
		    case 50:
			var range = el._range;
			var current = el.value;
			for (var i = range.length; --i >= 0;)
				if (range[i] == current)
					break;
			if (ev && ev.shiftKey) {
				if (--i < 0)
					i = range.length - 1;
			} else if ( ++i >= range.length )
				i = 0;
			var newval = range[i];
			el.value = newval;
			cal.onUpdateTime();
			return;
		    case 0:
			// TODAY will bring us here 
			//
			if(cal.timeFormatOnToday != 0){
				if(cal.timeFormatOnToday == 1){
					date.setHours(00,00,00);
				} else if(cal.timeFormatOnToday == 2){
					date.setHours(23,59,59);
				}
			}
			if ((typeof cal.getDateStatus == "function") && cal.getDateStatus(date, date.getFullYear(), date.getMonth(), date.getDate())) {
				// remember, "date" was previously set to new
				// Date() if TODAY was clicked; thus, it
				// contains today date.
				Cyberoam.messageBox({message:Calendar._TT["TODAY_NOT_ALLOWED"]});
				return false;
			}
			break;
		}
		if (!date.equalsTo(cal.date)) {
			cal.setDate(date);
			newdate = true;
		}
	}
	if (newdate && !cal.params.dateStatusFunc(cal.date)) {
		cal.callHandler();
	}
	if (closing) {
		Calendar.removeClass(el, "hilite");
		cal.callCloseHandler();
	}
};

