var DropDownMenu = React.createClass({displayName: "DropDownMenu",
	mixins: [DropdownStateMixin],
	getInitialState: function() {
		return {
			hoverVictim: false
		};
	},
	handleClick: function(e) {
		e.preventDefault();

		if(this.props.config.shouldStateChange && typeof this.props.config.shouldStateChange === "function"  && !this.props.config.shouldStateChange()){
			return;
		}

		if(!this.state.open){
			this.setState({hoverVictim: !this.state.hoverVictim});
		}
		this.setDropdownState(!this.state.open);
	},
	handleMouseOver: function() {
		this.setState({
			hoverVictim: !this.state.hoverVictim
		});
	},
	handleMouseOut: function() {
		this.setState({
			hoverVictim: !this.state.hoverVictim
		});
	},
	componentDidUpdate: function() {
		if(this.state.open && this.props.config.postUpdate && typeof this.props.config.postUpdate === "function"){
			var dropDownMenu = this.refs.dropDownMenu.getDOMNode();
			this.props.config.postUpdate.call(this, dropDownMenu);
		}
	},
	render:function(){
		if(this.state.open){
			return (
			React.createElement("div", {onClick: this.handleClick, className: this.props.config.menuClass+" "+this.props.config.menuClass+"_select", ref: 'dropDownMenu'},
				React.createElement("a", {className: "selected"},
					React.createElement("span", {className: "title " + this.props.config.titleClass}, this.props.config.title),
					React.createElement("i", {className: this.props.config.menuIconClass})
				),
				React.createElement(MenuList, {menuDropDownClass: this.props.config.menuDropDownClass, onClick: this.handleClick, itemArray: this.props.config.menuItems})
			)
			);
		}else if(this.state.hoverVictim){
			return (
			React.createElement("div", {onClick: this.handleClick, onMouseOver: this.handleMouseOver, onMouseOut: this.handleMouseOut, className: this.props.config.menuClass+" "+this.props.config.menuClass+"_hover"},
				React.createElement("a", null,
					React.createElement("span", {className: "title " + this.props.config.titleClass}, this.props.config.title),
					React.createElement("i", {className: this.props.config.menuIconClass})
				)
			)
			);
		}else{
			return (
			React.createElement("div", {onClick: this.handleClick, onMouseOver: this.handleMouseOver, className: this.props.config.menuClass},
				React.createElement("a", null,
					React.createElement("span", {className: "title " + this.props.config.titleClass}, this.props.config.title),
					React.createElement("i", {className: this.props.config.menuIconClass})
				)
			)
			);
		}
	}
});

