/************************************ iView Menu Drop Down Component for Third & Fourth Level Start *****************************************************/
var cmbviewsThird=null;
var cmbviewsForth=null;
var groupjsonid=0;
var foruthLevelid=0;
function thirdLevelMenuItem(){
	if(groupjson==null){
		$("#menuLevelDiv").css("display","none");
		return;
	}
	var thirdContentData=new Array();
	for(var i=groupjson.length-1;i>=0;i--){
		var groupNode = groupjson[i];
		thirdContentData.push({label:Cyberoam.getTranslatedMSG(groupNode.label),key:groupNode.groupjsonid});
	}
    ComboBoxConfig={menuClass:"thirdLevelMenu",menuIconClass:"",menuClassSelect:"thirdLevelMenu",menuDropDownClass:"thirdMenuDropdown",dropDownIconClass:"fa fa-chevron-down fa-1x",noSelection:"Select View",defaultSelected:groupjsonid,onChange:function(key){getSelectedThirdMenu(key);},afterAdd:"",afterDelete:"",menuItems:thirdContentData}
    cmbviewsThird =React.render(React.createElement(ComboBox, {config: ComboBoxConfig}), $("#thirdLevelMenu")[0]);
}
function getSelectedThirdMenu(key){
	if(key!=groupjsonid){
		foruthLevelid=0;
		groupjsonid=key;
		var url=fourthLevelMenuItem();
		if(url!=null){
			Cyberoam.setMainFrame(""+url+"");
		}else{
			cmbviewsForth.selectNodesByKeys("0");
			callSetMainFrame(0);
		}
	}
}
function fourthLevelMenuItem(){
	if(groupjson==null){
		$("#menuLevelDiv").css("display","none");
		return;
	}
	var childnodes=null;
	var url=null;
	var fourthContentData=new Array();
	for(var i=0;i<groupjson.length;i++){
		var groupNode = groupjson[i];
		if(groupjsonid==groupjson[i].groupjsonid){
			if(groupjson[i].hasOwnProperty("childNodes")){
				childnodes=groupNode.childNodes;
			}else{
				if(groupjson[i].hasOwnProperty("url")){
					url=groupNode.url;
				}
			}
			break;
		}
	}
	if(childnodes!=null){
		$("#fourthLevelMenu").css("display","block");
		$("#arrowicon").css("display","block");
		for(var j=0;j<childnodes.length;j++){
			if(childnodes[j].hasOwnProperty("url")){
				var url = childnodes[j].url;
				fourthContentData.push({label:Cyberoam.getTranslatedMSG(childnodes[j].label),key:j});
			}
		}
		ComboBoxConfig={menuClass:"forthLevelMenu",menuIconClass:"",menuClassSelect:"forthLevelMenu",menuDropDownClass:"thirdMenuDropdown",dropDownIconClass:"fa fa-chevron-down fa-1x",noSelection:"Select View",defaultSelected:foruthLevelid,onChange:function(key){callSetMainFrame(key);},afterAdd:"",afterDelete:"",menuItems:fourthContentData}
		waitFourthMenuDivCreation();
		//cmbviewsForth =React.render(React.createElement(ComboBox, {config: ComboBoxConfig}), $("#fourthLevelMenu")[0]);
		return null;
	}else{
		$("#fourthLevelMenu").css("display","none");
		$("#arrowicon").css("display","none");
		return url;
	}

}

function waitFourthMenuDivCreation(){
    if($("#fourthLevelMenu").length<1){
    	window.setTimeout( waitFourthMenuDivCreation, 100 );
    }else{
        cmbviewsForth =React.render(React.createElement(ComboBox, {config: ComboBoxConfig}), $("#fourthLevelMenu")[0]);
    }
};

function callSetMainFrame(key){

	foruthLevelid=key;
	for(var i=0;i<groupjson.length;i++){
		var groupNode = groupjson[i];
		if(groupjsonid==groupNode.groupjsonid){
			if(groupNode.hasOwnProperty("childNodes")){
				var childnodes=groupNode.childNodes;
				if(childnodes[foruthLevelid].hasOwnProperty("url")){
					Cyberoam.setMainFrame(""+childnodes[foruthLevelid].url+"");
				}
			}
			break;
		}
	}
}

