/********************************* More Options Control Component *******************************************************/
/* A component represented with the 'more-details' icon which reveals a dropdown containing various options.
 * This component takes two possible parameters:
 *  - enableToggle: An object containing properties used for an on/off toggle
 *  - options: An array of options to be rendered in the control.
 *
 * Each option has the following format:
 * {
 *    type: string - to indicate which icon should appear (or undefined if none)
 *    label: string - the 'Language.XXX' label to appear for this option
 *    disabled: boolean - if true, the label should be grayed out and clicks disabled
 *    handleClick: function - the handler to be called when this option is clicked
 * }
 */
MoreOptionsControl = React.createClass({
	propTypes: {
		enableToggle: React.PropTypes.object,
		options: React.PropTypes.array
	},

	mixins: [DropdownStateMixin],

	handleClick: function() {
		this.setDropdownState(!this.state.open);
	},

	render: function() {
		return React.DOM.div({className: 'policy-icon more-option-icon', onClick: this.handleClick},
			this.state.open ?
				React.createElement(MoreOptionsDropdown, { enableToggle: this.props.enableToggle, options: this.props.options }) :
				null
		);
	}
});

// This is the dropdown that is revealed when the 'MoreOptionsControl' component is clicked.
MoreOptionsDropdown = React.createClass({
	propTypes: {
		enableToggle: React.PropTypes.object,
		options: React.PropTypes.array
	},

	render: function() {
		var childNodes = [];

		if (this.props.enableToggle) {
			childNodes.push(React.createElement(MoreOptionsEnableToggle, this.props.enableToggle));
		}

		if (this.props.options) {
			this.props.options.forEach(function(option) {
				childNodes.push(React.createElement(MoreOptionsItem, option));
			});
		}

		return React.DOM.div({
			className: 'more-options-control-dropdown'
		}, childNodes);
	}
});

// This is the enable icon that appears at the top of the dropdown for MoreOptionsControl.
MoreOptionsEnableToggle = React.createClass({
	propTypes: {
		isEnabled: React.PropTypes.bool,
		handleClick: React.PropTypes.func
	},

	render: function() {
		return React.DOM.div({
			className: 'more-options-control-enable-container',
			onClick: this.props.handleClick
		},[
			React.DOM.input({
				checked: this.props.isEnabled === Cyberoam.DB.TRUE,
				type: 'checkbox'
			}),
			React.DOM.label(null,
				React.DOM.div({ className: 'small' })
			)
		]);
	}
});

// This is an item that appears in the dropdown for MoreOptionsControl.
MoreOptionsItem = React.createClass({
	propTypes: {
		type: React.PropTypes.string,
		label: React.PropTypes.string,
		disabled: React.PropTypes.bool,
		handleClick: React.PropTypes.func
	},

	getDefaultProps: function() {
		var classMap = {
			add: 'add-icon',
			clone: 'clone-icon',
			edit: 'edit-icon',
			delete: 'delete-icon'
		};

		return { classMap: classMap };
	},

	getIconClassName: function() {
		return 'policy-icon ' + this.props.classMap[this.props.type];
	},

	getOptionClassName: function() {
		if (this.props.disabled) {
			return 'more-options-control-item disabled';
		} else {
			return 'more-options-control-item';
		}
	},

	render: function() {
		var childNodes = [];

		if (this.props.type) {
			childNodes.push(React.DOM.div({ className: this.getIconClassName() }));
		}

		childNodes.push(React.DOM.a({ className: 'more-options-item-label' }, this.props.label));

		return React.DOM.div({
			onClick: this.props.disabled ? null : this.props.handleClick,
			className: this.getOptionClassName()
		}, childNodes);
	}
});

/******************************* More Options Control Component End *****************************************************/

/************************************ Manage Control Component **********************************************************/
ManageControl = React.createClass({
	propTypes: {
		controls: React.PropTypes.array,
		menuPostMount: React.PropTypes.func,
		shouldStateChange: React.PropTypes.func
	},

	render: function() {
		var childNodes = [];

		this.props.controls.forEach(function(control) {
			childNodes.push(React.createElement(ManageControlButton, {
				label: control.label,
				type: control.type,
				disabled: control.disabled,
				inactive: control.inactive,
				handleClick: control.handleClick,
				customClassName: control.customClassName,
				menuItems: control.menuItems,
				menuPostMount: this.props.menuPostMount,
				shouldStateChange: this.props.shouldStateChange
			}));
		}.bind(this));

		return React.DOM.div({className: 'expand-manage-icon-container'}, childNodes);
	}
});

ManageControlButton = React.createClass({
	propTypes: {
		customClassName: React.PropTypes.string,
		disabled: React.PropTypes.bool,
		handleClick: React.PropTypes.func,
		inactive: React.PropTypes.bool,
		label: React.PropTypes.string,
		menuItems: React.PropTypes.array,
		menuPostMount: React.PropTypes.func,
		shouldStateChange: React.PropTypes.func,
		type: React.PropTypes.string
	},

	mixins: [DropdownStateMixin],

	getDefaultProps: function() {
		var props = {disabled: false, inactive: true};
		var classMap = {
			base: 'expand-manage-icon',
			add: 'add-icon',
			clone: 'clone-icon',
			edit: 'edit-icon',
			remove: 'delete-icon',
			inactive: 'inactive-icon',
			disabled: 'disabled-icon'
		};

		props.classMap = classMap;
		return props;
	},

	render: function() {
		var childNodes = [];
		var props = {
			className: this.buildClassName(),
			title: this.props.label,
			onClick: (this.props.handleClick ? this.props.handleClick : this.handleClick)
		};

		if (this.props.disabled) {
			delete props.onClick;
		}

		if (this.state.open &&
			Array.isArray(this.props.menuItems)) {
			childNodes.push(React.createElement(ManageControlMenu, {
				menuItems: this.props.menuItems,
				menuPostMount: this.props.menuPostMount
			}));
		}

		return React.DOM.div(props, childNodes);
	},

	handleClick: function() {
		if (this.props.shouldStateChange &&
			typeof this.props.shouldStateChange === "function" &&
			!this.props.shouldStateChange()) {
			return;
		}

		this.setDropdownState(!this.state.open);
	},

	buildClassName: function() {
		var className = this.props.classMap.base + ' ' + this.props.classMap[this.props.type];

		if (this.props.disabled) {
			className += ' ' + this.props.classMap.disabled;
		}

		if (this.props.inactive) {
			className += ' ' + this.props.classMap.inactive;
		}

		if (this.props.customClassName) {
			className += ' ' + this.props.customClassName;
		}

		return className;
	}
});

ManageControlMenu = React.createClass({
	displayName: 'ManageControlMenu',

	propTypes: {
		menuItems: React.PropTypes.array,
		menuPostMount: React.PropTypes.func
	},

	render: function() {
		var childNodes = [];
		var className = 'security-policy-popup-item';

		this.props.menuItems.forEach(function(menuItem) {
			childNodes.push(React.DOM.div({
				className: className,
				onClick: menuItem.handleClick
			}, menuItem.label));
		});

		return React.DOM.div({className: 'security-policy-add-popup', ref: 'manageControlMenu'}, childNodes);
	},

	componentDidMount: function() {
		if (typeof this.props.menuPostMount === "function") {
			this.props.menuPostMount.call(this, this.refs.manageControlMenu.getDOMNode(), this.constructor.displayName);
		}
	}
});

/************************************ OverlayMessage Component **********************************************************/

OverlayMessage = React.createClass({
	propTypes: {
		shouldShowMessage: React.PropTypes.func
	},

	render: function() {
		var childNodes = [];
		var overlayProps;

		if (this.props.shouldShowMessage &&
			typeof this.props.shouldShowMessage === "function" &&
			this.props.shouldShowMessage()) {
			childNodes.push(React.DOM.i({key: 'overlay-icon', className: 'fa fa-exclamation-circle'}));
			childNodes.push(React.DOM.div({key: 'overlay-text'}, this.props.shouldShowMessage()));

			overlayProps = {
				className: 'overlay-message security-policy-add-popup',
				title: Language.ClickHide,
				onClick: this.handleClick
			};
		}

		return React.DOM.div(overlayProps, childNodes);
	},

	handleClick: function() {
		$(this.getDOMNode()).hide();
	}
});
