/********************************* SearchBar Component ****************************/
/*
 * Renders a search bar with a magnifying glass when the value is empty,
 * an 'x' to clear the value when the value is not empty
 */
var SearchBar = React.createClass({
    displayName: 'SearchBar',

    propTypes: {
        filter: React.PropTypes.string,                  // initial search string

        maxLength: React.PropTypes.string,               // max length of the search string

        handleSearch: React.PropTypes.func.isRequired,   // invoked when Enter is clicked in the search bar
        handleClear: React.PropTypes.func.isRequired     // invoked when the clear icon is clicked
    },

    getInitialState: function() {
        return {filter: this.props.filter};
    },

    componentWillReceiveProps: function(nextProps) {
        this.setState({filter: this.truncateFilter(nextProps.filter) });
    },

    render: function() {
        var nodes = [
            React.DOM.input({
                className: 'search-bar-input',
                type: 'text',
                value: this.state.filter,
                maxLength: this.props.maxLength,
                onChange: this.onChange,
                onKeyDown: this.onKeyDown
            }),
            React.DOM.span({
                className: 'fa search-bar-icon--glass',
                onClick: this.search
            })
        ];

        if (this.state.filter) {
            nodes.push(React.DOM.span({
                className: 'fa fa-times',
                onClick: this.clearSearch
            }));
        }

        return React.DOM.div({className: 'search-bar'}, nodes);
    },

    truncateFilter: function(filter) {
        if (!this.props.maxLength) {
            return filter;
        }

        return filter ? filter.substring(0, this.props.maxLength) : '';
    },

    onChange: function(e) {
        this.setState({filter: e.target.value});
    },

    onKeyDown: function(e) {
        if (e.keyCode === 13) {
            this.props.handleSearch(e.target.value);
        }
    },

    search: function(e) {
        this.props.handleSearch(e.target.parentElement.children[0].value);
    },

    clearSearch: function() {
        this.setState({filter: ''});
        this.props.handleClear();
    }
});

/********************************* SearchBar Component End ****************************/

/************************* Global banner component ********************************** */
/*
Configurable properties
-----------------------
tyep: success/info/warn/error
size: large/medium
text: String
	String that you want to show in banner
html: HTML String, not applicable if 'text' property is provided.
	HTML that you want to dispay in banner. Use 'text' property insted 'html'if banner stirng is plain text.
	If HTML you supply, having any user controled content then make sure to properly HTML encode it to prevent XSS.
closeable: true/false
onClose: funcation that you want to execute on banner close action.

Usage exmaple
-------------
React.render(React.createElement(Banner, {
				type : 'info',
				html : 'Hello <b>world</b>',
				closeable : true,
				onClose : function() { //custom funcation}
			}), <Dom Element> );
 */
var Banner = React.createClass({
	displayName: 'Banner',
	propTypes: {
		type: React.PropTypes.string,
		size: React.PropTypes.string,
		text: React.PropTypes.string,
		html: React.PropTypes.string,
		closeable: React.PropTypes.bool,
		onClose: React.PropTypes.func,
	},
	getInitialState: function () {
		return {};
	},

	onClose: function() {
		this.props.onClose();
	},

	render: function() {
		var types = {
			success:{ icon:"fa fa-lg fa-check-circle", css:'banner--type-success' },
			info: { icon:"fa fa-lg fa-info-circle", css:'banner--type-info' },
			warn: { icon:"fa fa-lg fa-exclamation-circle", css:'banner--type-warn' },
			error: { icon:"fa fa-lg fa-exclamation-triangle", css:'banner--type-error' },
		};
		var sizes = {
			large:'banner--size-large',
			medium:'banner--size-medium'
		}
		var size = 'large';
		if(this.props.size != undefined){
			size = this.props.size;
		}

		var nodes = [];
		nodes.push(React.DOM.div({key:'banner-icon', className: types[this.props.type]['icon'] + ' banner__icon'}));
		if(this.props.text != undefined){
			nodes.push(React.DOM.div({key:'banner-text', className: 'banner__text'}, this.props.text));
		} else if (this.props.html != undefined){
			// nosemgrep banner content will be setup by 3rd party
			nodes.push(React.DOM.div({key:'banner-text', className: 'banner__text', dangerouslySetInnerHTML: { __html: this.props.html}}));
		}
		if (this.props.closeable){
			nodes.push(React.DOM.div({key:'banner-close-btn', className: 'fa fa-times banner__close-btn', onClick: this.onClose }));
		}
		return React.DOM.div({key:'banner', className: 'banner '+ sizes[size]+ ' '+types[this.props.type]['css']}, nodes);
	}
});
/************************* Global banner end ********************************** */
