Cyberoam.MS_DataItem=React.createClass({displayName: "MS_DataItem",
	handleClick:function(event){
		if(event.target.tagName.toLowerCase() == "i" && event.target.className=="fa fa-pencil"){
			event.stopPropagation();
			this.props.handleAddEditEntityClick(event,this.props.dataKey,"data");
		}else{
			if(event.target.tagName.toLowerCase() == "i")
			event.stopPropagation();
			this.props.handleClick(event,this.props.dataKey);
		}
	},
	//start - default hover function of widget
	customOver: function (e) {
		var timer;
		var id = this.props.dataKey;
		var object = this.props.config.objectTooltip;
		var entity = object.entity;
		var target = e.target;
		var label = this.props.viewLabel;
		timer = setTimeout(function() {
			if (object.customTooltips && object.customTooltips[id]) {
				Cyberoam.showTooltip({data: object.customTooltips[id]}, target);
			} else if ((label != "Any") && (label != "Any IPv4")) {
				Cyberoam.showTooltipByMode({mode:Modes.TOOLTIP_REQUEST, id:id, entity:entity}, target);
			}
		}, 480);
		target.onmouseout = function(){clearTimeout(timer);timer=null;}
	},
	onMouseOverShowTooltip: function (e) {
			var key = this.props.dataKey;
			var category = this.props.categoryKey;
			var value = this.props.viewLabel;
            var data = this.props.config.objectTooltip.tooltipDataProvider(key,value,category);
            Cyberoam.showTooltip({'data':data}, e.target);
		},
	//end - default hover function of widget
	//creating json for tooltip support on hover of widget
	render: function() {
		var categoryData=this.props.config.category;
		var checkboxid="chk"+this.props.dataKey;
		var row = [];
		var elemJsn = {"key": "span"+this.props.dataKey, "title": this.props.viewLabel};
        if(this.props.config.objectTooltip) {
        	delete elemJsn["title"];
        	if(this.props.config.objectTooltip.tooltipDataProvider){
                elemJsn['onMouseOver']=this.onMouseOverShowTooltip;
        	}else{
                elemJsn['onMouseOver']=this.customOver;
        	}
        }
		var isChecked=(this.props.currentSelecectedItems[this.props.dataKey] != undefined)?true:false;
		row.push(React.createElement(Cyberoam.MS_CheckBox, {key: "checkbox"+this.props.dataKey, dataKey: this.props.dataKey, isChecked: isChecked}));
		if (this.props.config.displayImages) {
                        var image = this.props.config.itemImage ? this.props.config.itemImage : this.props.config.typeImages[this.props.categoryKey];
			row.push(React.createElement("span", {key: "span_img"+this.props.dataKey, style: {width: "24px"}}, React.createElement("img", {style: {height:"24px"}, src: image})));
			row.push(React.createElement("span", {key: "span"+this.props.dataKey, title: this.props.viewLabel, style: {marginLeft: "10px", width: "172px", paddingBottom: "7px"}}, this.props.viewLabel));
		} else {
			row.push(React.createElement("span", elemJsn, this.props.viewLabel));
		}
		var defaultCategory=this.props.categoryKey;
		if(this.props.config.categoryLength == 1 && this.props.categoryKey == undefined){
			for(var i in this.props.config.category) {
				if (this.props.config.category.hasOwnProperty(i)) {
					defaultCategory = i;
				}
			}
		}
		if(!Cyberoam.isCCC && (categoryData != undefined && categoryData[defaultCategory] && categoryData[defaultCategory].editURL != undefined && categoryData[defaultCategory].editURL != "") && (this.props.isDefaultOption == undefined || this.props.isDefaultOption != true)){
			if(this.props.currentSelecectedItems["Any"] == undefined){
				row.push(React.createElement("i", {key: "edit"+this.props.dataKey, className: "fa fa-pencil", onClick: this.handleClick}));
			}else{
				row.push(React.createElement("i", {key: "edit"+this.props.dataKey, className: "fa fa-pencil"}));
			}
		}
		if(this.props.currentSelecectedItems["Any"] == undefined || this.props.dataKey == "Any" || this.props.config.bypassSelectedAny){
			return(React.createElement("li", {onClick: this.handleClick}, row))
		}else{
			return(React.createElement("li", {className: "disabled"}, row))
		}
	}
});

Cyberoam.MS_DataContainer=React.createClass({displayName: "MS_DataContainer",
    handleClick:function(event,selectedDataKey){
		this.props.handleDataSelection(event,selectedDataKey)
	},
	handleAddEditEntityClick:function(event,selectedItem,passedType){
		this.props.handleAddEditEntityClick(event,selectedItem,passedType);
	},
	render:function(){
		var rowData=[];
		if(this.props.config.defaultOption != undefined){
			for(var i in this.props.config.defaultOption) {
				if (this.props.config.defaultOption.hasOwnProperty(i)) {
					rowData.push(React.createElement(Cyberoam.MS_DataItem, {
						config: this.props.config,
						viewLabel: this.props.config.defaultOption[i].label,
						handleAddEditEntityClick: this.handleAddEditEntityClick,
						categoryKey: this.props.config.defaultOption[i].type,
						isDefaultOption: true,
						dataKey: i,
						key: i,
						handleClick: this.handleClick,
						isSelectAllChecked: this.props.isSelectAllChecked,
						currentSelecectedItems: this.props.currentSelecectedItems
					}));
				}
			}
		}
		if (this.props.config.sortItems) {
			var keys = [];
			Object.keys(this.props.previewData).forEach(function(key) {
				keys.push(key);
			});

			if (this.props.config.sortData && typeof this.props.config.sortData === 'function') {
				keys = this.props.config.sortData(keys);
			} else {
				keys.sort();
			}
			$.each(keys, jQuery.proxy(function(index, value) {
				rowData.push(React.createElement(Cyberoam.MS_DataItem, {
					config: this.props.config,
					viewLabel: this.props.previewData[value].label,
					handleAddEditEntityClick: this.handleAddEditEntityClick,
					categoryKey: this.props.previewData[value].type,
					dataKey: value,
					key: value, handleClick: this.handleClick,
					currentSelecectedItems: this.props.currentSelecectedItems
				}));
			}, this));
		} else {
			for(var i in this.props.previewData) {
				if (this.props.previewData.hasOwnProperty(i)) {
					rowData.push(React.createElement(Cyberoam.MS_DataItem, {
						config: this.props.config,
						viewLabel: this.props.previewData[i].label,
						handleAddEditEntityClick: this.handleAddEditEntityClick,
						categoryKey: this.props.previewData[i].type,
						dataKey: i,
						key: i,
						handleClick: this.handleClick,
						currentSelecectedItems: this.props.currentSelecectedItems
					}));
				}
			}
		}
		rowData = Cyberoam.languageNeutralSort(rowData, 'props.viewLabel', 'Any');
		return(React.createElement("li", {className: "CNS-multi-selector-data-list"}, React.createElement("ul", null, rowData)));
	}
});
Cyberoam.MS_SelectAllDataItem=React.createClass({displayName: "MS_SelectAllDataItem",
	getInitialState: function() {
	return({isSelectAllChecked:false});
	},
	handleSelectAll:function(event){
		this.props.handleSelectAll(event,!this.state.isSelectAllChecked,this.props.previewData)
		this.setState({isSelectAllChecked:!this.state.isSelectAllChecked});
	},
	render:function(){
		if(this.props.currentSelecectedItems["Any"] == undefined){
			return(React.createElement("li", {className: "select-all-option", key: "selectAllOption", onClick: this.handleSelectAll}, React.createElement(Cyberoam.MS_CheckBox, {dataKey: "selectAllOption", isChecked: this.state.isSelectAllChecked}), React.createElement("span", null, Language.SelectAll)));
		}else{
			return(React.createElement("li", {className: "select-all-option", key: "selectAllOption"}, React.createElement(Cyberoam.MS_CheckBox, {dataKey: "selectAllOption", isChecked: this.state.isSelectAllChecked}), React.createElement("span", null, Language.SelectAll)));
		}
	}
})
Cyberoam.MS_addItemList=React.createClass({displayName: "MS_addItemList",
	getInitialState: function() {
		var initialFilteredCategory="";
		var filteredCategory="";
		var totalCategory=0;
		totalSelectedItem=0;
		var currentSelecectedItems={};
		if(this.props.selectedItems["Any"] != undefined){
			currentSelecectedItems["Any"]={};
			totalSelectedItem++;
		}
		if(this.props.config.category != undefined){
			for(var i in this.props.config.category) {
				if (this.props.config.category.hasOwnProperty(i)) {
					totalCategory++;
					initialFilteredCategory = i;
				}
			}
		}
		if(totalCategory == 1){
			filteredCategory=initialFilteredCategory;
		}
		if(!filteredCategory && this.props.config.defaultCategory){
			filteredCategory=this.props.config.defaultCategory;
		}
		if(typeof this.props.config.getInitialFilteredCategory === 'function'){
			filteredCategory = this.props.config.getInitialFilteredCategory();
		}
		this.props.config["categoryLength"]=totalCategory;
		return ({filteredCategory:filteredCategory,categoryLength:totalCategory,searchCriteria:"",currentSelectedKey:"",isSelectAllChecked:false,currentSelecectedItems:currentSelecectedItems,totalSelectedItem:totalSelectedItem})
	},
	handleDataSelection:function(event,selectedDataKey){
		var selectedItemList=this.state.currentSelecectedItems;
		var totalSelectedItem=this.state.totalSelectedItem;
		if(selectedItemList[selectedDataKey] == undefined){
			selectedItemList[selectedDataKey]={};
			totalSelectedItem++;
		}else{
			delete selectedItemList[selectedDataKey];
			totalSelectedItem--;
		}
		this.setState({currentSelecectedItems:selectedItemList,totalSelectedItem:totalSelectedItem});
		//this.props.handleDataSelection(event,selectedDataKey);
	},
	handleClick:function(event,selectedCat){
		this.setState({filteredCategory:selectedCat});
	},
	handleSearch:function(event){
		searchValue=event.target.value;
		currentObject=this;
		if(currentObject.searchInterval != null)
			clearTimeout(currentObject.searchInterval);
		currentObject.searchInterval = setTimeout(function(){currentObject.setState({searchCriteria:searchValue});},500);
	},
	handleSelectAll:function(event,selectAllState,previewedRecords){
		var selectedItemList=this.state.currentSelecectedItems;
		var totalSelectedItem=this.state.totalSelectedItem;
			for(var i in previewedRecords){
				if(selectedItemList[i] == undefined && selectAllState){
					selectedItemList[i]={};
					totalSelectedItem++;
				}else if(selectedItemList[i] != undefined && !selectAllState){
					delete selectedItemList[i];
					totalSelectedItem--;
				}
			}

		this.setState({isSelectAllChecked:!selectAllState,currentSelecectedItems:selectedItemList,totalSelectedItem:totalSelectedItem});
	},
	handleApplyClick:function(event){
		this.props.handleDataSelection(event,this.state.currentSelecectedItems);
		this.setState({currentSelecectedItems:{},totalSelectedItem:0});
	},
	clearSearch:function(event){
		//React.findDOMNode(this.refs.searchText).value="";
		if(this.props.config.isSearchBox)
			this.refs.searchText.getDOMNode().value="";
		this.setState({searchCriteria:""});
	},componentDidMount:function(){
		if(this.props.config.isSearchBox)
			this.refs.searchText.getDOMNode().focus();
		var dataListObj=this.refs.dataList.getDOMNode();
		if(dataListObj){
			var clientHeight = document.documentElement.clientHeight;
			var curObjHeight=dataListObj.offsetHeight;
			var curObjPos=$(dataListObj).offset();
			var offsetParentObj=dataListObj.offsetParent;

			if(this.props.config.postMount && typeof this.props.config.postMount === 'function') {
				this.props.config.postMount.call(this, dataListObj, this.constructor.displayName);
			} else {
				if(($(window).scrollTop()+clientHeight)<(curObjHeight+curObjPos.top+70)){
					$('html, body').animate({
						scrollTop: ((curObjHeight+curObjPos.top+70)-clientHeight)
					});
				}
			}
		}
	},componentDidUpdate:function(){
		var dataListObj=this.refs.dataList.getDOMNode();
		if(dataListObj && this.props.config.postUpdate && typeof this.props.config.postUpdate === 'function') {
			this.props.config.postUpdate.call(this, dataListObj, this.constructor.displayName);
		}
	},
	handleAddEditEntityClick:function(event,selectedCat,passedType){
		this.props.handleAddEditEntityClick(event,selectedCat,passedType);
	},
	render:function(){
		var rows = [];
		if(this.props.config.isSearchBox == undefined || this.props.config.isSearchBox==true){
			var searchtextclass="";
			if(this.state.searchCriteria != "")
				searchtextclass="fa fa-times";
			else
				searchtextclass="fa fa-search";
		    rows.push(React.createElement("li", {key: "searchBoxAsKey", className: "CNS-search-txt"}, React.createElement("input", {type: "text", onKeyUp: this.handleSearch, ref: "searchText", className: "CNSSearchTxt"}), React.createElement("i", {className: searchtextclass, onClick: this.clearSearch})));
		}
		if(this.props.config.category != undefined){
			if(this.state.categoryLength > 1){
				var filterLabel="";
				if(this.state.filteredCategory == ""){
					filterLabel=Language.Show+" : "+Language.All;
				}else{
					filterLabel=Language.ShowOnly+" : " + this.props.config.category[this.state.filteredCategory].label;
				}
				rows.push(React.createElement(Cyberoam.MS_CategorySelctionLinkContainer, {key: "MS_CategorySelctionLinkContainerAsKey", handleAddEditEntityClick: this.handleAddEditEntityClick, filteredCategory: this.state.filteredCategory, filterLabel: filterLabel, config: this.props.config, handleClick: this.handleClick}))
			}else if(this.state.categoryLength < 2 && this.props.config.category[this.state.filteredCategory].addURL != undefined && this.props.config.category[this.state.filteredCategory].addURL != ""){
				rows.push(React.createElement(Cyberoam.MS_CategorySelctionLinkContainer, {key: "MS_CategorySelctionLinkContainerAsKey", handleAddEditEntityClick: this.handleAddEditEntityClick, filteredCategory: this.state.filteredCategory, config: this.props.config}));
			}
		}

		var rowData={};
		if((this.state.filteredCategory == "" && this.state.searchCriteria == "") ||
				(this.props.config.bypassFilteredCategory && this.state.searchCriteria == "")){
			for(var i in this.props.config.data){
				if(this.props.selectedItems[i] == undefined)
					rowData[i]={label:this.props.config.data[i].label,type:this.props.config.data[i].type};
			}
		}else if(this.state.filteredCategory != "" && this.state.searchCriteria == ""){
			for(var i in this.props.config.data){
				if(this.props.selectedItems[i] == undefined && (this.state.categoryLength == 1 || (this.props.config.data[i].type && this.state.filteredCategory == this.props.config.data[i].type))){
					rowData[i]={label:this.props.config.data[i].label,type:this.props.config.data[i].type}
				}
			}
		}else if((this.state.filteredCategory == "" && this.state.searchCriteria != "") ||
					(this.props.config.bypassFilteredCategory && this.state.searchCriteria != "")){
			for(var i in this.props.config.data){
				if (typeof this.props.selectedItems[i] === 'undefined'){
					if( this.props.config.data[i].label.toLowerCase().indexOf(this.state.searchCriteria.toLowerCase()) >= 0){
						rowData[i]={label:this.props.config.data[i].label,type:this.props.config.data[i].type}
					}
					if(typeof this.props.config.searchableItems !== 'undefined') {
						var that = this;
						this.props.config.searchableItems.forEach(function(searchKey){
							if( that.props.config.data[i].hasOwnProperty(searchKey) ) {
								var searchValue = that.props.config.data[i][searchKey];
								if(typeof searchValue !==  'string'){
									searchValue = '' + searchValue; //casting non 'String' values to string
								}
								if(searchValue.toLowerCase().indexOf(that.state.searchCriteria.toLowerCase()) >= 0){
									rowData[i]={label:that.props.config.data[i].label,type:that.props.config.data[i].type}
								}
							}
						});
					}
				}
			}
		}else{
			for(var i in this.props.config.data){
				if(this.props.selectedItems[i] == undefined
					&& (this.state.categoryLength == 1 || (this.props.config.data[i].type && this.state.filteredCategory == this.props.config.data[i].type))) {
					if(this.props.config.data[i].label.toLowerCase().indexOf(this.state.searchCriteria.toLowerCase()) >= 0) {
						rowData[i]={label:this.props.config.data[i].label,type:this.props.config.data[i].type}
					}
					if(typeof this.props.config.searchableItems !== 'undefined') {
						var that = this;
						this.props.config.searchableItems.forEach(function(searchKey) {
							if(that.props.config.data[i].hasOwnProperty(searchKey)) {
								var searchValue = that.props.config.data[i][searchKey];
								if(typeof searchValue !==  'string'){
									searchValue = '' + searchValue; //casting non 'String' values to string
								}
								if(searchValue.toLowerCase().indexOf(that.state.searchCriteria.toLowerCase()) >= 0){
									rowData[i]={label:that.props.config.data[i].label,type:that.props.config.data[i].type}
								}
							}
						});
					}
				}
			}
		}
		if(this.props.config.isSelectAll != undefined && this.props.config.isSelectAll == true){
			rows.push(React.createElement(Cyberoam.MS_SelectAllDataItem, {key: "selectAllOption", handleSelectAll: this.handleSelectAll, dataKey: "selectAllOption", isChecked: this.state.isSelectAllChecked, previewData: rowData, currentSelecectedItems: this.state.currentSelecectedItems}));
		}
		rows.push(React.createElement(Cyberoam.MS_DataContainer, {key: "MS_DataContainerAsKey", handleAddEditEntityClick: this.handleAddEditEntityClick, handleDataSelection: this.handleDataSelection, config: this.props.config, previewData: rowData, selectedItems: this.props.selectedItems, currentSelecectedItems: this.state.currentSelecectedItems}));

		if(this.state.totalSelectedItem != 0){
			var customMessage="";
			if(this.state.currentSelecectedItems["Any"] == undefined){
				customMessage = Language.ApplySelectedItem.replace("{number}", this.state.totalSelectedItem);
			}else if(this.props.config.defaultOption && this.props.config.defaultOption.Any){
				customMessage = Language.ApplyAnySelectedItem.replace("{any}", this.props.config.defaultOption["Any"].label);
			}else{
				customMessage = Language.ApplyAnySelectedItemDefault;
			}
			rows.push(React.createElement("li", {key: "addSelectedItemsList", className: "add-selected-item", onClick: this.handleApplyClick}, React.createElement("span", null, customMessage)))
		}
		return (React.createElement("ul", {className: "CNS-multi-selector-list", ref: "dataList"}, rows));
	}
});
